-- Senaryo zenginleştirme (Claude API)
BEGIN;

UPDATE public.scenarios SET
  briefing = '{"tr":"İstanbul Havalimanı''nda sabah walk-around inspection sırasında A320 uçağında hidrolik sızıntısı tespit edildi. Uçak AOG durumunda olduğu için Operations Control Centre''a detaylı snag report yapman ve tahmini rectification time bildirmen gerekiyor.","en":"During morning walk-around inspection at Istanbul Airport, you discovered a hydraulic leak on an A320 aircraft. The aircraft is AOG and you must provide a detailed snag report to Operations Control Centre with estimated rectification time."}'::jsonb,
  learner_role = '{"tr":"Sen İstanbul Havalimanı''nda görevli line technician olarak TC-JYA (A320) uçağının sabah muayenesini gerçekleştirdin ve sol main landing gear''da hidrolik sızıntısı tespit ettin.","en":"You are a line technician at Istanbul Airport who has completed morning inspection of TC-JYA (A320) and discovered hydraulic fluid leaking from the left main landing gear."}'::jsonb,
  objective = '{"tr":"AOG durumundaki uçağın defect''ini OCC''ye raporla, MEL applicability''yi değerlendir ve rectification plan''ı sun.","en":"Report the AOG defect to OCC, assess MEL applicability, and present rectification plan."}'::jsonb,
  key_vocabulary = '[{"term":"AOG (Aircraft on Ground)","definition_tr":"Uçağın teknik arıza nedeniyle uçuşa elverişsiz durumda olması","definition_en":"Aircraft is unserviceable and cannot operate due to technical defect"},{"term":"snag","definition_tr":"Uçakta tespit edilen teknik arıza veya kusur","definition_en":"Technical defect or fault discovered on aircraft"},{"term":"walk-around inspection","definition_tr":"Uçak etrafında yapılan görsel dış kontrol muayenesi","definition_en":"Visual external inspection conducted around the aircraft"},{"term":"MEL (Minimum Equipment List)","definition_tr":"Belirli arızalarla uçuşa izin veren ekipman listesi","definition_en":"List of equipment that may be inoperative while still allowing flight"},{"term":"deferrable","definition_tr":"Arızanın ertelenebilir/sonraya bırakılabilir olması","definition_en":"Defect that can be postponed or deferred to later maintenance"},{"term":"rectification","definition_tr":"Arızanın giderilmesi, tamir işlemi","definition_en":"Process of fixing or repairing the defect"},{"term":"hydraulic ground cart","definition_tr":"Hidrolik sistem servis ve test için kullanılan yer ekipmanı","definition_en":"Ground equipment used for servicing and testing hydraulic systems"},{"term":"pressurization test","definition_tr":"Hidrolik sistemin basınç altında test edilmesi","definition_en":"Testing hydraulic system under pressure to verify integrity"}]'::jsonb,
  estimated_duration_seconds = 150,
  turns = '[{"atcStation":"OPERATIONS CONTROL","atcUtterance":"Good morning, TC-JYA has been reported AOG. What is the nature of the defect?","correctionTr":"OCC''ye defektin ne olduğunu açıkça bildirin: ''hydraulic fluid leak'', ''left main landing gear'', ve ''walk-around inspection'' ifadelerini kullanın.","expectedReadback":"Ops Control, TC-JYA has hydraulic fluid leak on left main landing gear, discovered during walk-around inspection","frequency":"131.8","hintTr":"Arızayı net tanımlayın - hangi sistem, hangi konum, nasıl keşfedildi.","id":"turn-1","isFinal":false,"keyPhrases":[["hydraulic","hydraulics","fluid"],["leak","leaking","leakage"],["left main","left gear","left landing gear"],["walk-around","walkaround","inspection"]],"hint":{"text_tr":"OCC''ye arızayı net bir şekilde tanımla: hangi sistem (hydraulic), nerede (left main landing gear), nasıl keşfedildi (walk-around inspection). ICAO standart terminoloji kullan.","text_en":"Clearly describe the defect to OCC: which system (hydraulic), where (left main landing gear), how discovered (walk-around inspection). Use ICAO standard terminology."},"expected_response":{"text_en":"Operations Control, TC-JYA has hydraulic fluid leak on left main landing gear, discovered during walk-around inspection","text_tr":"OCC''ye hidrolik sıvı sızıntısının sol ana iniş takımında olduğunu ve sabah muayenesinde tespit edildiğini bildir","must_include":["hydraulic","hydraulics","fluid","leak","leaking","leakage","left main","left gear","left landing gear","walk-around","walkaround","inspection"]},"vocabulary_focus":["snag","walk-around inspection","hydraulic"]},{"atcStation":"OPERATIONS CONTROL","atcUtterance":"Copy that, hydraulic leak on left main gear. Can you confirm MEL applicability and estimated time to rectify?","correctionTr":"MEL uygulanabilirliğini (''not MEL deferrable'') ve tamir süresini (''three hours'', ''spare part from warehouse'') net belirtin.","expectedReadback":"Negative, not MEL deferrable. Require hydraulic component replacement. Estimated rectification time three hours, need spare part from warehouse","frequency":"131.8","hintTr":"MEL durumunu, gerekli işlemi ve tahmini süreyi sırayla bildirin.","id":"turn-2","isFinal":false,"keyPhrases":[["negative","no","not MEL"],["not deferrable","cannot defer","not MEL deferrable"],["replacement","replace","component replacement"],["three hours","3 hours","three-hour"],["spare part","spare","warehouse","part"]],"hint":{"text_tr":"MEL durumunu değerlendir (bu arıza MEL ile ertelenebilir mi?), sonra gerekli işlemi (component replacement) ve tahmini süreyi (three hours) açıkla. Spare part nereden gelecek?","text_en":"Assess MEL status (can this defect be deferred?), then explain required action (component replacement) and estimated time (three hours). Where will spare part come from?"},"expected_response":{"text_en":"Negative, not MEL deferrable. Require hydraulic component replacement. Estimated rectification time three hours, need spare part from warehouse","text_tr":"Arızanın MEL ile ertelenemeyeceğini, hidrolik parça değişimi gerektiğini, tahmini üç saat süreceğini ve depoden yedek parça lazım olduğunu belirt","must_include":["negative","no","not mel","not deferrable","cannot defer","replacement","replace","component","three hours","3 hours","spare part","spare","warehouse","part"]},"vocabulary_focus":["MEL","deferrable","rectification"]},{"atcStation":"OPERATIONS CONTROL","atcUtterance":"Roger, three-hour rectification with warehouse spare required. Will you need any additional support or tooling for the repair?","correctionTr":"İhtiyacınız olan ekipmanı (''hydraulic ground cart'') ve destek personeli (''additional technician'', ''pressurization test'') açıkça talep edin.","expectedReadback":"Affirmative, request hydraulic ground cart and one additional technician for system pressurization test after repair","frequency":"131.8","hintTr":"Test için gerekli ekipman ve ek personel ihtiyacını bildirin.","id":"turn-3","isFinal":true,"keyPhrases":[["affirmative","affirm","yes","positive"],["hydraulic ground cart","ground cart","cart"],["additional technician","one technician","another technician","extra technician"],["pressurization test","system test","pressure test","test"]],"hint":{"text_tr":"Tamir sonrası sistem testi için gerekli ekipmanı (hydraulic ground cart) ve ek personeli (additional technician for pressurization test) talep et. Net ve profesyonel ifade kullan.","text_en":"Request necessary equipment (hydraulic ground cart) and additional personnel (additional technician for pressurization test) for post-repair system testing. Use clear and professional language."},"expected_response":{"text_en":"Affirmative, request hydraulic ground cart and one additional technician for system pressurization test after repair","text_tr":"Tamir sonrası sistem basınç testi için hidrolik yer ekipmanı ve bir ek teknisyen talep ettiğini onayla","must_include":["affirmative","affirm","yes","positive","hydraulic ground cart","ground cart","cart","additional technician","one technician","another technician","extra technician","pressurization test","system test","pressure test","test"]},"vocabulary_focus":["hydraulic ground cart","pressurization test","rectification"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'aog-hydraulic-snag-report-ops';

UPDATE public.scenarios SET
  briefing = '{"tr":"İstanbul Havalimanı''nda TK1453 Londra seferinin departure hazırlığı devam ediyor. Load supervisor aft cargo compartment kapasitesi ve weight & balance ayarlaması için seni frequency''de arıyor.","en":"Flight TK1453 to London is in departure preparation at Istanbul Airport. The load supervisor is calling you on frequency regarding aft cargo compartment capacity and weight & balance adjustments."}'::jsonb,
  learner_role = '{"tr":"Sen TK1453 uçağının ramp agent''ısın ve baggage loading coordination sorumluluğundasın.","en":"You are the ramp agent for TK1453 responsible for baggage loading coordination."}'::jsonb,
  objective = '{"tr":"Load supervisor ile aft ve forward compartment''lardaki bagaj yükleme değişikliklerini koordine et ve doğru ICAO phraseology kullan.","en":"Coordinate baggage loading changes in aft and forward compartments with load supervisor using correct ICAO phraseology."}'::jsonb,
  key_vocabulary = '[{"term":"aft compartment","definition_tr":"Uçağın arkasındaki bagaj bölmesi","definition_en":"Rear cargo hold of the aircraft"},{"term":"forward compartment","definition_tr":"Uçağın ön kısmındaki bagaj bölmesi","definition_en":"Front cargo hold of the aircraft"},{"term":"weight and balance","definition_tr":"Uçağın ağırlık ve denge hesaplaması","definition_en":"Aircraft weight distribution calculation"},{"term":"stand by","definition_tr":"Bekleyin, kontrol ediyorum anlamında kullanılan standart ifade","definition_en":"Standard phrase meaning wait while I check"},{"term":"wilco","definition_tr":"Will comply - talimatı anlayıp uygulayacağım anlamında","definition_en":"Will comply - I understand and will execute the instruction"},{"term":"offload","definition_tr":"Uçaktan bagaj veya kargo çıkarmak","definition_en":"To remove baggage or cargo from aircraft"},{"term":"load supervisor","definition_tr":"Uçak yükleme operasyonlarından sorumlu görevli","definition_en":"Person responsible for aircraft loading operations"},{"term":"advise when complete","definition_tr":"İşlem bittiğinde haber ver","definition_en":"Report back when the task is finished"}]'::jsonb,
  estimated_duration_seconds = 150,
  turns = '[{"atcStation":"LOAD SUPERVISOR","atcUtterance":"Ramp, Load. We have fifteen additional bags for TK1453. Can you confirm aft cargo compartment has space available?","correctionTr":"Load süpervisörüne ''stand by'' diyerek 15 bagaj için aft compartment kapasitesini kontrol edeceğinizi bildirin.","expectedReadback":"Load, Ramp. Stand by, checking aft compartment capacity for fifteen bags.","frequency":"131.7","hintTr":"Önce beklemesini isteyin, sonra neyi kontrol edeceğinizi söyleyin.","id":"turn-1","isFinal":false,"keyPhrases":[["stand by","standby","wait"],["checking","check","verifying"],["aft compartment","aft cargo","rear compartment"],["fifteen bags","15 bags","one five bags"]],"hint":{"text_tr":"Önce ''stand by'' diyerek beklemesini iste, sonra 15 bagaj için aft compartment kapasitesini kontrol edeceğini belirt.","text_en":"First say ''stand by'' to ask them to wait, then state you''ll check aft compartment capacity for 15 bags."},"expected_response":{"text_en":"Load, Ramp. Stand by, checking aft compartment capacity for fifteen bags.","text_tr":"Load''a hitap et, stand by de ve 15 bagaj için aft compartment kapasitesini kontrol edeceğini söyle.","must_include":["stand by","standby","checking","check","aft compartment","aft cargo","fifteen","15","one five"]},"vocabulary_focus":["stand by","aft compartment","capacity"]},{"atcStation":"LOAD SUPERVISOR","atcUtterance":"Ramp, roger. Also, we need to offload two pieces from forward compartment due to weight and balance. Confirm when ready.","correctionTr":"Load süpervisörüne talimatı anladığınızı (wilco), forward compartment''tan 2 bagaj çıkaracağınızı ve bitince haber vereceğinizi söyleyin.","expectedReadback":"Load, wilco. We''ll offload two bags from forward compartment and advise when complete.","frequency":"131.7","hintTr":"Wilco kullanın, hangi bölmeden kaç bagaj çıkaracağınızı ve ne zaman bildireceğinizi söyleyin.","id":"turn-2","isFinal":false,"keyPhrases":[["wilco","will comply","roger"],["offload","remove","unload"],["two bags","two pieces","2 bags"],["forward compartment","forward cargo","front compartment"],["advise","inform","report"]],"hint":{"text_tr":"Wilco kullanarak talimatı kabul et, forward compartment''tan 2 bagaj çıkaracağını (offload) ve bitince haber vereceğini (advise) söyle.","text_en":"Use wilco to acknowledge, state you''ll offload 2 bags from forward compartment and advise when complete."},"expected_response":{"text_en":"Load, wilco. We''ll offload two bags from forward compartment and advise when complete.","text_tr":"Wilco de, forward compartment''tan 2 bagaj çıkaracağını ve bitince bildireceğini söyle.","must_include":["wilco","will comply","offload","remove","two","2","forward compartment","forward cargo","advise","complete"]},"vocabulary_focus":["wilco","offload","forward compartment","advise"]},{"atcStation":"LOAD SUPERVISOR","atcUtterance":"Ramp, understood. Please coordinate with baggage handler and call me back on this frequency when loading is complete.","correctionTr":"Baggage handler ile koordine olacağınızı ve yükleme bitince 131.7''de rapor edeceğinizi onaylayın.","expectedReadback":"Roger, Load. Will coordinate with baggage handler and report back when loading complete on one three one decimal seven.","frequency":"131.7","hintTr":"Roger ile başlayın, kiminle koordine olacağınızı ve hangi frekansta geri döneceğinizi söyleyin.","id":"turn-3","isFinal":true,"keyPhrases":[["roger","wilco","affirm"],["coordinate","work with","contact"],["baggage handler","handler","baggage team"],["report back","call back","advise"],["loading complete","complete","finished"],["one three one decimal seven","131.7","this frequency"]],"hint":{"text_tr":"Roger de, baggage handler ile koordine olacağını belirt ve yükleme bitince 131.7 frequency''sinde geri dönüş yapacağını söyle.","text_en":"Say roger, confirm coordination with baggage handler and report back on 131.7 when loading is complete."},"expected_response":{"text_en":"Roger, Load. Will coordinate with baggage handler and report back when loading complete on one three one decimal seven.","text_tr":"Roger de, baggage handler ile koordine olacağını ve yükleme bitince 131.7''de rapor edeceğini söyle.","must_include":["roger","coordinate","baggage handler","handler","report","loading complete","complete","one three one decimal seven","131.7"]},"vocabulary_focus":["coordinate","baggage handler","report back","frequency"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'baggage-loading-coordination-b1';

UPDATE public.scenarios SET
  briefing = '{"tr":"İstanbul Havalimanı''nda yoğun trafik var. Pushback sonrası runway 35L''e taxi yapacak, yolda traffic separation uygulayacaksınız.","en":"Busy traffic at Istanbul Airport. After pushback, you will taxi to runway 35L and practice traffic separation procedures."}'::jsonb,
  learner_role = '{"tr":"Sen Turkish 1453 callsign''lı Boeing 737''de first officer olarak ground kontrolü ile iletişim kuruyorsun.","en":"You are the first officer on Turkish 1453, a Boeing 737, communicating with ground control."}'::jsonb,
  objective = '{"tr":"Ground kontrolünün taxi clearance ve traffic talimatlarını doğru readback yaparak uygula.","en":"Correctly readback and follow ground control''s taxi clearance and traffic instructions."}'::jsonb,
  key_vocabulary = '[{"term":"taxi clearance","definition_tr":"Kontrol kulesinin uçağa taxiway''lerde hareket izni vermesi","definition_en":"Permission from control tower for aircraft to move on taxiways"},{"term":"holding point","definition_tr":"Runway''e girmeden önce bekleme noktası","definition_en":"Designated position where aircraft hold before entering runway"},{"term":"readback","definition_tr":"ATC talimatını pilot tarafından tekrar ederek doğrulama","definition_en":"Pilot''s repetition of ATC instruction to confirm understanding"},{"term":"hold short","definition_tr":"Belirtilen noktadan önce durup beklemek","definition_en":"Stop and wait before a specified point"},{"term":"give way","definition_tr":"Başka bir uçağa öncelik/geçiş hakkı vermek","definition_en":"Yield right of way to another aircraft"},{"term":"traffic","definition_tr":"Havaalanında veya havada diğer uçaklar","definition_en":"Other aircraft in the airport or airspace"},{"term":"via","definition_tr":"Belirtilen rota veya taxiway üzerinden gitmek","definition_en":"Proceed by way of specified route or taxiway"},{"term":"contact tower","definition_tr":"Tower frekansına geçip iletişim kurmak","definition_en":"Switch to and communicate with tower frequency"}]'::jsonb,
  estimated_duration_seconds = 180,
  turns = '[{"atcStation":"ISTANBUL GROUND","atcUtterance":"Turkish 1453, taxi to holding point runway 35L via taxiway B and A.","correctionTr":"Ground kontrolü size taxi rotasını verdi. Readback yaparken route''u tekrar edin: taxiway B, sonra A, runway 35L holding point''e kadar. Call sign''ınızı da ekleyin.","expectedReadback":"Taxi to holding point runway 35L via taxiway B and A, Turkish 1453.","frequency":"121.9","hintTr":"İyi başlangıç! Ground talimatlarını eksiksiz tekrar edin.","id":"turn-1","isFinal":false,"keyPhrases":[["taxi","taxiing"],["holding point","holding"],["runway 35L","35L"],["taxiway B","via B"],["taxiway A","and A","via A"],["Turkish 1453","1453"]],"hint":{"text_tr":"Ground size taxi rotası veriyor. Route''u sırayla tekrar edin: taxiway B, sonra A kullanarak runway 35L holding point''e kadar. Callsign''ı unutmayın.","text_en":"Ground is giving you taxi route. Readback the route in order: via taxiway B, then A to runway 35L holding point. Don''t forget callsign."},"expected_response":{"text_en":"Taxi to holding point runway 35L via taxiway B and A, Turkish 1453.","text_tr":"Taxiway B ve A üzerinden runway 35L holding point''e taxi yapacaksınız.","must_include":["taxi","holding point","runway 35l","35l","taxiway b","via b","taxiway a","and a","turkish 1453","1453"]},"vocabulary_focus":["taxi clearance","holding point","via","readback"]},{"atcStation":"ISTANBUL GROUND","atcUtterance":"Turkish 1453, hold short of taxiway C, give way to Lufthansa A320 passing left to right.","correctionTr":"Ground size başka bir uçağa yol vermenizi istedi. ''Hold short of taxiway C'' ve ''give way to Lufthansa A320'' ifadelerini readback''te kullanın. Traffic awareness önemli.","expectedReadback":"Hold short of taxiway C, give way to Lufthansa A320, Turkish 1453.","frequency":"121.9","hintTr":"Çok iyi! Son talimatı da doğru anlayın.","id":"turn-2","isFinal":false,"keyPhrases":[["hold short","holding short"],["taxiway C","C"],["give way","giving way"],["Lufthansa","A320"],["Turkish 1453","1453"]],"hint":{"text_tr":"Ground bir traffic conflict önlemek istiyor. Taxiway C''den önce durmanız ve soldan sağa geçen Lufthansa A320''ye yol vermeniz gerekiyor. Her iki talimatı da readback edin.","text_en":"Ground wants to prevent traffic conflict. You must stop before taxiway C and give way to Lufthansa A320 passing left to right. Readback both instructions."},"expected_response":{"text_en":"Hold short of taxiway C, give way to Lufthansa A320, Turkish 1453.","text_tr":"Taxiway C öncesinde durup Lufthansa A320''ye geçiş hakkı vereceksiniz.","must_include":["hold short","holding short","taxiway c","give way","giving way","lufthansa","a320","turkish 1453","1453"]},"vocabulary_focus":["hold short","give way","traffic"]},{"atcStation":"ISTANBUL GROUND","atcUtterance":"Turkish 1453, traffic is clear, continue taxi, contact tower 118.1.","correctionTr":"Ground size devam etmenizi ve Tower frekansına geçmenizi söyledi. Readback''te ''continue taxi'' ve ''contact tower 118.1'' deyin. Frekansı doğru tekrar edin.","expectedReadback":"Continue taxi, contact tower 118.1, Turkish 1453.","frequency":"121.9","hintTr":"Mükemmel! Artık Tower ile konuşmaya hazırsınız.","id":"turn-3","isFinal":true,"keyPhrases":[["continue taxi","continue","taxi"],["contact tower","tower"],["118.1","one one eight decimal one"],["Turkish 1453","1453"]],"hint":{"text_tr":"Traffic geçti, artık devam edebilirsiniz. Ground size taxi''ye devam etmenizi ve tower frekansına (118.1) geçmenizi söylüyor. Frekansı doğru tekrar edin.","text_en":"Traffic has passed, you can continue. Ground tells you to continue taxi and switch to tower frequency (118.1). Readback the frequency correctly."},"expected_response":{"text_en":"Continue taxi, contact tower 118.1, Turkish 1453.","text_tr":"Taxi''ye devam edip tower frekansı 118.1''e geçiyorsunuz.","must_include":["continue","taxi","contact tower","tower","118.1","one one eight","turkish 1453","1453"]},"vocabulary_focus":["contact tower","continue taxi","frequency"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'basic-atc-readback-taxi-clearance';

UPDATE public.scenarios SET
  briefing = '{"tr":"Turkish Airlines 1453 sefer sayılı Londra Heathrow uçuşunun boarding süreci başlıyor. Gate A12''de farklı yolcu kategorilerini sırayla çağırarak profesyonel bir PA announcement yapacaksın.","en":"Boarding process is beginning for Turkish Airlines flight 1453 to London Heathrow. You will make professional PA announcements at gate A12, calling different passenger categories in sequence."}'::jsonb,
  learner_role = '{"tr":"Sen Turkish Airlines flight 1453 sefer sayılı uçuşun cabin crew üyesisin ve gate A12''den boarding announcement''larını yapıyorsun.","en":"You are a cabin crew member for Turkish Airlines flight 1453, making boarding announcements at gate A12."}'::jsonb,
  objective = '{"tr":"Yolculara nezaketle hitap ederek boarding sürecini doğru sırayla yönet ve gerekli bilgileri açıkça ilet.","en":"Courteously address passengers, manage the boarding process in correct sequence, and clearly communicate necessary information."}'::jsonb,
  key_vocabulary = '[{"term":"boarding announcement","definition_tr":"Yolcuları uçağa binmeye davet eden kapı anons duyurusu","definition_en":"Gate announcement inviting passengers to board the aircraft"},{"term":"gate","definition_tr":"Yolcuların uçağa binmek için toplandığı kapı/geçiş noktası","definition_en":"The designated area where passengers gather to board the aircraft"},{"term":"priority boarding","definition_tr":"Küçük çocuklu aileler ve özel yardım gereken yolcular için öncelikli biniş","definition_en":"Early boarding privilege for families with small children and passengers requiring special assistance"},{"term":"business class","definition_tr":"Ekonomi sınıfından daha konforlu ve hizmet standartları yüksek olan seyahat sınıfı","definition_en":"Premium cabin class offering enhanced comfort and service standards"},{"term":"Star Alliance Gold","definition_tr":"Star Alliance sadakat programının üst düzey üyelik statüsü","definition_en":"Elite tier membership status in the Star Alliance frequent flyer program"},{"term":"boarding pass","definition_tr":"Yolcunun uçağa binme hakkını gösteren bilet/kart","definition_en":"Document or card that authorizes a passenger to board the aircraft"},{"term":"general boarding","definition_tr":"Öncelikli gruplar sonrası tüm kalan yolcuların binişi","definition_en":"Boarding process for all remaining passengers after priority groups"},{"term":"PA (Public Address)","definition_tr":"Yolculara yapılan hoparlör üzerinden genel anons","definition_en":"Public announcement made to passengers over the speaker system"}]'::jsonb,
  estimated_duration_seconds = 180,
  turns = '[{"atcStation":"CAPTAIN","atcUtterance":"Cabin crew, we are ready for boarding. Please begin the announcement for passengers at gate A12.","correctionTr":"Yolculara nezaketle hitap edin: ''Good morning/afternoon ladies and gentlemen, welcome to Turkish Airlines flight 1453 to London Heathrow'' diyerek başlayın. Ardından ''We are now ready to begin boarding at gate A12'' ve öncelikli binişi belirtin.","expectedReadback":"Good morning ladies and gentlemen. Welcome to Turkish Airlines flight 1453 to London Heathrow. We are now ready to begin boarding at gate A12. Passengers with small children and those requiring special assistance may board first.","frequency":null,"hintTr":"Profesyonel bir havayolu anonsunda nezaket ifadeleri, uçuş numarası, varış noktası ve kapi numarası mutlaka yer almalıdır.","id":"turn-1","isFinal":false,"keyPhrases":[["good morning","good afternoon","good evening","ladies and gentlemen"],["welcome","Turkish Airlines"],["flight 1453","TK 1453","Turkish 1453"],["London Heathrow","Heathrow","London"],["ready","begin boarding","commence boarding"],["gate A12","gate A 12"],["small children","children","passengers with children"],["special assistance","requiring assistance"]],"hint":{"text_tr":"İyi bir boarding announcement her zaman nezaket selamlamasıyla başlar, ardından havayolu adı, flight number, destination ve gate bilgisini içerir. Son olarak priority passengers''ı (küçük çocuklu aileler ve özel yardım gereken yolcular) ilk sıraya davet et.","text_en":"A good boarding announcement always starts with a courteous greeting, followed by airline name, flight number, destination, and gate information. Finally, invite priority passengers (families with small children and those requiring special assistance) to board first."},"expected_response":{"text_en":"Good morning ladies and gentlemen. Welcome to Turkish Airlines flight 1453 to London Heathrow. We are now ready to begin boarding at gate A12. Passengers with small children and those requiring special assistance may board first.","text_tr":"Günaydın bayanlar baylar. Turkish Airlines 1453 sefer sayılı Londra Heathrow uçuşuna hoş geldiniz. Gate A12''den binişe başlamaya hazırız. Küçük çocuklu yolcular ve özel yardıma ihtiyacı olanlar ilk sırada binebilir.","must_include":["good morning","good afternoon","good evening","ladies and gentlemen","welcome","turkish airlines","flight 1453","london heathrow","heathrow","ready","begin boarding","commence boarding","gate a12","small children","special assistance"]},"vocabulary_focus":["boarding announcement","gate","priority boarding"]},{"atcStation":"GROUND STAFF","atcUtterance":"Cabin crew, we have priority passengers ready. Should we also call business class now?","correctionTr":"Önce ''Yes'' ya da onay verin, ardından ''We may now invite business class passengers and Star Alliance Gold members to board through gate A12'' deyin. Son olarak yolcuları belge hazırlamaya davet edin: ''Please have your boarding passes and passports ready.''","expectedReadback":"Yes, we may now invite business class passengers and our Star Alliance Gold members to board through gate A12. Please have your boarding passes and passports ready.","frequency":null,"hintTr":"İş dünyası yolcularını ve sadakat programı üyelerini çağırırken nezaket ve profesyonellik önemlidir.","id":"turn-2","isFinal":false,"keyPhrases":[["yes","affirmative","correct"],["invite","call","welcome"],["business class","business"],["Star Alliance Gold","Gold members","frequent flyers"],["board","boarding"],["gate A12","gate A 12"],["boarding passes","boarding pass"],["passports","travel documents","documents"]],"hint":{"text_tr":"Priority passengers''tan sonra sıra business class yolcuları ve Star Alliance Gold members''a gelir. Onay verdikten sonra bu grupları nezaketle davet et ve boarding pass ile passport hazırlamalarını iste.","text_en":"After priority passengers, it''s time to call business class passengers and Star Alliance Gold members. Acknowledge first, then courteously invite these groups and remind them to have their boarding passes and passports ready."},"expected_response":{"text_en":"Yes, we may now invite business class passengers and our Star Alliance Gold members to board through gate A12. Please have your boarding passes and passports ready.","text_tr":"Evet, şimdi business class yolcularımızı ve Star Alliance Gold üyelerimizi gate A12''den binişe davet edebiliriz. Lütfen boarding pass''larınızı ve pasaportlarınızı hazır bulundurun.","must_include":["yes","affirmative","invite","business class","star alliance gold","gold members","board","gate a12","boarding passes","passports","travel documents","ready"]},"vocabulary_focus":["business class","Star Alliance Gold","boarding pass"]},{"atcStation":"GROUND STAFF","atcUtterance":"Understood. Business class is boarding now. Should we proceed with general boarding?","correctionTr":"Genel binişi başlatın: ''We now invite all remaining passengers holding boarding passes for flight Turkish 1453 to London Heathrow to board at gate A12.'' Düzenli binişi hatırlatın ve teşekkür edin.","expectedReadback":"Affirmative. We now invite all remaining passengers holding boarding passes for flight Turkish 1453 to London Heathrow to board at gate A12. Please proceed to the gate in an orderly manner. Thank you.","frequency":null,"hintTr":"Genel biniş çağrısında tüm yolcuları davet ederken uçuş numarası ve kapıyı tekrar belirtmek önemlidir.","id":"turn-3","isFinal":true,"keyPhrases":[["affirmative","yes","correct","roger"],["invite","call","welcome"],["all remaining passengers","remaining passengers","all passengers"],["boarding passes","boarding pass"],["flight Turkish 1453","TK 1453","Turkish 1453","flight 1453"],["London Heathrow","Heathrow"],["gate A12","gate A 12"],["orderly manner","orderly","in order"],["thank you"]],"hint":{"text_tr":"General boarding çağrısında tüm kalan yolcuları row number''larına göre sıraya davet et. Aşırı bagaj için son hatırlatma yap ve yolcuların seat assignment''larını bulmaları için yardım teklif et.","text_en":"In the general boarding call, invite all remaining passengers by row numbers. Give a final reminder about carry-on baggage and offer assistance for passengers to find their seat assignments."},"expected_response":{"text_en":"We now invite all remaining passengers holding boarding passes for flight Turkish 1453 to London Heathrow to board at gate A12. Please board according to your row numbers. Kindly ensure your carry-on baggage meets size requirements. Our crew will assist you in finding your seats.","text_tr":"Şimdi Turkish 1453 sefer sayılı Londra Heathrow uçuşu için boarding pass''i olan tüm kalan yolcuları gate A12''den binişe davet ediyoruz. Lütfen sıra numaralarınıza göre binin. El bagajlarınızın ölçü gerekliliklerine uygun olduğundan emin olun. Ekibimiz koltuklarınızı bulmanızda yardımcı olacak.","must_include":["invite","remaining passengers","boarding passes","flight 1453","turkish 1453","london heathrow","gate a12","row numbers","carry-on baggage","size requirements","crew","assist","seats"]},"vocabulary_focus":["general boarding","boarding pass","PA"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'boarding-pa-announcement-b1';

UPDATE public.scenarios SET
  briefing = '{"tr":"Turkish 1453 İstanbul Havalimanı''nda iniş yaptıktan sonra kargo bölmesinde duman tespit edildi. Kaptan taksi yolunda acil evacuation emri verdi ve sadece sol taraf kapılarının kullanılmasını istedi.","en":"After landing at Istanbul Airport, smoke was detected in the cargo hold of Turkish 1453. The captain has ordered an immediate evacuation on the taxiway using left-side doors only."}'::jsonb,
  learner_role = '{"tr":"Sen Turkish 1453 Boeing 737 uçağında Purser (Kabin Amiri) olarak ekip koordinasyonundan ve tüm yolcuların güvenli evacuate edilmesinden sorumlusun.","en":"You are the Purser on Turkish 1453, a Boeing 737, responsible for coordinating the cabin crew and ensuring all passengers evacuate safely."}'::jsonb,
  objective = '{"tr":"Kaptan''ın acil evacuation komutunu doğru şekilde tekrarla, arızalı kapıya müdahale et ve tüm yolcu/ekip sayısını raporla.","en":"Correctly acknowledge the captain''s evacuation command, manage the jammed door situation, and report final passenger and crew count."}'::jsonb,
  key_vocabulary = '[{"term":"evacuate","definition_tr":"Uçaktan acil çıkış yapmak, tahliye etmek","definition_en":"To exit the aircraft immediately in an emergency"},{"term":"purser","definition_tr":"Kabin ekibinin başı, kabin amiri","definition_en":"Chief flight attendant responsible for cabin crew coordination"},{"term":"slide deployment","definition_tr":"Acil çıkış kaydırağının açılması","definition_en":"The activation of emergency evacuation slides"},{"term":"jammed","definition_tr":"Sıkışmış, çalışmayan, arızalı","definition_en":"Stuck or inoperative, unable to function"},{"term":"headcount","definition_tr":"Kişi sayımı, yolcu ve ekip sayısının teyidi","definition_en":"Confirmation of the number of passengers and crew"},{"term":"port side","definition_tr":"Uçağın sol tarafı (pilot açısından)","definition_en":"Left side of the aircraft (from pilot perspective)"},{"term":"aft","definition_tr":"Uçağın arka kısmı","definition_en":"Rear section of the aircraft"},{"term":"forward","definition_tr":"Uçağın ön kısmı","definition_en":"Front section of the aircraft"}]'::jsonb,
  estimated_duration_seconds = 180,
  turns = '[{"atcStation":"CAPTAIN","atcUtterance":"Cabin crew, this is the captain. Evacuate, evacuate, evacuate! Doors left side only.","correctionTr":"Kaptan''ın acil tahliye emrini tekrarlamalısınız: ''Evacuate, evacuate, evacuate!'' ve sadece sol taraf kapılarının kullanılacağını onaylayın.","expectedReadback":"Evacuate, evacuate, evacuate! Doors left side only, confirmed.","frequency":null,"hintTr":"Acil durumda komut tekrarı hayati önem taşıyor.","id":"turn-1","isFinal":false,"keyPhrases":[["evacuate","evacuation"],["left side","left doors","port side"],["only","confirmed","wilco","understood"]],"hint":{"text_tr":"Kaptan''ın acil evacuation komutunu aynen tekrarlamalı ve hangi taraf kapılarının kullanılacağını teyit etmelisin.","text_en":"Repeat the captain''s evacuation command exactly and confirm which side doors will be used."},"expected_response":{"text_en":"Evacuate, evacuate, evacuate! Doors left side only, confirmed.","text_tr":"Tahliye komutunu üç kez tekrarla ve sadece sol taraf kapılarını onaylayarak cevap ver.","must_include":["evacuate","evacuation","left side","left","port","confirmed","wilco","understood","only"]},"vocabulary_focus":["evacuate","port side"]},{"atcStation":"SENIOR CABIN ATTENDANT","atcUtterance":"Purser, door 2L slide not deployed, jammed mechanism. What are your instructions?","correctionTr":"2L kapısının arızalı olduğunu kabul edin ve yolcuların 1L ve 3L kapılarına yönlendirilmesi talimatını verin.","expectedReadback":"Door 2L jammed, use doors 1L and 3L only. Redirect passengers aft and forward.","frequency":null,"hintTr":"Ekip üyelerine net alternatif rota bildirin.","id":"turn-2","isFinal":false,"keyPhrases":[["door 2L","2 left","two left"],["jammed","not deployed","inoperative"],["doors 1L","door one left","1 left"],["3L","three left","door 3 left"],["redirect","send","move passengers"]],"hint":{"text_tr":"2L kapısının arızalı olduğunu kabul et ve yolcuları alternatif çıkışlara (1L ve 3L) yönlendir. Forward ve aft yönlendirmesi ver.","text_en":"Acknowledge the malfunction at door 2L and redirect passengers to alternative exits (1L and 3L), giving forward and aft directions."},"expected_response":{"text_en":"Door 2L jammed, use doors 1L and 3L only. Redirect passengers aft and forward.","text_tr":"2L kapısının arızalı olduğunu belirt ve yolcuların 1L ile 3L''ye yönlendirilmesini söyle.","must_include":["door 2l","2 left","two left","jammed","inoperative","not deployed","1l","one left","3l","three left","redirect","aft","forward"]},"vocabulary_focus":["jammed","aft","forward","slide deployment"]},{"atcStation":"CAPTAIN","atcUtterance":"Cabin, all passengers clear of aircraft? Confirm headcount and status.","correctionTr":"Kaptan''a tüm yolcu ve ekip sayısını (187 yolcu, 6 ekip) onaylayın ve yaralanma olmadığını bildirin.","expectedReadback":"Affirmative, all 187 passengers and 6 crew evacuated safely. No injuries reported.","frequency":null,"hintTr":"Sayı ve durum raporu acil protokolün son adımıdır.","id":"turn-3","isFinal":true,"keyPhrases":[["affirmative","yes","confirmed","correct"],["all passengers","everyone","187","all pax"],["evacuated","clear","off aircraft"],["safely","safe"],["no injuries","no casualties","all safe"]],"hint":{"text_tr":"Kaptan''a tüm yolcu ve ekip sayısını net bir şekilde bildir (187 yolcu + 6 ekip) ve yaralanma durumu olmadığını raporla.","text_en":"Report the complete passenger and crew count (187 passengers + 6 crew) and confirm no injuries to the captain."},"expected_response":{"text_en":"Affirmative, all 187 passengers and 6 crew evacuated safely. No injuries reported.","text_tr":"187 yolcu ve 6 ekip üyesinin güvenle tahliye edildiğini ve yaralanma olmadığını onayla.","must_include":["affirmative","yes","confirmed","187","passengers","pax","crew","6","six","evacuated","clear","safely","safe","no injuries","no casualties"]},"vocabulary_focus":["headcount","evacuate"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'cabin-evacuation-command-sequence-l4';

UPDATE public.scenarios SET
  briefing = '{"tr":"Transatlantik uçuşta arka galley''de bir yolcu aniden bayıldı ve bilinçsiz durumda. Kabin Amiri olarak kokpit ile acil koordinasyon yaparak tıbbi yardım organize etmeli ve gerekirse diversion kararını desteklemelisiniz.","en":"During a transatlantic flight, a passenger has suddenly collapsed in the rear galley and is unconscious. As Cabin Chief, you must coordinate urgently with the flight deck to arrange medical assistance and support a possible diversion decision."}'::jsonb,
  learner_role = '{"tr":"Sen transatlantik bir uçuşta flight deck crew üyesisin ve Kabin Amiri''nden gelen tıbbi acil durum raporunu koordine ediyorsun","en":"You are a flight deck crew member on a transatlantic flight coordinating a medical emergency report from the Cabin Chief"}'::jsonb,
  objective = '{"tr":"Kabin ekibi ile net iletişim kurarak tıbbi acil durumu yönet, gerekli ekipmanı sağla ve diversion gereksinimini belirle","en":"Manage the medical emergency through clear communication with cabin crew, provide necessary equipment, and determine diversion requirements"}'::jsonb,
  key_vocabulary = '[{"term":"medical emergency","definition_tr":"Uçakta yolcu veya mürettebatın sağlığını tehdit eden acil tıbbi durum","definition_en":"Urgent medical situation threatening the health of a passenger or crew member on board"},{"term":"unconscious","definition_tr":"Bilinci kapalı, uyaranlara yanıt vermeyen durum","definition_en":"State of being unaware and unresponsive to stimuli"},{"term":"AED (Automated External Defibrillator)","definition_tr":"Kalp durmasında kullanılan otomatik harici defibrilatör cihazı","definition_en":"Portable device used to treat cardiac arrest by delivering electric shock"},{"term":"diversion","definition_tr":"Planlanan hedefe gitmek yerine alternatif havaalanına iniş kararı","definition_en":"Decision to land at an alternate airport instead of the planned destination"},{"term":"PA (Public Address)","definition_tr":"Kabin içi anons sistemi üzerinden yapılan duyuru","definition_en":"Announcement made through the cabin public address system"},{"term":"medical kit","definition_tr":"Uçakta bulunması zorunlu tıbbi malzeme ve ilaç kiti","definition_en":"Required onboard kit containing medical supplies and medications"},{"term":"stable","definition_tr":"Hastanın durumunun sabit, kötüleşmeyen halde olması","definition_en":"Patient''s condition being steady and not deteriorating"},{"term":"stand by","definition_tr":"Beklemek, hazır olmak; daha sonra bilgi verilecek anlamında kullanılan ifade","definition_en":"Wait or be ready; phrase indicating information will follow shortly"}]'::jsonb,
  estimated_duration_seconds = 180,
  turns = '[{"atcStation":"CABIN CHIEF","atcUtterance":"Flight deck, cabin chief. We have a medical emergency in the rear cabin. Passenger unconscious, not responding. Requesting immediate assistance and doctor call.","correctionTr":"Kokpit''e durumu onayladığınızı gösterin: ''copy medical emergency'' veya ''understood''. PA yapacaklarını kabul edin ve yolcunun mevcut durumunu sorun.","expectedReadback":"Cabin chief, flight deck. Copy medical emergency, unconscious passenger. Will make PA for doctor immediately. What is passenger condition now?","frequency":"INTERPHONE","hintTr":"Acil durumu teyit edin, doktor çağrısı yapılacağını belirtin ve güncel durum sorun.","id":"turn-1","isFinal":false,"keyPhrases":[["copy","roger","understood","acknowledge"],["medical emergency","emergency"],["unconscious","not responding"],["PA","call","announcement"],["doctor","medical professional"],["condition","status","situation"]],"hint":{"text_tr":"Önce acil durumu onaylayın (copy/roger medical emergency), ardından PA ile doktor çağrısı yapacağınızı belirtin ve yolcunun şu anki durumunu sorun","text_en":"First acknowledge the emergency (copy/roger medical emergency), then confirm you''ll make a PA for a doctor, and ask about the passenger''s current condition"},"expected_response":{"text_en":"Cabin chief, flight deck. Copy medical emergency, unconscious passenger. Will make PA for doctor immediately. What is passenger condition now?","text_tr":"Kabin Amiri''ne acil durumu aldığınızı, doktor için anons yapacağınızı ve mevcut durumu sorduğunuzu bildirin","must_include":["copy","roger","understood","medical emergency","emergency","unconscious","pa","announcement","doctor","condition","status"]},"vocabulary_focus":["medical emergency","unconscious","PA"]},{"atcStation":"CAPTAIN","atcUtterance":"Cabin chief, we have a doctor on board responding. Do you need medical kit and AED? Also advise if diversion required.","correctionTr":"Tıbbi ekipman talebinizi açıkça belirtin: ''medical kit'' ve ''AED'' gerekli, koltuk numarası verin. Diversion kararı için doktorun değerlendirmesini beklediğinizi söyleyin.","expectedReadback":"Yes captain, we need both medical kit and AED to seat 42A immediately. Stand by for diversion decision, doctor assessing now.","frequency":"INTERPHONE","hintTr":"İhtiyaç duyduğunuz ekipmanı, yerini ve diversion hakkında doktor değerlendirmesi beklediğinizi bildirin.","id":"turn-2","isFinal":false,"keyPhrases":[["yes","affirmative","confirm"],["medical kit","kit"],["AED"],["seat","42A","location"],["immediately","urgent","ASAP"],["stand by","standby","wait"],["diversion","alternate"],["doctor","assessing","assessment"]],"hint":{"text_tr":"Medical kit ve AED''nin gerekli olduğunu, koltuk numarasını (42A) ve aciliyetini belirtin. Diversion kararı için doktorun değerlendirmesini beklediğinizi ekleyin","text_en":"Confirm that medical kit and AED are needed, specify seat number (42A) and urgency. Add that you''re standing by for the doctor''s assessment regarding diversion"},"expected_response":{"text_en":"Yes captain, we need both medical kit and AED to seat 42A immediately. Stand by for diversion decision, doctor assessing now.","text_tr":"Tıbbi ekipmanların 42A koltuğuna acilen gerektiğini, diversion kararı için doktor değerlendirmesi beklendiğini bildirin","must_include":["yes","affirmative","medical kit","kit","aed","seat","42a","immediately","urgent","stand by","standby","diversion","doctor","assessing"]},"vocabulary_focus":["medical kit","AED","diversion","stand by"]},{"atcStation":"CABIN CHIEF","atcUtterance":"Flight deck, cabin chief. Doctor advises passenger is stable now, conscious and responsive. No diversion necessary. Continue to destination. Will monitor closely.","correctionTr":"Durumu onaylayın: yolcu ''stable'' ve ''conscious''. Diversion gerekli değil, hedefe devam. Değişiklik olursa bilgi istediğinizi ekleyin.","expectedReadback":"Roger cabin chief, copy passenger stable and conscious. No diversion required, continuing to destination. Keep us informed of any changes.","frequency":"INTERPHONE","hintTr":"İyi haberi teyit edin, yolcunun durumu iyileşti ve uçuş normale dönüyor.","id":"turn-3","isFinal":true,"keyPhrases":[["roger","copy","understood"],["passenger stable","stable"],["conscious","responsive"],["no diversion","continue","continuing"],["destination"],["keep informed","advise","update","monitor"]],"hint":{"text_tr":"İyi haberi onaylayın: yolcu artık stable ve conscious durumda. Diversion gerekmiyor, hedefe devam ediliyor. Değişiklik olursa bilgilendirilmek istediğinizi ekleyin","text_en":"Acknowledge the good news: passenger is now stable and conscious. No diversion needed, continuing to destination. Add that you want to be kept informed of any changes"},"expected_response":{"text_en":"Roger cabin chief, copy passenger stable and conscious. No diversion required, continuing to destination. Keep us informed of any changes.","text_tr":"Yolcunun durumunun düzeldiğini, diversion gerekmediğini ve hedefe devam edildiğini onaylayın, değişiklik durumunda bilgi isteyin","must_include":["roger","copy","stable","conscious","responsive","no diversion","continue","destination","keep informed","monitor","changes"]},"vocabulary_focus":["stable","conscious","diversion"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'cabin-medical-emergency-coordination';

UPDATE public.scenarios SET
  briefing = '{"tr":"Boarding tamamlanmak üzere ve kalkışa 15 dakika var. Cabin Chief sana bugünkü safety demonstration görev dağılımını yapıyor ve prosedürü hatırlatıyor.","en":"Boarding is nearly complete with 15 minutes to departure. The Cabin Chief is briefing you on today''s safety demonstration task assignments and procedures."}'::jsonb,
  learner_role = '{"tr":"Sen cabin crew üyesi olarak door 2L''de safety demo sorumluluğunu alıyorsun ve Cabin Chief''in talimatlarını anlayıp onaylamalısın.","en":"You are a cabin crew member receiving safety demo responsibility at door 2L and must acknowledge the Cabin Chief''s instructions clearly."}'::jsonb,
  objective = '{"tr":"Cabin Chief''in verdiği safety demo görevini doğru anla, pozisyonunu onayla ve ekipman kontrolü talimatını kabul et.","en":"Understand the safety demo assignment, confirm your position, and acknowledge the equipment check instruction."}'::jsonb,
  key_vocabulary = '[{"term":"safety demo / safety demonstration","definition_tr":"Uçuştan önce yolculara yapılan güvenlik ekipmanı gösterimi","definition_en":"Pre-flight demonstration of safety equipment to passengers"},{"term":"oxygen mask","definition_tr":"Kabin basıncı düştüğünde kullanılan acil durum oksijen maskesi","definition_en":"Emergency oxygen mask used when cabin pressure drops"},{"term":"life vest / lifevest","definition_tr":"Su üzerine acil iniş durumunda kullanılan can yeleği","definition_en":"Flotation device used in case of water landing"},{"term":"door two left (2L)","definition_tr":"Uçağın sol tarafındaki ikinci kapı pozisyonu","definition_en":"Second door position on the left side of the aircraft"},{"term":"PA system","definition_tr":"Passenger Address system - kabin içi anons sistemi","definition_en":"Passenger Address system for cabin announcements"},{"term":"manual demo","definition_tr":"PA sistemi çalışmazsa ekip üyelerinin sesli olarak yaptığı gösterim","definition_en":"Demonstration performed verbally by crew if PA system fails"},{"term":"demo equipment","definition_tr":"Safety demonstration için kullanılan ekipmanlar (mask, vest, seatbelt vb.)","definition_en":"Equipment used for safety demonstration (mask, vest, seatbelt, etc.)"},{"term":"wilco","definition_tr":"Will comply - talimatı anlayıp uygulayacağım anlamında standart onay","definition_en":"Will comply - standard acknowledgment that instruction is understood and will be followed"}]'::jsonb,
  estimated_duration_seconds = 135,
  turns = '[{"atcStation":"CABIN CHIEF","atcUtterance":"Good morning. You''ll demonstrate the oxygen mask and life vest at door two left during the safety demo. Confirm your position, please.","correctionTr":"Kabin Amiri sizden pozisyonunuzu teyit etmenizi istedi. ''Oxygen mask ve life vest gösterimi door 2L''de yapacağım'' şeklinde onaylayın.","expectedReadback":"Roger, I''ll demonstrate oxygen mask and life vest at door two left.","frequency":null,"hintTr":"Sadece hangi ekipmanı nerede göstereceğinizi tekrar edin.","id":"turn-1","isFinal":false,"keyPhrases":[["oxygen mask","oxygen"],["life vest","lifevest"],["door two left","2L","door 2 left"]],"hint":{"text_tr":"Cabin Chief sana pozisyonunu soruyor. Hangi ekipmanı (oxygen mask ve life vest) nerede göstereceğini (door 2L) tekrarla ve onayla.","text_en":"The Cabin Chief is asking you to confirm your position. Repeat which equipment (oxygen mask and life vest) you will demonstrate and where (door 2L)."},"expected_response":{"text_en":"Roger, I''ll demonstrate oxygen mask and life vest at door two left.","text_tr":"Anladım, oxygen mask ve life vest gösterimini door 2L''de yapacağım.","must_include":["oxygen mask","oxygen","life vest","lifevest","door two left","door 2 left","2l","demonstrate"]},"vocabulary_focus":["oxygen mask","life vest","door two left"]},{"atcStation":"CABIN CHIEF","atcUtterance":"Correct. Remember, wait for my signal before you start. If the PA system fails, we''ll do manual demo. Any questions?","correctionTr":"Kabin Amiri sizden talimatı anladığınızı ve soru olup olmadığını söylemenizi bekliyor. ''Sinyalinizi bekleyeceğim, sorum yok'' deyin.","expectedReadback":"Understood, I''ll wait for your signal. No questions.","frequency":null,"hintTr":"Talimatı onaylayın ve soru olmadığını bildirin.","id":"turn-2","isFinal":false,"keyPhrases":[["wait","waiting"],["signal","your signal"],["no questions","no question","all clear"]],"hint":{"text_tr":"İki şey söylemen gerek: Cabin Chief''in sinyalini bekleyeceğini onayla ve soru olmadığını bildir. Kısa ve net yanıt ver.","text_en":"You need to say two things: confirm you''ll wait for the Cabin Chief''s signal, and state you have no questions. Keep it short and clear."},"expected_response":{"text_en":"Understood, I''ll wait for your signal. No questions.","text_tr":"Anlaşıldı, sizin sinyalinizi bekleyeceğim. Sorum yok.","must_include":["understood","wait","waiting","signal","your signal","no questions","no question","all clear"]},"vocabulary_focus":["signal","PA system","manual demo"]},{"atcStation":"CABIN CHIEF","atcUtterance":"Good. Check your demo equipment now and report back if there''s any problem. We depart in fifteen minutes.","correctionTr":"Kabin Amiri demo ekipmanını kontrol edip sorun varsa bildirmenizi istiyor. ''Wilco, ekipmanı kontrol edip sorun olursa bildireceğim'' şeklinde yanıt verin.","expectedReadback":"Wilco, I''ll check the demo equipment and report any problems.","frequency":null,"hintTr":"Talimatı kabul edin ve ne yapacağınızı tekrarlayın.","id":"turn-3","isFinal":true,"keyPhrases":[["wilco","will comply","roger"],["check","checking"],["demo equipment","equipment"],["report","report back"]],"hint":{"text_tr":"Talimatı kabul et (wilco kullanabilirsin) ve ne yapacağını özetle: demo equipment''i kontrol edip sorun varsa rapor edeceksin.","text_en":"Accept the instruction (you can use wilco) and summarize what you''ll do: check demo equipment and report any problems."},"expected_response":{"text_en":"Wilco, I''ll check the demo equipment and report any problems.","text_tr":"Wilco, demo ekipmanını kontrol edip herhangi bir sorun varsa rapor edeceğim.","must_include":["wilco","will comply","roger","check","checking","demo equipment","equipment","report","report back","problems","any problems"]},"vocabulary_focus":["wilco","demo equipment"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'cabin-pre-departure-safety-demo-briefing';

UPDATE public.scenarios SET
  briefing = '{"tr":"İstanbul Havalimanı''nda kesişen iki runway''de eş zamanlı kalkış talebi var. Tower controller olarak runway 35L ve runway 06''daki traffic''i güvenli şekilde sequence edip conflict''i çözmelisin.","en":"Two aircraft are requesting departure on intersecting runways at Istanbul Airport. As Tower controller, you must safely sequence traffic on runway 35L and runway 06 to resolve the conflict."}'::jsonb,
  learner_role = '{"tr":"Sen Istanbul Tower controller''ısın ve kesişen runway''lerde bekleyen iki departure traffic''i koordine ediyorsun.","en":"You are the Istanbul Tower controller coordinating two departure aircraft on intersecting runways."}'::jsonb,
  objective = '{"tr":"Kesişen runway''lerdeki iki uçağı güvenli sequence ile kalkışa gönder ve separation''ı koru.","en":"Safely sequence and clear two aircraft for departure on intersecting runways while maintaining separation."}'::jsonb,
  key_vocabulary = '[{"term":"hold position","definition_tr":"Uçağın bulunduğu noktada durmasını ve hareket etmemesini isteyen talimat","definition_en":"Instruction for aircraft to remain at current position without moving"},{"term":"intersecting runways","definition_tr":"Birbirini kesen, ortak bir noktada kesişen pistler","definition_en":"Runways that cross each other at a common point"},{"term":"cleared for takeoff","definition_tr":"Uçağın kalkış yapması için verilen resmi izin","definition_en":"Official authorization for aircraft to commence takeoff"},{"term":"expedite departure","definition_tr":"Uçağın kalkışını mümkün olan en hızlı şekilde gerçekleştirmesini isteme","definition_en":"Request for aircraft to execute takeoff as quickly as possible"},{"term":"traffic","definition_tr":"Yakındaki veya etkileyebilecek pozisyondaki diğer uçak","definition_en":"Other aircraft in proximity or affecting position"},{"term":"airborne","definition_tr":"Uçağın havaya kalkmış, artık yerde olmayan durumu","definition_en":"Aircraft has lifted off and is no longer on the ground"},{"term":"sequence","definition_tr":"Uçakların kalkış veya iniş sırasını planlama ve düzenleme","definition_en":"Planning and organizing the order of aircraft departures or arrivals"},{"term":"immediate departure","definition_tr":"Gecikme olmadan, hemen kalkışa hazır olan uçak durumu","definition_en":"Aircraft ready for takeoff without delay"}]'::jsonb,
  estimated_duration_seconds = 150,
  turns = '[{"atcStation":"PEGASUS 752","atcUtterance":"Istanbul Tower, Pegasus 752 holding point runway 06, ready for departure.","correctionTr":"Pegasus 752''ye hold position talimatı verin ve 35L''den kalkacak traffic''in yolunu keseceğini belirtin. ''Hold position, traffic departing 35L will cross your path, standby'' gibi bir ifade kullanın.","expectedReadback":"Pegasus 752, hold position, traffic departing runway 35L will cross your departure path, standby.","frequency":"118.1","hintTr":"Kesişen runway''lerde önce hangi uçağı gönderebileceğinizi düşünün ve diğerini bekletin.","id":"turn-1","isFinal":false,"keyPhrases":[["Pegasus 752","752"],["hold position","hold","hold short"],["traffic","traffic departing"],["35L","three five left"],["cross","crossing","will cross"],["standby","stand by"]],"hint":{"text_tr":"Pegasus 752 runway 06''da hazır ama 35L ile kesişiyor. Önce Turkish 1453''ü göndereceğin için Pegasus''u hold position''da bekletmen gerekiyor. Traffic bilgisi ver ve standby de.","text_en":"Pegasus 752 is ready on runway 06 but it intersects 35L. Since you''ll send Turkish 1453 first, instruct Pegasus to hold position, provide traffic information, and tell them to standby."},"expected_response":{"text_en":"Pegasus 752, hold position, traffic departing runway 35L will cross your departure path, standby.","text_tr":"Pegasus''a pozisyonunda beklemesini söyle, 35L''den kalkacak traffic''in yolunu keseceğini bildir ve standby iste.","must_include":["pegasus 752","752","hold position","hold","traffic","35l","three five left","cross","standby"]},"vocabulary_focus":["hold position","traffic","intersecting runways"]},{"atcStation":"TURKISH 1453","atcUtterance":"Tower, Turkish 1453, we are ready for immediate departure, request clearance runway 35L.","correctionTr":"Turkish 1453''e takeoff clearance verin ve runway 06''da bekleyen traffic olduğunu belirterek expedite departure isteyin. ''Cleared for takeoff 35L, traffic holding 06, expedite departure'' şeklinde ifade edin.","expectedReadback":"Turkish 1453, cleared for takeoff runway 35L, traffic holding runway 06, expedite departure.","frequency":"118.1","hintTr":"Immediate kalkışa hazır olan uçağı önce göndermek mantıklı. Diğer uçağa trafik bilgisi vermeyi unutmayın.","id":"turn-2","isFinal":false,"keyPhrases":[["Turkish 1453","1453"],["cleared for takeoff","cleared takeoff"],["runway 35L","35L","three five left"],["traffic","traffic holding"],["runway 06","06","zero six"],["expedite","expedite departure"]],"hint":{"text_tr":"Turkish 1453 immediate departure''a hazır ve runway kesişme noktasını ilk geçecek. Takeoff clearance ver, runway 06''da bekleyen traffic''ten bahset ve expedite departure iste ki Pegasus fazla beklemesin.","text_en":"Turkish 1453 is ready for immediate departure and will cross the intersection first. Issue takeoff clearance, mention traffic holding on runway 06, and request expedite departure so Pegasus doesn''t wait long."},"expected_response":{"text_en":"Turkish 1453, cleared for takeoff runway 35L, traffic holding runway 06, expedite departure.","text_tr":"Turkish''e 35L''den kalkış izni ver, runway 06''da bekleyen traffic''ten bahset ve hızlı kalkış iste.","must_include":["turkish 1453","1453","cleared for takeoff","cleared takeoff","runway 35l","35l","three five left","traffic","runway 06","06","zero six","expedite"]},"vocabulary_focus":["cleared for takeoff","expedite departure","traffic"]},{"atcStation":"PEGASUS 752","atcUtterance":"Tower, Pegasus 752, traffic in sight, still ready for departure.","correctionTr":"Traffic artık airborne olduğuna göre Pegasus 752''ye takeoff clearance verebilirsiniz. ''Traffic airborne, cleared for takeoff runway 06, wind 040 degrees 8 knots'' gibi söyleyin.","expectedReadback":"Pegasus 752, traffic airborne, cleared for takeoff runway 06, wind 040 degrees 8 knots.","frequency":"118.1","hintTr":"İlk uçak havalandıktan sonra ikinci uçağa clearance verebilirsiniz. Rüzgar bilgisini eklemeyi unutmayın.","id":"turn-3","isFinal":true,"keyPhrases":[["Pegasus 752","752"],["traffic airborne","traffic is airborne","traffic departed"],["cleared for takeoff","cleared takeoff"],["runway 06","06","zero six"],["wind","wind 040","040 degrees","8 knots"]],"hint":{"text_tr":"Turkish 1453 artık havalandı, kesişme noktası temiz. Pegasus 752''ye traffic airborne olduğunu bildir, takeoff clearance ver ve aktual rüzgar bilgisini ekle.","text_en":"Turkish 1453 is now airborne, intersection is clear. Inform Pegasus 752 that traffic is airborne, issue takeoff clearance, and include current wind information."},"expected_response":{"text_en":"Pegasus 752, traffic airborne, cleared for takeoff runway 06, wind 040 degrees 8 knots.","text_tr":"Pegasus''a traffic''in havalandığını söyle, runway 06''dan kalkış izni ver ve rüzgar bilgisini ekle.","must_include":["pegasus 752","752","traffic airborne","airborne","cleared for takeoff","cleared takeoff","runway 06","06","zero six","wind","040","8 knots"]},"vocabulary_focus":["airborne","cleared for takeoff","wind"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'conflict-resolution-two-departures-l4';

UPDATE public.scenarios SET
  briefing = '{"tr":"İstanbul Havalimanı''nda yoğun kar yağışı var ve pist operasyonları yavaşladı. Ground operations koordinatörü olarak, ramp supervisor ile de-icing prosedürlerini koordine edecek ve Turkish 1453 heavy''nin Frankfurt''a güvenli kalkışını sağlayacaksın.","en":"Heavy snowfall at Istanbul Airport has slowed runway operations. As ground operations coordinator, you must coordinate de-icing procedures with the ramp supervisor and ensure Turkish 1453 heavy''s safe departure to Frankfurt."}'::jsonb,
  learner_role = '{"tr":"Sen İstanbul Havalimanı ground operations koordinatörüsün ve kar yağışı sırasında Turkish 1453 heavy A330''un de-icing ihtiyaçlarını yönetiyorsun.","en":"You are the Istanbul Airport ground operations coordinator managing de-icing requirements for Turkish 1453 heavy, an A330, during snowfall."}'::jsonb,
  objective = '{"tr":"De-icing fluid tipi, miktarı ve HOT time bilgilerini doğru ver, de-icing pad koordinasyonunu sağla ve crew''ya kritik zamanlama bilgilerini aktar.","en":"Provide correct de-icing fluid type, quantity, and HOT time information, coordinate de-icing pad availability, and relay critical timing information to the crew."}'::jsonb,
  key_vocabulary = '[{"term":"Type Four fluid","definition_tr":"En uzun koruma süresi sağlayan donma önleyici sıvı tipi (Tip IV), yoğun kar yağışında tercih edilir","definition_en":"Anti-icing fluid type providing longest holdover time (Type IV), preferred in heavy snowfall"},{"term":"HOT / Holdover Time","definition_tr":"De-icing işleminden sonra uçağın donmadan güvenle kalabileceği maksimum süre","definition_en":"Maximum time aircraft can remain safely before freezing after de-icing completion"},{"term":"De-icing pad","definition_tr":"Uçaklara donma önleyici sıvı uygulaması yapılan özel alan","definition_en":"Designated area where anti-icing fluid is applied to aircraft"},{"term":"Precipitation","definition_tr":"Yağış (kar, yağmur, dolu vb.); de-icing kararlarını etkileyen meteorolojik durum","definition_en":"Weather condition (snow, rain, sleet) affecting de-icing decisions"},{"term":"Wilco","definition_tr":"''Will comply'' kısaltması; talimatı anlayıp uygulayacağını belirtir","definition_en":"Abbreviation for ''will comply''; indicates understanding and intention to follow instruction"},{"term":"Heavy","definition_tr":"136,000 kg veya üzeri maksimum kalkış ağırlığına sahip uçak kategorisi","definition_en":"Aircraft category with maximum takeoff weight of 136,000 kg or more"},{"term":"Pushback","definition_tr":"Uçağın park pozisyonundan geriye itilerek taksi için hazırlanması","definition_en":"Process of pushing aircraft backwards from parking position for taxi"},{"term":"Ramp supervisor","definition_tr":"Apron alanındaki yer operasyonlarını denetleyen görevli","definition_en":"Official supervising ground operations on the apron area"}]'::jsonb,
  estimated_duration_seconds = 150,
  turns = '[{"atcStation":"RAMP SUPERVISOR","atcUtterance":"Ground Ops, Ramp. Turkish 1453 heavy requesting de-icing. What type and quantity do you recommend for these conditions?","correctionTr":"Type Four fluid (donma önleyici sıvı tipi), her kanada 50 litre ve HOT time (koruma süresi) yaklaşık 45 dakika olduğunu belirtmelisiniz. Mevcut yağış koşullarını da ekleyin.","expectedReadback":"Ramp, Ground Ops. Recommend Type Four fluid, fifty liters per wing. Holdover time approximately forty-five minutes in current precipitation.","frequency":"129.8","hintTr":"De-icing için sıvı tipi, miktar ve holdover time bilgilerini net bir şekilde verin.","id":"turn-1","isFinal":false,"keyPhrases":[["type four","type 4","type IV"],["fifty liters","50 liters","fifty litres"],["holdover time","HOT"],["forty-five minutes","45 minutes","four five minutes"]],"hint":{"text_tr":"Kar yağışı koşullarında en uygun fluid tipini (Type Four), miktar önerisini (her kanada 50 litre) ve mevcut hava koşullarında geçerli olacak holdover time''ı (yaklaşık 45 dakika) net bir şekilde belirt.","text_en":"Clearly state the most suitable fluid type for snow conditions (Type Four), quantity recommendation (50 liters per wing), and applicable holdover time in current weather (approximately 45 minutes)."},"expected_response":{"text_en":"Ramp, Ground Ops. Recommend Type Four fluid, fifty liters per wing. Holdover time approximately forty-five minutes in current precipitation.","text_tr":"Ramp''e, Type Four sıvı önerin, her kanada elli litre. Mevcut yağış koşullarında holdover time yaklaşık kırk beş dakika diyorsun.","must_include":["type four","type 4","type iv","fifty liters","50 liters","per wing","holdover time","hot","forty-five minutes","45 minutes","four five minutes","precipitation","current conditions"]},"vocabulary_focus":["Type Four fluid","HOT / Holdover Time","Precipitation"]},{"atcStation":"RAMP SUPERVISOR","atcUtterance":"Ground Ops, copied. Confirm you will coordinate de-icing pad availability and update Turkish 1453 on completion time?","correctionTr":"Onay verip (affirm), pad 2''nin müsaitliğini koordine edeceğinizi ve Turkish 1453''e tahmini tamamlanma süresini (yaklaşık 10 dakika) bildireceğinizi söylemelisiniz.","expectedReadback":"Affirm. Will coordinate pad two availability and advise Turkish 1453 estimated completion in one-zero minutes.","frequency":"129.8","hintTr":"Onaylayın ve ne yapacağınızı net bir şekilde ifade edin.","id":"turn-2","isFinal":false,"keyPhrases":[["affirm","affirmative","confirm","roger"],["coordinate","check","arrange"],["pad two","pad 2","de-icing pad two"],["one-zero minutes","10 minutes","ten minutes"]],"hint":{"text_tr":"Talebi onaylayıp (affirm/affirmative kullan) hangi de-icing pad''i koordine edeceğini (pad 2) ve Turkish 1453''e ne kadar sürede tamamlanacağını (yaklaşık 10 dakika) bildireceğini söyle.","text_en":"Confirm the request (use affirm/affirmative), state which de-icing pad you''ll coordinate (pad 2), and mention you''ll advise Turkish 1453 of estimated completion time (approximately 10 minutes)."},"expected_response":{"text_en":"Affirm. Will coordinate pad two availability and advise Turkish 1453 estimated completion in one-zero minutes.","text_tr":"Onaylıyorsun. Pad iki müsaitliğini koordine edecek ve Turkish 1453''e tahmini bir-sıfır dakikada tamamlanacağını bildireceksin.","must_include":["affirm","affirmative","roger","coordinate","check","arrange","pad two","pad 2","de-icing pad","advise","turkish 1453","one-zero minutes","10 minutes","ten minutes","completion"]},"vocabulary_focus":["De-icing pad","Wilco","Heavy"]},{"atcStation":"RAMP SUPERVISOR","atcUtterance":"Wilco. Also advise the crew to begin their holdover time from de-icing completion, not from pushback.","correctionTr":"Mesajı aldığınızı (copied/wilco) ve mürettebata HOT time''ın de-icing tamamlandıktan sonra başlayacağını bildireceğinizi söylemelisiniz. Pushback değil, de-icing bitiminden itibaren.","expectedReadback":"Copied. Will inform Turkish 1453 crew to start holdover time from de-icing completion. Ground Ops standing by.","frequency":"129.8","hintTr":"Kritik bilgiyi doğru anladığınızı gösterin ve mürettebata aktaracağınızı belirtin.","id":"turn-3","isFinal":true,"keyPhrases":[["copied","copy","roger","wilco"],["inform","advise","notify"],["Turkish 1453","the crew"],["start holdover time","begin HOT","commence holdover"],["de-icing completion","completion of de-icing"]],"hint":{"text_tr":"Mesajı aldığını belirt (copied, wilco veya roger) ve crew''ya HOT time''ın pushback''ten değil de-icing tamamlandıktan sonra başlayacağını bildireceğini söyle. Son olarak ''standing by'' ekleyebilirsin.","text_en":"Acknowledge the message (copied, wilco, or roger) and confirm you''ll inform the crew that HOT time starts from de-icing completion, not pushback. You can end with ''standing by''."},"expected_response":{"text_en":"Copied. Will inform Turkish 1453 crew to start holdover time from de-icing completion. Ground Ops standing by.","text_tr":"Anladığını belirtiyorsun. Turkish 1453 crew''suna holdover time''ın de-icing tamamlandıktan sonra başlayacağını bildireceksin. Ground Ops hazır bekliyorsun.","must_include":["copied","copy","wilco","roger","inform","advise","notify","turkish 1453","crew","start","begin","commence","holdover time","hot","de-icing completion","completion","not pushback","from completion"]},"vocabulary_focus":["HOT / Holdover Time","Pushback","Wilco","Ramp supervisor"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'deicing-fluid-request-hot-time';

UPDATE public.scenarios SET
  briefing = '{"tr":"Istanbul Tower''da windshear raporu nedeniyle runway 35L''den 35R''ye pist değişikliği yapılıyor. TK1453 için revize edilmiş departure clearance ve taxi instruction vermeniz gerekiyor.","en":"Due to windshear reports on runway 35L, you must issue a revised departure clearance and taxi instructions for Turkish Airlines TK1453 to use runway 35R instead."}'::jsonb,
  learner_role = '{"tr":"Sen Istanbul Tower controller olarak TK1453''e pist değişikliği nedeniyle revize clearance ve taxi instruction veriyorsun.","en":"You are working as Istanbul Tower controller issuing a revised clearance and taxi instructions to TK1453 due to a runway change."}'::jsonb,
  objective = '{"tr":"Windshear nedeniyle güvenli pist değişikliği yaparak eksiksiz departure clearance ve taxi instruction ver.","en":"Issue complete departure clearance and taxi instructions for a safe runway change due to windshear."}'::jsonb,
  key_vocabulary = '[{"term":"windshear","definition_tr":"Rüzgar kayması - ani rüzgar hızı veya yönü değişimi","definition_en":"Sudden change in wind speed or direction, hazardous during takeoff/landing"},{"term":"revised clearance","definition_tr":"Revize edilmiş izin - değiştirilen uçuş izni","definition_en":"Modified or amended flight clearance due to operational changes"},{"term":"stand by","definition_tr":"Bekleyin - yeni talimat için hazır olun","definition_en":"Wait for further instructions, remain ready"},{"term":"hold short","definition_tr":"Geçmeden önünde bekle - belirtilen noktayı geçme","definition_en":"Stop before reaching a specified point (runway/taxiway)"},{"term":"cross runway","definition_tr":"Pisti geç - aktif pistten karşıya geçiş izni","definition_en":"Permission to traverse an active runway"},{"term":"taxi via","definition_tr":"Üzerinden taksi yap - belirtilen yol üzerinden git","definition_en":"Proceed on the ground using specified taxiway route"},{"term":"initially","definition_tr":"İlk başta, başlangıçta - sonra değişebilir","definition_en":"At first, for the initial phase (may change later)"},{"term":"squawk","definition_tr":"Transponder kodu ayarla","definition_en":"Set transponder code for radar identification"}]'::jsonb,
  estimated_duration_seconds = 180,
  turns = '[{"atcStation":"TURKISH 1453","atcUtterance":"Istanbul Tower, Turkish 1453, holding short runway 35L, ready for departure.","correctionTr":"Pilota beklemesini söyleyin ve 35L pistindeki rüzgar kayması nedeniyle revize edilmiş bir izin vereceğinizi bildirin.","expectedReadback":"Turkish 1453, Istanbul Tower, stand by for revised clearance due to windshear on runway 35L.","frequency":"118.1","hintTr":"Pilotun güvenliği için pist değişikliği gerekiyor.","id":"turn-1","isFinal":false,"keyPhrases":[["stand by","standby","wait"],["revised clearance","new clearance","amended clearance"],["windshear","wind shear"],["35L","three five left"]],"hint":{"text_tr":"Pilota beklemesini söyle ve 35L pistindeki windshear nedeniyle revised clearance vereceğini bildir.","text_en":"Tell the pilot to stand by and inform them you''ll issue a revised clearance due to windshear on runway 35L."},"expected_response":{"text_en":"Turkish 1453, stand by for revised clearance due to windshear on runway 35L.","text_tr":"TK1453''e windshear nedeniyle beklemesini ve yeni clearance alacağını söyle.","must_include":["stand by","standby","revised clearance","new clearance","amended clearance","windshear","wind shear","35l","three five left"]},"vocabulary_focus":["stand by","revised clearance","windshear"]},{"atcStation":"TURKISH 1453","atcUtterance":"Standing by, Turkish 1453.","correctionTr":"Londra Heathrow''a izin verin, TAVMA1B kalkış prosedürü ile 35R pistini kullanarak, başlangıç tırmanış 5000 fit, transponder kodu 2341.","expectedReadback":"Turkish 1453, cleared to London Heathrow via TAVMA1B departure, runway 35R, climb initially to 5000 feet, squawk 2341.","frequency":"118.1","hintTr":"Tüm kalkış izin bilgilerini eksiksiz verin.","id":"turn-2","isFinal":false,"keyPhrases":[["cleared to London","cleared to Heathrow"],["TAVMA1B","TAVMA one bravo"],["runway 35R","runway three five right"],["climb initially","initial climb"],["5000 feet","five thousand feet"],["squawk 2341","squawk two three four one"]],"hint":{"text_tr":"Londra Heathrow''a tam clearance ver: TAVMA1B departure, runway 35R, initially 5000 feet climb, squawk 2341.","text_en":"Issue complete clearance to London Heathrow: TAVMA1B departure, runway 35R, initial climb 5000 feet, squawk 2341."},"expected_response":{"text_en":"Turkish 1453, cleared to London Heathrow via TAVMA1B departure, runway 35R, climb initially to 5000 feet, squawk 2341.","text_tr":"Heathrow''a TAVMA1B ile 35R''den, ilk 5000 feet''e, transponder 2341 ile clearance ver.","must_include":["cleared to london","cleared to heathrow","tavma","one bravo","1b","runway 35r","three five right","climb initially","initial climb","5000 feet","five thousand","squawk 2341","two three four one"]},"vocabulary_focus":["cleared to","departure","climb initially","squawk"]},{"atcStation":"TURKISH 1453","atcUtterance":"Cleared to London Heathrow via TAVMA1B departure, runway 35R, climb initially 5000 feet, squawk 2341, Turkish 1453. Confirm taxi instructions for new runway.","correctionTr":"Echo taksi yolu üzerinden, 35L pistini geçerek, 35R pistinde Bravo 2''de beklemesini söyleyin ve pushback koordinasyonu için 121.9''dan Yer kontrolü ile iletişime geçmesini bildirin.","expectedReadback":"Turkish 1453, taxi via Echo, cross runway 35L, hold short runway 35R at Bravo 2, contact Ground on 121.9 for pushback coordination.","frequency":"118.1","hintTr":"Yeni piste gitmek için detaylı taksi talimatları verin.","id":"turn-3","isFinal":true,"keyPhrases":[["taxi via Echo","taxi echo"],["cross runway 35L","cross three five left"],["hold short runway 35R","hold short three five right","hold short 35R"],["Bravo 2","bravo two"],["contact Ground","call Ground"],["121.9","one two one decimal nine","one two one point nine"]],"hint":{"text_tr":"Echo taxiway üzerinden, 35L pistini cross ederek, 35R pistinde Bravo 2''de hold short etmesini söyle ve Ground 121.9''u ver.","text_en":"Instruct to taxi via Echo, cross runway 35L, hold short runway 35R at Bravo 2, and contact Ground on 121.9."},"expected_response":{"text_en":"Turkish 1453, taxi via Echo, cross runway 35L, hold short runway 35R at Bravo 2, contact Ground on 121.9 for pushback coordination.","text_tr":"Echo''dan taksi yap, 35L''yi geç, 35R''de Bravo 2''de bekle, Ground 121.9''u ara.","must_include":["taxi via echo","taxi echo","cross runway 35l","cross three five left","hold short","runway 35r","three five right","bravo 2","bravo two","contact ground","call ground","121.9","one two one decimal nine","one two one point nine"]},"vocabulary_focus":["taxi via","cross runway","hold short","contact"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'departure-clearance-runway-change';

UPDATE public.scenarios SET
  briefing = '{"tr":"TK1984 LTFM-EDDF uçuşunu planlıyorsun. Bucharest IFPS ofisi arayarak filed rotanda Romanya üzerinde NOTAM nedeniyle airway closure olduğunu bildiriyor ve refile isteyecek.","en":"You are planning flight TK1984 from Istanbul (LTFM) to Frankfurt (EDDF). Bucharest IFPS calls to inform you of an active NOTAM closing part of your filed route over Romania and requests a refile."}'::jsonb,
  learner_role = '{"tr":"Sen TK1984 uçuşu için dispatcher olarak ATC coordination office ile iletişim kuruyorsun.","en":"You are the dispatcher for flight TK1984 coordinating with the ATC coordination office."}'::jsonb,
  objective = '{"tr":"NOTAM''daki airway closure bilgisini doğrula, alternatif rota ile refile yap ve fuel durumunu onayla.","en":"Confirm the NOTAM airway closure details, refile via alternate route, and verify fuel status."}'::jsonb,
  key_vocabulary = '[{"term":"NOTAM","definition_tr":"Notice to Airmen - pilotlara havacılık tesisleri, servisler veya prosedürlerle ilgili dağıtılan bildirim","definition_en":"Notice to Airmen - a notice distributed to pilots containing information about aviation facilities, services, or procedures"},{"term":"refile","definition_tr":"Flight plan''ı değiştirip yeniden göndermek","definition_en":"To submit a revised or new flight plan"},{"term":"airway closure","definition_tr":"Belirli bir hava yolunun trafiğe kapatılması (genellikle askeri aktivite, hava durumu veya diğer operasyonel nedenlerle)","definition_en":"The closing of a specific airway to traffic, usually due to military activity, weather, or other operational reasons"},{"term":"fuel reserve","definition_tr":"Uçuşun güvenli tamamlanması için planlanan minimum yakıt fazlası","definition_en":"The minimum excess fuel planned to ensure safe completion of the flight"},{"term":"estimate","definition_tr":"Bir noktaya tahmini varış zamanı (ETA - Estimated Time of Arrival)","definition_en":"The predicted time of arrival at a specific point (ETA - Estimated Time of Arrival)"},{"term":"slot time","definition_tr":"Havalimanından kalkış için ATC tarafından atanan belirli zaman aralığı","definition_en":"A specific time window assigned by ATC for departure from an airport"},{"term":"IFPS","definition_tr":"Integrated Initial Flight Plan Processing System - Avrupa''da flight plan işleme merkezi","definition_en":"Integrated Initial Flight Plan Processing System - the European flight plan processing center"},{"term":"clearance","definition_tr":"ATC''nin uçağa verdiği yetki/izin (rota, irtifa, kalkış vs.)","definition_en":"Authorization from ATC for an aircraft to proceed under specified conditions (route, altitude, departure, etc.)"}]'::jsonb,
  estimated_duration_seconds = 180,
  turns = '[{"atcStation":"BUCHAREST IFPS","atcUtterance":"Turkish one-niner-eight-four, Bucharest IFPS. We have a NOTAM affecting your route. Airway M853 between PIXUM and RUDIK is closed due to military activity until 1800 Zulu. Request you refile via L984 or advise alternate.","correctionTr":"NOTAM bilgisini doğrulaman lazım: hangi airway (M853), hangi noktalar arası (PIXUM-RUDIK), kapanış saati (1800Z), ve alternatif rotayı (L984) kullanacağını belirtmelisin. ''Copies'' veya ''roger'' ile başla, sonra detayları tekrarla.","expectedReadback":"Bucharest IFPS, Turkish one-niner-eight-four copies. M853 PIXUM to RUDIK closed until 1800 Zulu. We will refile via L984 and advise estimated time.","frequency":"N/A","hintTr":"ATC''nin verdiği tüm kritik bilgileri readback et: airway adı, fix''ler, zaman, yeni rota.","id":"turn-1","isFinal":false,"keyPhrases":[["copies","copy","roger","understood"],["M853","M 853"],["PIXUM","RUDIK"],["closed","closure"],["1800","eighteen hundred"],["refile","re-file","file"],["L984","L 984"],["advise","inform","send"]],"hint":{"text_tr":"NOTAM bilgisini eksiksiz readback et: hangi airway, hangi fix''ler arası, kapanma saati ve önerilen alternatif rotayı tekrarla. ''Copies'' veya ''roger'' ile başla.","text_en":"Read back all NOTAM details: which airway, between which fixes, closure time, and proposed alternate route. Start with ''copies'' or ''roger''."},"expected_response":{"text_en":"Bucharest IFPS, Turkish one-niner-eight-four copies. M853 PIXUM to RUDIK closed until 1800 Zulu. We will refile via L984 and advise estimated time.","text_tr":"NOTAM detaylarını onayla: M853 PIXUM-RUDIK arası 1800Z''ye kadar kapalı, L984 üzerinden refile yapacağını ve zamanı bildireceğini söyle.","must_include":["copies","copy","roger","m853","m 853","pixum","rudik","1800","eighteen hundred","zulu","refile","l984","l 984"]},"vocabulary_focus":["NOTAM","airway closure","refile"]},{"atcStation":"BUCHAREST IFPS","atcUtterance":"Turkish one-niner-eight-four, roger. Confirm your revised estimate for RUDIK and total flight time via L984. Also state if fuel reserve remains within limits.","correctionTr":"Yeni hesaplamaları net şekilde iletmelisin: RUDIK''e varış tahmini (estimate), toplam flight time ve yakıt rezervinin yeterli olduğunu (within limits) onaylaman gerekiyor. ''Standby'' diyerek zaman kazanabilirsin.","expectedReadback":"Standby for revised estimate. We calculate RUDIK estimate time 1445 Zulu, total flight time two hours fifty-three minutes. Fuel reserve remains within limits, no additional fuel required.","frequency":"N/A","hintTr":"Dispatcher olarak rakamları ve fuel durumunu kesin ifade et. ATC sana güvenmeli.","id":"turn-2","isFinal":false,"keyPhrases":[["standby","stand by","calculating"],["RUDIK"],["1445","fourteen forty-five"],["flight time","total time"],["two hours fifty","two hours five three","2:53"],["fuel reserve","reserve fuel"],["within limits","sufficient","adequate"],["no additional","no extra"]],"hint":{"text_tr":"Dispatcher olarak hesapladığın yeni RUDIK estimate''ini, toplam flight time''ı ve fuel reserve durumunu net şekilde bildir. Gerekirse ''standby'' diyerek zaman kazan.","text_en":"As dispatcher, clearly state your calculated RUDIK estimate, total flight time, and fuel reserve status. Use ''standby'' if you need time."},"expected_response":{"text_en":"Standby for revised estimate. We calculate RUDIK estimate time 1445 Zulu, total flight time two hours fifty-three minutes. Fuel reserve remains within limits, no additional fuel required.","text_tr":"Yeni hesaplamalar için bekle de, sonra RUDIK''e 1445Z estimate, toplam uçuş 2 saat 53 dakika, yakıt rezervi yeterli ve ek yakıt gerekmiyor.","must_include":["standby","stand by","rudik","1445","fourteen forty-five","flight time","total time","two hours fifty","fuel reserve","within limits","no additional"]},"vocabulary_focus":["estimate","fuel reserve","flight time"]},{"atcStation":"BUCHAREST IFPS","atcUtterance":"Turkish one-niner-eight-four, roger your revised routing and fuel status. New flight plan accepted. Slot time remains unchanged at 1415 Zulu. Contact Istanbul Clearance on one-two-one-decimal-seven-five-zero for updated clearance.","correctionTr":"Onay ver: slot time değişmedi (1415Z), ve Istanbul Clearance''ı hangi frekansta (121.750) arayacağını belirt. Nazik bir kapanış yap. Tüm sayıları tekrarla.","expectedReadback":"Roger, slot time 1415 Zulu unchanged. Will contact Istanbul Clearance one-two-one-decimal-seven-five-zero for updated clearance. Turkish one-niner-eight-four, thank you.","frequency":"N/A","hintTr":"Profesyonel bir kapanış: slot, frekans, teşekkür. Dispatcher koordinasyonu böyle biter.","id":"turn-3","isFinal":true,"keyPhrases":[["roger","copy","copied"],["slot time","slot"],["1415","fourteen fifteen"],["unchanged","remains"],["Istanbul Clearance","clearance"],["121.750","one two one decimal seven five","one two one point seven five"],["updated clearance","new clearance"],["thank you","thanks","good day"]],"hint":{"text_tr":"Yeni flight plan''in kabul edildiğini, slot time''ın değişmediğini (1415Z) ve Istanbul Clearance''ı hangi frekansta (121.750) arayacağını onayla.","text_en":"Acknowledge the new flight plan acceptance, confirm slot time unchanged (1415Z), and read back the Istanbul Clearance frequency (121.750)."},"expected_response":{"text_en":"Roger, Turkish one-niner-eight-four. New routing accepted, slot time 1415 Zulu unchanged. Will contact Istanbul Clearance on one-two-one-decimal-seven-five-zero for updated clearance.","text_tr":"Onay ver: yeni rota kabul edildi, slot 1415Z değişmedi, Istanbul Clearance''ı 121.750''de arayacaksın ve güncel clearance alacaksın.","must_include":["roger","accepted","slot","1415","fourteen fifteen","unchanged","istanbul clearance","121.750","one two one decimal seven five zero","updated clearance"]},"vocabulary_focus":["slot time","clearance","frequency"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'dispatcher-route-notam-airspace-closure';

UPDATE public.scenarios SET
  briefing = '{"tr":"Turkish 1453 heavy, Boeing 777 ile Istanbul''dan New York JFK''ya ETOPS uçuşu yapacaksınız. Kuzey Atlantik üzerinde 120 knot headwind tahmini nedeniyle captain ile ARINC üzerinden fuel calculation koordinasyonu yapmanız gerekiyor.","en":"You are dispatching Turkish 1453 heavy, a Boeing 777 ETOPS flight from Istanbul to New York JFK. The captain is calling via ARINC to coordinate fuel calculations due to forecast 120-knot headwinds over the North Atlantic."}'::jsonb,
  learner_role = '{"tr":"Sen Turkish 1453 heavy için dispatcher olarak çalışıyorsun, B777 ETOPS operasyonu için fuel planning ve alternates koordinasyonu yapacaksın.","en":"You are the dispatcher for Turkish 1453 heavy, coordinating fuel planning and alternates for a B777 ETOPS operation."}'::jsonb,
  objective = '{"tr":"Captain ile ARINC üzerinden fuel requirements, critical point calculations ve alternate reserves konusunda profesyonel koordinasyon sağla.","en":"Coordinate professionally with the captain via ARINC regarding fuel requirements, critical point calculations, and alternate reserves."}'::jsonb,
  key_vocabulary = '[{"term":"ETOPS","definition_tr":"Extended-range Twin-engine Operations Performance Standards - ikili motorlu uçaklarda uzun menzilli operasyonlar için özel kurallar","definition_en":"Extended-range Twin-engine Operations Performance Standards - special rules for long-range operations with twin-engine aircraft"},{"term":"Critical Point (CP)","definition_tr":"İki alternate havaalanı arasındaki eşit uçuş zamanı noktası, ETOPS hesaplamalarında kritik","definition_en":"Equal-time point between two alternate airports, critical for ETOPS calculations"},{"term":"Tankering","definition_tr":"Dönüş uçuşu için fazla yakıt taşıma, yakıt maliyeti optimizasyonu","definition_en":"Carrying extra fuel for the return flight to optimize fuel costs"},{"term":"Headwind Component","definition_tr":"Uçuş yönüne karşı esen rüzgarın etkili bileşeni, yakıt tüketimini artırır","definition_en":"Effective component of wind opposing flight direction, increases fuel consumption"},{"term":"Fuel Reserves","definition_tr":"Acil durumlar ve diversion için planlanan minimum yakıt miktarı","definition_en":"Minimum fuel amount planned for emergencies and diversions"},{"term":"ARINC","definition_tr":"Aeronautical Radio Inc. - havacılıkta kullanılan VHF/HF radio haberleşme servisi","definition_en":"Aeronautical Radio Inc. - VHF/HF radio communication service used in aviation"},{"term":"Winds Aloft","definition_tr":"Farklı flight level''larda tahmin edilen rüzgar hızı ve yönü","definition_en":"Forecast wind speed and direction at different flight levels"},{"term":"Alternate Airport","definition_tr":"Hedef havaalanına iniş yapılamadığında kullanılacak yedek havaalanı","definition_en":"Backup airport to be used if landing at destination is not possible"}]'::jsonb,
  estimated_duration_seconds = 180,
  turns = '[{"atcStation":"CAPTAIN TURKISH 1453","atcUtterance":"Dispatch, Turkish 1453 heavy. We''ve reviewed the latest winds aloft for our ETOPS routing. Showing 120 knots headwind component at flight level 350. Request you recalculate critical point fuel and confirm adequate reserves for Keflavik and Shannon alternates.","correctionTr":"Kaptan''a yakıt hesaplamasını yapacağınızı ve ETOPS alternate havaalanları için yeterli rezerv kontrolü yapacağınızı onaylayın. ''Recalculate critical point fuel'' ve ''120 knot headwind at FL350'' bilgilerini readback edin.","expectedReadback":"Turkish 1453, Roger. I''ll recalculate the critical point fuel with 120 knot headwind at flight level 350 and verify reserves for Keflavik and Shannon. Stand by approximately five minutes.","frequency":"ARINC 131.550","hintTr":"Rüzgar değerini ve flight level bilgisini tekrar edin, sonra ne kadar süre beklenmesi gerektiğini belirtin.","id":"turn-1","isFinal":false,"keyPhrases":[["recalculate","re-calculate","calculate"],["critical point","CP"],["120","one two zero","one twenty"],["flight level 350","FL350","three five zero"],["Keflavik","KEF"],["Shannon","SNN"],["stand by","standby"]],"hint":{"text_tr":"Önce captain''ın talebini kabul et, sonra critical point fuel hesaplamasını yapacağını söyle. Rüzgar değerini (120 knot) ve flight level''ı (FL350) tekrarla, Keflavik ve Shannon alternate''lerini say. Yaklaşık 5 dakika bekleme süresini bildir.","text_en":"First acknowledge the captain''s request, then confirm you''ll recalculate critical point fuel. Repeat the wind value (120 knots) and flight level (FL350), mention Keflavik and Shannon alternates. Provide approximately 5 minutes waiting time."},"expected_response":{"text_en":"Turkish 1453, Roger. I''ll recalculate the critical point fuel with 120 knot headwind at flight level 350 and verify reserves for Keflavik and Shannon. Stand by approximately five minutes.","text_tr":"Captain''ın talebini onaylayıp, 120 knot headwind ve FL350 ile critical point fuel hesaplaması yapacağını, Keflavik ve Shannon için reserve kontrolü yapacağını söyle, 5 dakika bekleme iste.","must_include":["recalculate","critical point","120","flight level 350","fl350","keflavik","shannon","stand by","five minutes"]},"vocabulary_focus":["Critical Point (CP)","Headwind Component","Fuel Reserves","Alternate Airport"]},{"atcStation":"CAPTAIN TURKISH 1453","atcUtterance":"Dispatch, Turkish 1453. After recalculation, do we need additional tankering, or is planned fuel still adequate? Also confirm ETOPS critical fuel at 58 West is still above minimum required.","correctionTr":"Hesaplanan yakıt miktarının yeterli olduğunu ve 58 West noktasındaki ETOPS critical fuel değerinin minimum gerekliliğin üzerinde olduğunu bildirin. Ek tankering gerekmediğini belirtin.","expectedReadback":"Turkish 1453, based on updated winds, planned fuel remains adequate. ETOPS critical fuel at 58 West is 24,800 kilos, which is 1,200 kilos above minimum required. No additional tankering needed.","frequency":"ARINC 131.550","hintTr":"Critical fuel miktarını ve minimum üzerindeki farkı kilogram cinsinden verin.","id":"turn-2","isFinal":false,"keyPhrases":[["planned fuel","current fuel"],["adequate","sufficient"],["58 West","fifty-eight West"],["24,800","twenty-four thousand eight hundred","two four eight zero zero"],["1,200","one thousand two hundred","one two zero zero"],["above minimum","exceeds minimum"],["no additional","no extra"],["tankering"]],"hint":{"text_tr":"Güncel rüzgar hesaplamalarına göre planlanan yakıtın yeterli olduğunu belirt. 58 West noktasındaki ETOPS critical fuel miktarını (24,800 kg) ve minimum gerekliliğin kaç kilo üzerinde olduğunu (1,200 kg) söyle. Ek tankering gerekmediğini bildir.","text_en":"State that planned fuel remains adequate based on updated winds. Provide ETOPS critical fuel at 58 West (24,800 kg) and how much above minimum it is (1,200 kg). Confirm no additional tankering is needed."},"expected_response":{"text_en":"Turkish 1453, based on updated winds, planned fuel remains adequate. ETOPS critical fuel at 58 West is 24,800 kilos, which is 1,200 kilos above minimum required. No additional tankering needed.","text_tr":"Güncel rüzgarlara göre planlanan yakıtın yeterli olduğunu, 58 West''teki ETOPS critical fuel''in 24,800 kilo olduğunu ve minimum gerekliliğin 1,200 kilo üzerinde olduğunu söyle, ek tankering gerekmediğini belirt.","must_include":["planned fuel","adequate","58 west","24800","24,800","1200","1,200","above minimum","no additional","tankering"]},"vocabulary_focus":["ETOPS","Critical Point (CP)","Tankering","Fuel Reserves"]},{"atcStation":"CAPTAIN TURKISH 1453","atcUtterance":"Copy that, Dispatch. Confirm final figures: total fuel on board at departure and estimated fuel remaining at JFK touchdown.","correctionTr":"Kalkış yakıtı ve JFK''ye iniş anındaki tahmini kalan yakıt miktarlarını kilogram olarak onaylayın. Minimum reserve üzerindeki fazla yakıt miktarını da ekleyin.","expectedReadback":"Turkish 1453, confirmed. Total fuel at departure 98,500 kilos. Estimated fuel remaining at JFK touchdown 12,300 kilos. You have 3,500 kilos above minimum reserve.","frequency":"ARINC 131.550","hintTr":"İki ana rakamı net bir şekilde verin: departure fuel ve landing fuel. Reserve farkını da belirtin.","id":"turn-3","isFinal":true,"keyPhrases":[["98,500","ninety-eight thousand five hundred","nine eight five zero zero"],["departure"],["12,300","twelve thousand three hundred","one two three zero zero"],["JFK","Kennedy"],["touchdown","landing"],["3,500","three thousand five hundred","three five zero zero"],["above minimum","over minimum"],["reserve"]],"hint":{"text_tr":"Captain son rakamları doğrulatmak istiyor: kalkıştaki toplam yakıt miktarını ve JFK touchdown''daki tahmini kalan yakıt miktarını kilogram cinsinden bildir. ETOPS minimum reserve''lerin üzerinde olduğundan emin ol.","text_en":"Captain wants final figures confirmed: provide total fuel on board at departure and estimated fuel remaining at JFK touchdown in kilograms. Ensure you''re above ETOPS minimum reserves."},"expected_response":{"text_en":"Turkish 1453, affirm. Total fuel on board at departure: 112,400 kilos. Estimated fuel remaining at JFK touchdown: 18,600 kilos, which is 3,200 kilos above minimum reserve.","text_tr":"Kalkıştaki toplam yakıt miktarını (112,400 kg) ve JFK''ya inişte kalan tahmini yakıtı (18,600 kg) bildir, minimum reserve''in kaç kilo üzerinde olduğunu (3,200 kg) ekle.","must_include":["total fuel","departure","112400","112,400","18600","18,600","jfk","touchdown","3200","above minimum","reserve"]},"vocabulary_focus":["Fuel Reserves","ETOPS","Winds Aloft"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'etops-fuel-calculation-dispatcher';

UPDATE public.scenarios SET
  briefing = '{"tr":"Final approach 27R''dasın, ancak önündeki trafik pisti henüz boşaltmamış. Tower go-around emri veriyor ve seni yeniden sequencing için approach''a yönlendirecek.","en":"You are on final approach to runway 27R, but preceding traffic has not vacated the runway yet. Tower instructs a go-around and will hand you off to approach for re-sequencing."}'::jsonb,
  learner_role = '{"tr":"Sen Turkish Airlines 1453 callsign''ı ile uçan pilot olarak final approach''ta go-around talimatı alıyorsun ve frekans değişimi yapıyorsun.","en":"You are the pilot flying as Turkish Airlines 1453, receiving go-around instructions on final approach and performing frequency change."}'::jsonb,
  objective = '{"tr":"Go-around emrini doğru read-back et ve approach frekansına geçiş yap.","en":"Execute proper go-around read-back and switch to approach frequency."}'::jsonb,
  key_vocabulary = '[{"term":"go-around","definition_tr":"İniş iptali ve yeniden tırmanış manevrası","definition_en":"Aborted landing and climb maneuver"},{"term":"runway heading","definition_tr":"Pistin manyetik yönü doğrultusunda uçuş","definition_en":"Flight direction aligned with runway magnetic heading"},{"term":"re-sequencing","definition_tr":"Yeniden trafik sırasına alma işlemi","definition_en":"Process of re-ordering traffic for another approach"},{"term":"final approach","definition_tr":"İniş öncesi son yaklaşma fazı","definition_en":"Final phase of approach before landing"},{"term":"contact approach","definition_tr":"Approach kontrolü ile temas kurma emri","definition_en":"Instruction to establish communication with approach control"},{"term":"vacate","definition_tr":"Pisti boşaltma, pistten ayrılma","definition_en":"To clear or exit the runway"},{"term":"read-back","definition_tr":"ATC talimatını tekrarlayarak onaylama","definition_en":"Repeating ATC instruction for confirmation"},{"term":"tower","definition_tr":"Havaalanı kontrol kulesi","definition_en":"Airport control tower"}]'::jsonb,
  estimated_duration_seconds = 120,
  turns = '[{"atcStation":"TOWER","atcUtterance":"Turkish 1453, go around. Climb runway heading to 3000 feet.","correctionTr":"Go-around emrini hemen ve standart: \"Going around\" + tırmanış talimatı + callsign.","expectedReadback":"Going around, runway heading climb 3000 feet, Turkish 1453.","frequency":"118.1","hintTr":"Go-around aciliyettir — read-back hemen ve net olmalı.","id":"turn-1","keyPhrases":[["go around","going around","go-around"],["runway heading","runway track"],["3000","three thousand","3 thousand"],["feet","ft"],["turkish"]],"hint":{"text_tr":"Go-around acil bir durumdur. Önce \"Going around\" de, sonra tırmanış talimatını tekrarla ve callsign''ınla bitir. Hızlı ve net konuş.","text_en":"Go-around is urgent. First say \"Going around\", then repeat climb instructions and end with your callsign. Be quick and clear."},"expected_response":{"text_en":"Going around, runway heading climb 3000 feet, Turkish 1453.","text_tr":"İptal edip tırmanıyorum, pist yönünde 3000 feet''e çıkacağım.","must_include":["going around","go around","runway heading","runway track","3000","three thousand","feet","turkish"]},"vocabulary_focus":["go-around","runway heading","final approach"]},{"atcStation":"TOWER","atcUtterance":"Turkish 1453, contact approach 124 decimal 35 for re-sequencing.","correctionTr":"Frekans değişiminde sadece frekansı + callsign söyle: \"124 decimal 35, Turkish 1453\".","expectedReadback":"124 decimal 35, Turkish 1453.","frequency":"118.1","id":"turn-2","isFinal":true,"keyPhrases":[["124","one two four","one twenty four"],["decimal","point"],["35","three five","thirty five"],["turkish"]],"hint":{"text_tr":"Frekans değişimi çok basit: sadece yeni frekansı tekrarla ve callsign''ını ekle. Fazladan kelime kullanma.","text_en":"Frequency change is simple: just repeat the new frequency and add your callsign. Don''t add extra words."},"expected_response":{"text_en":"124 decimal 35, Turkish 1453.","text_tr":"124.35 frekansına geçiyorum.","must_include":["124","one two four","decimal","point","35","three five","turkish"]},"vocabulary_focus":["contact approach","re-sequencing","read-back"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'go-around-final';

UPDATE public.scenarios SET
  briefing = '{"tr":"Ankara yaklaşmasına girdiniz ancak trafik yoğunluğu nedeniyle approach sizi VECON noktasında holding pattern''a aldı. EFC zamanı verilecek ve hava koşulları nedeniyle holding yönünü değiştirmeniz gerekebilir.","en":"You are entering Ankara airspace but due to traffic congestion, approach has instructed you to enter a holding pattern at VECON. You will receive an EFC time and may need to adjust your holding direction due to weather."}'::jsonb,
  learner_role = '{"tr":"Sen Turkish Airlines 1453 callsign''ı ile uçan pilot olarak Ankara Approach ile haberleşiyorsun ve holding instructions''ı alıp doğru read-back yapman gerekiyor.","en":"You are the pilot flying as Turkish 1453, communicating with Ankara Approach and required to acknowledge holding instructions with proper read-back."}'::jsonb,
  objective = '{"tr":"Holding clearance''ı doğru read-back yap, EFC zamanını onayla ve hava koşulları nedeniyle holding pattern değişikliğini kabul et.","en":"Correctly read back holding clearance, confirm EFC time, and accept holding pattern modification due to weather."}'::jsonb,
  key_vocabulary = '[{"term":"holding pattern","definition_tr":"Belirlenen bir nokta üzerinde bekleme manevrası yapmak, genellikle trafik yoğunluğu veya hava koşulları nedeniyle","definition_en":"A predetermined maneuver to keep an aircraft within a specified airspace while awaiting further clearance"},{"term":"as published","definition_tr":"Yayınlanmış prosedüre göre, chart''ta gösterildiği şekilde","definition_en":"According to the procedure shown in official charts or documentation"},{"term":"EFC (Expect Further Clearance)","definition_tr":"İleriye dönük clearance bekleme zamanı, holding''den çıkış için tahmini zaman","definition_en":"The time a pilot can expect to receive further clearance, typically to leave the holding pattern"},{"term":"Zulu time","definition_tr":"UTC zaman dilimi, koordineli evrensel zaman (aviation''da standart)","definition_en":"UTC timezone, Coordinated Universal Time used as standard in aviation"},{"term":"read-back correct","definition_tr":"Pilot''un tekrarladığı talimatın doğru olduğunu controller''ın onaylaması","definition_en":"Confirmation by controller that the pilot''s read-back of instructions was accurate"},{"term":"reverse direction","definition_tr":"Holding pattern''ın yönünü tersine çevirmek (soldan sağa veya sağdan sola)","definition_en":"To change the holding pattern from left turns to right turns or vice versa"},{"term":"weather building","definition_tr":"Hava koşullarının kötüleşmesi, fırtına veya bulut gelişimi","definition_en":"Weather conditions developing or intensifying, typically storms or cloud formation"},{"term":"affirm / affirmative","definition_tr":"Evet anlamında ICAO standart onay ifadesi (''yes'' yerine kullanılır)","definition_en":"Standard ICAO phraseology for ''yes'' to confirm or acknowledge"}]'::jsonb,
  estimated_duration_seconds = 135,
  turns = '[{"atcStation":"ANKARA APPROACH","atcUtterance":"Turkish 1453, hold at VECON as published, expect further clearance one-two-four-five Zulu.","correctionTr":"Standart read-back: ''Hold at VECON as published, expect further clearance one-two-four-five Zulu, Turkish 1453.'' Çağrı kodunu cümle sonunda söyle, EFC zamanını her zaman tekrarla.","expectedReadback":"Hold at VECON as published, expect further clearance one-two-four-five Zulu, Turkish 1453.","frequency":"120.9","hintTr":"EFC = Expect Further Clearance. Saati ICAO formatında oku: \"one-two-four-five\".","id":"turn-1","keyPhrases":[["hold","holding"],["vecon"],["as published"],["expect further clearance","further clearance","efc"],["one two four five","1245","12 45","twelve forty five"],["zulu","z"],["turkish","thy"],["1453","one four five three"]],"hint":{"text_tr":"Holding clearance''ı tam olarak tekrarla: nokta adı, ''as published'', EFC zamanı (ICAO formatında dört rakam ayrı ayrı oku), ''Zulu'' de ve callsign''ı sonda söyle.","text_en":"Repeat the holding clearance completely: fix name, ''as published'', EFC time (read four digits individually in ICAO format), say ''Zulu'', and callsign at the end."},"expected_response":{"text_en":"Hold at VECON as published, expect further clearance one-two-four-five Zulu, Turkish 1453.","text_tr":"VECON''da yayınlanmış prosedüre göre bekle, saat 12:45 UTC''de ileri clearance bekle, callsign.","must_include":["hold","vecon","as published","expect further clearance","one two four five","zulu","turkish","1453"]},"vocabulary_focus":["holding pattern","as published","EFC (Expect Further Clearance)","Zulu time"]},{"atcStation":"ANKARA APPROACH","atcUtterance":"Turkish 1453, read-back correct.","correctionTr":"Sadece çağrı kodunu söyle: \"Turkish 1453\".","expectedReadback":"Turkish 1453.","frequency":"120.9","id":"turn-2","keyPhrases":[["turkish"],["1453","one four five three"]],"hint":{"text_tr":"Controller read-back''inin doğru olduğunu söylüyor. Sadece callsign''ını söyleyerek onaylaman yeterli.","text_en":"Controller confirms your read-back was correct. Simply acknowledge with your callsign only."},"expected_response":{"text_en":"Turkish 1453.","text_tr":"Callsign''ını söyleyerek kısa onay ver.","must_include":["turkish","1453"]},"vocabulary_focus":["read-back correct"]},{"atcStation":"ANKARA APPROACH","atcUtterance":"Turkish 1453, weather building south. Suggest reverse direction in hold. Confirm if able.","correctionTr":"Sapmayı \"Affirm\" ile onayla, sonra ne yapacağını tekrarla: \"Affirm reversing hold direction\".","expectedReadback":"Affirm reversing hold direction, Turkish 1453.","frequency":"120.9","id":"turn-3","isFinal":true,"keyPhrases":[["affirm","affirmative","yes"],["reverse","reversing","reverse direction"],["hold","holding"],["turkish"],["1453","one four five three"]],"hint":{"text_tr":"Güneyde hava kötüleşiyor ve controller holding yönünü değiştirmeni öneriyor. ''Affirm'' diyerek kabul et ve ''reversing hold direction'' ile ne yapacağını tekrarla, sonra callsign.","text_en":"Weather is building to the south and controller suggests reversing your holding direction. Say ''Affirm'' to accept and repeat ''reversing hold direction'', then callsign."},"expected_response":{"text_en":"Affirm reversing hold direction, Turkish 1453.","text_tr":"''Affirm'' ile onaylayıp holding yönünü değiştireceğini söyle ve callsign ekle.","must_include":["affirm","reversing","hold","direction","turkish","1453"]},"vocabulary_focus":["affirm / affirmative","reverse direction","weather building"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'holding-vecon';

UPDATE public.scenarios SET
  briefing = '{"tr":"Ankara Esenboğa''da ground frequency üzerinde taxi clearance alacak ve runway''e yaklaşacaksınız. Tower frekansına geçiş yapana kadar tüm talimatları ICAO fonetik alfabe ile doğru şekilde readback yapmanız gerekiyor.","en":"You will receive taxi clearance on ground frequency at Ankara Esenboğa and approach the runway. You must provide correct readback using ICAO phonetic alphabet for all instructions until handoff to tower frequency."}'::jsonb,
  learner_role = '{"tr":"Sen Turkish November Papa Bravo callsign''ı ile uçan bir öğrenci pilot olarak kontrollü havalimanında ilk solo taxi pratiklerini yapıyorsun.","en":"You are a student pilot with callsign Turkish November Papa Bravo performing your first solo taxi practice at a controlled airport."}'::jsonb,
  objective = '{"tr":"Ground controller''ın verdiği taxi instructions ve frequency change talimatlarını ICAO standardında doğru readback yapın.","en":"Provide correct ICAO-standard readback of taxi instructions and frequency changes given by ground controller."}'::jsonb,
  key_vocabulary = '[{"term":"readback","definition_tr":"Pilot''un aldığı talimatı controller''a tekrar ederek doğruladığı prosedür","definition_en":"Procedure where pilot repeats instructions back to controller for verification"},{"term":"taxi clearance","definition_tr":"Havalimanı yüzeyinde hareket etmek için verilen izin","definition_en":"Authorization to move on the airport surface"},{"term":"hold short","definition_tr":"Belirtilen noktadan önce durup bekleme talimatı","definition_en":"Instruction to stop and wait before a specified point"},{"term":"taxiway","definition_tr":"Uçakların yerde hareket ettiği yollar (Alpha, Bravo, Charlie gibi harflerle adlandırılır)","definition_en":"Paths where aircraft move on ground (named with letters like Alpha, Bravo, Charlie)"},{"term":"cross runway","definition_tr":"Aktif runway''i geçmek için verilen izin","definition_en":"Authorization to cross an active runway"},{"term":"contact","definition_tr":"Farklı bir frekansa geçerek o controller ile haberleşmeye başlama","definition_en":"Switch to a different frequency and begin communication with that controller"},{"term":"stand","definition_tr":"Uçağın park edeceği apron pozisyonu","definition_en":"Apron position where aircraft will park"},{"term":"ICAO phonetic alphabet","definition_tr":"Havacılıkta harf karışıklığını önlemek için kullanılan standart telaffuz sistemi (A=Alpha, B=Bravo, vb.)","definition_en":"Standard pronunciation system used in aviation to avoid letter confusion (A=Alpha, B=Bravo, etc.)"}]'::jsonb,
  estimated_duration_seconds = 120,
  turns = '[{"atcStation":"ANKARA GROUND","atcUtterance":"Turkish November Papa Bravo, taxi via Alpha, Bravo, hold short of runway Three Five Left.","correctionTr":"Taksi talimatını fonetik alfabeyle tekrar edin: Alpha, Bravo taksi yollarından, runway Three Five Left öncesi hold short. Callsign''ınızı sonda ekleyin.","expectedReadback":"Taxi via Alpha, Bravo, hold short of runway Three Five Left, Turkish November Papa Bravo.","frequency":"121.7","hintTr":"ICAO fonetik alfabesini harfleri söylerken kullanın: A=Alpha, B=Bravo, N=November, P=Papa.","id":"turn-1","isFinal":false,"keyPhrases":[["taxi","taxiing"],["alpha"],["bravo"],["hold short","holding short"],["runway","rwy"],["three five left","35 left","three-five-left"],["november papa bravo","NPB"]],"hint":{"text_tr":"Taxi clearance''ı taxiway isimleriyle birlikte tekrar edin. Hold short talimatı önemli - runway numarasını da ekleyin. Callsign''ınızı cümlenin sonuna koyun.","text_en":"Repeat the taxi clearance with taxiway names. The hold short instruction is critical - include the runway number. Put your callsign at the end of the sentence."},"expected_response":{"text_en":"Taxi via Alpha, Bravo, hold short of runway Three Five Left, Turkish November Papa Bravo.","text_tr":"Alpha ve Bravo taxiway''lerinden runway Three Five Left öncesinde dur, Turkish November Papa Bravo.","must_include":["taxi","alpha","bravo","hold short","runway","three five left","november papa bravo"]},"vocabulary_focus":["readback","taxi clearance","hold short","taxiway","ICAO phonetic alphabet"]},{"atcStation":"ANKARA GROUND","atcUtterance":"Turkish November Papa Bravo, cross runway Three Five Left, taxi to stand Delta Two via Charlie, Whiskey.","correctionTr":"Runway''i geçme ve stand talimatını tekrar edin: runway Three Five Left''i cross, Charlie ve Whiskey üzerinden Delta Two stand''a taxi. Fonetik alfabeyi doğru kullanın.","expectedReadback":"Cross runway Three Five Left, taxi to stand Delta Two via Charlie, Whiskey, Turkish November Papa Bravo.","frequency":"121.7","hintTr":"C=Charlie, D=Delta, W=Whiskey fonetik karşılıklarını unutmayın.","id":"turn-2","isFinal":false,"keyPhrases":[["cross","crossing"],["runway","rwy"],["three five left","35 left","three-five-left"],["taxi","taxiing"],["stand","gate","parking"],["delta two","delta 2","D2"],["charlie"],["whiskey"],["november papa bravo","NPB"]],"hint":{"text_tr":"Önce runway''i cross etme iznini, sonra hangi taxiway''lerden geçerek hangi stand''a gideceğinizi belirtin. Tüm harfleri fonetik alfabeyle söyleyin.","text_en":"First state the runway crossing clearance, then which taxiways to use and which stand to go to. Use phonetic alphabet for all letters."},"expected_response":{"text_en":"Cross runway Three Five Left, taxi to stand Delta Two via Charlie, Whiskey, Turkish November Papa Bravo.","text_tr":"Runway Three Five Left''i geç, Charlie ve Whiskey üzerinden Delta Two stand''a taxi yap, Turkish November Papa Bravo.","must_include":["cross","runway","three five left","taxi","stand","delta two","charlie","whiskey","november papa bravo"]},"vocabulary_focus":["cross runway","stand","taxiway","ICAO phonetic alphabet"]},{"atcStation":"ANKARA GROUND","atcUtterance":"Turkish November Papa Bravo, contact Ankara Tower on One One Eight Decimal Niner.","correctionTr":"Frekans değişimi talimatını tekrar edin: Ankara Tower ile One One Eight Decimal Niner frekansında contact kurun. Callsign''ı sonda söyleyin.","expectedReadback":"Contact Ankara Tower on One One Eight Decimal Niner, Turkish November Papa Bravo.","frequency":"121.7","hintTr":"Frekansları her rakamı ayrı söyleyerek okuyun: 118.9 = One One Eight Decimal Niner.","id":"turn-3","isFinal":true,"keyPhrases":[["contact"],["ankara tower","tower"],["one one eight","118"],["decimal","point"],["niner","nine"],["november papa bravo","NPB"]],"hint":{"text_tr":"Frequency change talimatını onaylayın. Frekansı rakam rakam okuyun: 118.9 → One One Eight Decimal Niner. Tower ile contact kuracağınızı belirtin.","text_en":"Acknowledge the frequency change. Read frequency digit by digit: 118.9 → One One Eight Decimal Niner. State that you will contact tower."},"expected_response":{"text_en":"Contact Ankara Tower on One One Eight Decimal Niner, Turkish November Papa Bravo.","text_tr":"Ankara Tower ile One One Eight Decimal Niner frekansında contact kur, Turkish November Papa Bravo.","must_include":["contact","ankara tower","one one eight","decimal","niner","november papa bravo"]},"vocabulary_focus":["contact","readback","ICAO phonetic alphabet"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'icao-phonetic-alphabet-drill-b1';

UPDATE public.scenarios SET
  briefing = '{"tr":"İstanbul Havalimanı''nda apron''da bir Turkish Airlines A320 uçağı Gate 12''ye yaklaşıyor. Sen marshaller olarak uçağı güvenli bir şekilde park pozisyonuna yönlendirecek ve parking prosedürünü tamamlayacaksın.","en":"A Turkish Airlines A320 is approaching Gate 12 at Istanbul Airport. You are the marshaller responsible for guiding the aircraft safely to its parking position and completing the parking procedure."}'::jsonb,
  learner_role = '{"tr":"Sen İstanbul Havalimanı apron''unda görevli bir marshaller''sın ve TK1923 callsign''lı A320 uçağını Gate 12''ye park ettiriyorsun.","en":"You are a marshaller at Istanbul Airport guiding Turkish Airlines flight TK1923, an Airbus A320, to park at Gate 12."}'::jsonb,
  objective = '{"tr":"Uçağı standart marshalling signals ve radio communication kullanarak güvenli şekilde park pozisyonuna yönlendir ve parking prosedürünü tamamla.","en":"Guide the aircraft safely to its parking position using standard marshalling signals and radio communication, then complete the parking procedure."}'::jsonb,
  key_vocabulary = '[{"term":"marshaller","definition_tr":"Apron''da uçakları el işaretleriyle park pozisyonuna yönlendiren personel","definition_en":"Ground personnel who guides aircraft to parking positions using hand signals"},{"term":"gate","definition_tr":"Yolcu bindirme/indirme için kullanılan terminal kapısı ve park pozisyonu","definition_en":"Terminal position where aircraft park for passenger boarding/deboarding"},{"term":"marshalling signals","definition_tr":"Uçak yönlendirmede kullanılan standart el işaretleri","definition_en":"Standardized hand signals used to guide aircraft movement"},{"term":"chocks","definition_tr":"Uçak tekerlerinin önüne/arkasına yerleştirilen güvenlik takozları","definition_en":"Wedge-shaped blocks placed in front of/behind aircraft wheels to prevent movement"},{"term":"shutdown engines","definition_tr":"Motorları kapatma işlemi","definition_en":"Procedure to turn off aircraft engines"},{"term":"taxi","definition_tr":"Uçağın kendi gücüyle yerde hareket etmesi","definition_en":"Movement of an aircraft on the ground under its own power"},{"term":"stop position","definition_tr":"Uçağın park etmek için durması gereken nihai nokta","definition_en":"Final point where aircraft must stop for parking"},{"term":"apron","definition_tr":"Uçakların park ettiği, yükleme/boşaltma yapılan platform alanı","definition_en":"Area where aircraft are parked, loaded, and unloaded"}]'::jsonb,
  estimated_duration_seconds = 180,
  turns = '[{"atcStation":"TK1923 PILOT","atcUtterance":"Ground, Turkish 1923, approaching Gate 12, request marshalling.","correctionTr":"Pilot''a marshaller''ın hazır olduğunu ve taksi''ye devam edip işaretlerini takip etmesi gerektiğini söyleyin. ''Marshaller ready, continue taxi, follow my signals'' deyin.","expectedReadback":"Turkish 1923, marshaller ready, continue taxi, follow my signals.","frequency":"129.6","hintTr":"Pilot''a hazır olduğunuzu bildirin ve işaretlerinizi takip etmesini isteyin.","id":"turn-1","isFinal":false,"keyPhrases":[["marshaller ready","ready"],["continue taxi","continue","taxi"],["follow","signals","my signals"]],"hint":{"text_tr":"Pilot marshalling talebinde bulunuyor. Hazır olduğunu bildir ve işaretlerini takip etmesini iste. ''Marshaller ready, continue taxi, follow my signals'' ifadesini kullan.","text_en":"Pilot is requesting marshalling. Confirm you''re ready and instruct them to continue taxi and follow your signals."},"expected_response":{"text_en":"Turkish 1923, marshaller ready, continue taxi, follow my signals","text_tr":"Pilot''a marshaller''ın hazır olduğunu söyle, taksi''ye devam edip işaretleri takip etsin","must_include":["marshaller ready","ready","continue taxi","continue","taxi","follow","signals","my signals"]},"vocabulary_focus":["marshaller","taxi","marshalling signals"]},{"atcStation":"TK1923 PILOT","atcUtterance":"Continuing taxi, following your signals, Turkish 1923.","correctionTr":"Uçağa yavaşlamasını ve duruş noktasına 10 metre kaldığını bildirin. ''Roger, slow down, ten meters to stop'' deyin.","expectedReadback":"Turkish 1923, roger, slow down, ten meters to stop.","frequency":"129.6","hintTr":"Uçak yaklaşıyor, yavaşlatıp mesafeyi bildirin.","id":"turn-2","isFinal":false,"keyPhrases":[["roger","copied","affirm"],["slow down","reduce speed"],["ten meters","10 meters","ten metres"],["stop","stopping position"]],"hint":{"text_tr":"Uçak gate''e yaklaşıyor. Yavaşlamasını söyle ve stop position''a 10 metre kaldığını bildir. ''Roger, slow down, ten meters to stop'' de.","text_en":"Aircraft is approaching the gate. Tell them to slow down and inform them they''re 10 meters from the stop position."},"expected_response":{"text_en":"Turkish 1923, roger, slow down, ten meters to stop","text_tr":"Onay ver, yavaşlamasını söyle ve durma noktasına 10 metre kaldığını bildir","must_include":["roger","copied","affirm","slow down","reduce speed","ten meters","10 meters","ten metres","stop","stopping position"]},"vocabulary_focus":["stop position","slow down","roger"]},{"atcStation":"TK1923 PILOT","atcUtterance":"Slowing down, Turkish 1923.","correctionTr":"Uçağa durmasını, takozların yerinde olduğunu ve motorları kapatmasını söyleyin. ''Stop, chocks in place, shutdown engines'' deyin.","expectedReadback":"Turkish 1923, stop, chocks in place, shutdown engines.","frequency":"129.6","hintTr":"Uçak durdu, şimdi park prosedürünü tamamlayın.","id":"turn-3","isFinal":true,"keyPhrases":[["stop"],["chocks","chocks in place","chocked"],["shutdown","shut down","engines"]],"hint":{"text_tr":"Uçak stop position''a ulaştı. Durmasını emret, chocks''ların yerinde olduğunu bildir ve motorları kapatmasını söyle.","text_en":"Aircraft has reached the stop position. Command them to stop, confirm chocks are in place, and instruct engine shutdown."},"expected_response":{"text_en":"Turkish 1923, stop, chocks in place, shutdown engines","text_tr":"Uçağa dur de, takozların yerinde olduğunu söyle ve motorları kapatmasını iste","must_include":["stop","chocks","chocks in place","chocked","shutdown","shut down","engines","shutdown engines"]},"vocabulary_focus":["chocks","shutdown engines","stop"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'marshalling-aircraft-to-gate-b1';

UPDATE public.scenarios SET
  briefing = '{"tr":"Sol motorda yangın çıktı ve acil iniş yapman gerekiyor. ATC ile derhal MAYDAY bildirimi yaparak en yakın havalimanına yönlendirilmeyi talep edeceksin.","en":"You have an engine fire on the left engine and need to declare an emergency. You must make a MAYDAY call to ATC and request immediate vectors to the nearest suitable airport."}'::jsonb,
  learner_role = '{"tr":"Sen Turkish Airlines 1453 callsign''lı bir havayolu pilot''usun ve İstanbul yaklaşma kontrolü ile iletişim halinde acil durum bildirimi yapacaksın.","en":"You are the pilot of Turkish Airlines flight 1453 and must declare an emergency with Istanbul approach control due to an engine fire."}'::jsonb,
  objective = '{"tr":"ICAO standartlarına uygun şekilde MAYDAY çağrısı yap ve acil iniş için yönlendirme talep et.","en":"Make a proper MAYDAY call following ICAO standards and request vectors for an emergency landing."}'::jsonb,
  key_vocabulary = '[{"term":"MAYDAY","definition_tr":"En yüksek öncelikli acil durum çağrısı, 3 kez tekrar edilir (distress call)","definition_en":"The highest priority emergency call, repeated three times (distress call)"},{"term":"engine fire","definition_tr":"Motor yangını - havada kritik bir acil durum","definition_en":"A critical in-flight emergency involving fire in the engine"},{"term":"vectors","definition_tr":"ATC tarafından verilen heading talimatları (yönlendirme)","definition_en":"Heading instructions provided by ATC for navigation"},{"term":"descending","definition_tr":"İniş yapma, alçalma durumu","definition_en":"The act of decreasing altitude"},{"term":"nearest airport","definition_tr":"En yakın iniş yapılabilir havalimanı","definition_en":"The closest suitable airport for landing"},{"term":"approach","definition_tr":"Yaklaşma kontrolü - terminal area''da uçakları yöneten ATC ünitesi","definition_en":"Approach control - ATC unit managing aircraft in terminal area"},{"term":"callsign","definition_tr":"Uçağın radyo iletişiminde kullanılan kimlik kodu","definition_en":"Aircraft identification used in radio communication"},{"term":"PAN-PAN","definition_tr":"MAYDAY''den bir alt seviye acil durum çağrısı (urgency call)","definition_en":"Urgency call, one level below MAYDAY distress call"}]'::jsonb,
  estimated_duration_seconds = 120,
  turns = '[{"atcStation":"YOU","atcUtterance":"[Acil durum bildirimi yap — MAYDAY çağrısı]","correctionTr":"MAYDAY çağrısı 3 kez tekrar edilir, sonra istasyon, callsign, problem, niyetin (descending/turning) ve istek (vectors/clearance).","expectedReadback":"Mayday, Mayday, Mayday, Istanbul approach, Turkish 1453, engine fire, descending, request immediate vectors to nearest airport.","frequency":"121.5","hintTr":"MAYDAY = en yüksek aciliyet. PAN-PAN ondan bir alt seviye.","id":"turn-1","isFinal":true,"keyPhrases":[["mayday","may day"],["istanbul","ist"],["turkish"],["1453","one four five three"],["engine fire","fire engine","engine on fire"],["descending","descend"],["vectors","vector","heading"],["nearest airport","nearest field","closest airport"]],"hint":{"text_tr":"MAYDAY kelimesini 3 kez tekrarla, sonra sırasıyla: hangi istasyon, senin callsign''ın, problemin ne, ne yapıyorsun (descending), ne istiyorsun (vectors/en yakın havalimanı).","text_en":"Say MAYDAY three times, then state: which station, your callsign, nature of emergency, what you''re doing (descending), and what you need (vectors to nearest airport)."},"expected_response":{"text_en":"Mayday, Mayday, Mayday, Istanbul approach, Turkish 1453, engine fire, descending, request immediate vectors to nearest airport.","text_tr":"3 kez Mayday, hangi ATC istasyonu, callsign''ın, motor yangını var, alçalıyorsun ve en yakın havalimanına yönlendirme istiyorsun.","must_include":["mayday","may day","istanbul","ist","turkish","1453","one four five three","engine fire","fire","engine on fire","descending","descend","vectors","vector","heading","nearest airport","nearest field","closest airport","immediate"]},"vocabulary_focus":["MAYDAY","engine fire","descending","vectors","nearest airport"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'mayday-engine-fire';

UPDATE public.scenarios SET
  briefing = '{"tr":"Istanbul Approach''ta tıbbi emergency bildiren Turkish 1453 (B737, Atina''dan geliyor) runway 35L''ye priority landing talep ediyor. Sen controller olarak emergency''yi acknowledge edip koordinasyon ve vectoring sağlamalısın.","en":"You are Istanbul Approach Controller. Turkish 1453, a B737 inbound from Athens, has declared a medical emergency with an unconscious passenger and requests priority landing at runway 35L."}'::jsonb,
  learner_role = '{"tr":"Sen Istanbul Approach controller olarak Turkish 1453 (B737) için tıbbi emergency prosedürünü uyguluyorsun.","en":"You are Istanbul Approach Controller handling a medical emergency for Turkish 1453 (B737)."}'::jsonb,
  objective = '{"tr":"Tıbbi emergency''yi doğru prosedürle yönet: squawk ata, vectoring ver, bilgi topla ve ground services koordine et.","en":"Manage the medical emergency with proper procedures: assign squawk, provide vectors, gather information, and coordinate ground services."}'::jsonb,
  key_vocabulary = '[{"term":"roger your emergency","definition_tr":"Emergency durumunu teyit etme ifadesi, acil durumu anladığınızı gösterir","definition_en":"Phrase acknowledging an emergency situation"},{"term":"squawk 7700","definition_tr":"Emergency transponder kodu, radar''da öncelik sağlar","definition_en":"Emergency transponder code for priority handling"},{"term":"souls on board (POB)","definition_tr":"Uçaktaki toplam kişi sayısı (yolcu + mürettebat), emergency planlama için kritik","definition_en":"Total number of people aboard (passengers + crew), critical for emergency planning"},{"term":"fuel endurance","definition_tr":"Kalan yakıtla uçabileceği süre (saat/dakika), emergency''de zaman yönetimi için önemli","definition_en":"Remaining flight time based on fuel, important for emergency time management"},{"term":"vectors","definition_tr":"Controller tarafından verilen heading talimatları, yaklaşma için yönlendirme","definition_en":"Heading instructions provided by controller for guidance"},{"term":"ILS approach","definition_tr":"Instrument Landing System yaklaşması, hassas iniş için alet yaklaşması","definition_en":"Instrument Landing System approach for precision landing"},{"term":"QNH","definition_tr":"Deniz seviyesi basıncı, altimetre ayarı için kullanılır","definition_en":"Sea level pressure setting for altimeter"},{"term":"standing by","definition_tr":"Hazır beklemek, ground services''in hazır olduğunu belirtir (ambulance, fire truck vb.)","definition_en":"Ready and waiting, indicates ground services are prepared"}]'::jsonb,
  estimated_duration_seconds = 180,
  turns = '[{"atcStation":"TURKISH 1453","atcUtterance":"Istanbul Approach, Turkish 1453, we have a medical emergency on board, one passenger unconscious, request priority landing runway 35L.","correctionTr":"Emergency''yi acknowledge edin, squawk 7700 verin, altitude talimatı (FL180 maintain), yaklaşma için vectoring belirtin (ILS 35L), ve souls on board ile fuel endurance sorun. Emergency handling''de her bilgi kritik.","expectedReadback":"Turkish 1453, Istanbul Approach, roger your emergency, squawk 7700, maintain flight level 180, expect vectors for ILS approach runway 35L, confirm souls on board and fuel endurance.","frequency":"119.1","hintTr":"Acil durumda metodlu olun: önce emergency''yi teyit, sonra squawk, sonra talimat, sonra bilgi isteyin.","id":"turn-1","isFinal":false,"keyPhrases":[["roger","copied","acknowledge","affirm"],["emergency","mayday"],["squawk 7700","7700"],["maintain","flight level 180","FL180","one eight zero"],["vectors","vector"],["ILS","runway 35L","three five left"],["souls on board","POB","persons on board"],["fuel","endurance","fuel remaining"]],"hint":{"text_tr":"Emergency''yi önce teyit et (roger/copied), sonra squawk 7700 ata, altitude talimatı ver (FL180 maintain), ILS vectoring belirt ve kritik bilgileri sor (souls on board, fuel).","text_en":"First acknowledge the emergency, assign squawk 7700, give altitude instruction, advise vectors for ILS, and request critical information (souls on board, fuel endurance)."},"expected_response":{"text_en":"Turkish 1453, Istanbul Approach, roger your emergency, squawk 7700, maintain flight level 180, expect vectors for ILS approach runway 35L, confirm souls on board and fuel endurance.","text_tr":"Emergency''yi teyit et, squawk 7700 ver, FL180''de kal, 35L için ILS vektörleri bekle, souls on board ve fuel endurance bildir.","must_include":["roger","emergency","squawk 7700","maintain","flight level 180","vectors","ils","runway 35l","souls on board","fuel"]},"vocabulary_focus":["roger your emergency","squawk 7700","souls on board","fuel endurance","vectors"]},{"atcStation":"TURKISH 1453","atcUtterance":"Squawking 7700, maintaining flight level 180, 156 souls on board, fuel endurance 2 hours 15 minutes, Turkish 1453.","correctionTr":"Heading talimatı (left 280), descent clearance (8000 feet ile QNH), ve medical assistance + fire services''in hazır olduğunu bildirin. Emergency handling''de koordinasyon gösterin.","expectedReadback":"Turkish 1453, roger, turn left heading 280, descend to altitude 8000 feet, QNH 1013, medical assistance and fire services will be standing by.","frequency":"119.1","hintTr":"Pilot rahatlatılmalı: hem talimat net, hem de yerde hazırlık olduğunu bilin.","id":"turn-2","isFinal":false,"keyPhrases":[["roger","copied"],["turn left","left turn"],["heading 280","two eight zero"],["descend","descent"],["8000 feet","eight thousand","8000"],["QNH 1013","one zero one three"],["medical","assistance","ambulance"],["fire services","rescue","emergency services"],["standing by","stand by","ready"]],"hint":{"text_tr":"Bilgileri teyit et (roger), heading talimatı ver (left 280), descent clearance ver (8000 feet + QNH), ve ground services''in hazır olduğunu bildir (medical + fire services standing by).","text_en":"Acknowledge information, provide heading (left 280), issue descent clearance (8000 feet + QNH), and confirm ground services are ready (medical + fire services standing by)."},"expected_response":{"text_en":"Turkish 1453, roger, turn left heading 280, descend to altitude 8000 feet, QNH 1013, medical assistance and fire services will be standing by.","text_tr":"Bilgileri al, sola 280 heading''e dön, 8000 feet''e in, QNH 1013, tıbbi yardım ve itfaiye hazır bekliyor.","must_include":["roger","turn left","heading 280","descend","8000 feet","qnh 1013","medical","fire services","standing by"]},"vocabulary_focus":["QNH","descend","heading","medical assistance","standing by"]},{"atcStation":"TURKISH 1453","atcUtterance":"Left heading 280, descending to 8000 feet, QNH 1013, thank you for assistance, Turkish 1453.","correctionTr":"Frekans değişikliği verin (Istanbul Tower 118.7) ve nazikçe bitirin. Emergency transfer''de Tower ile koordinasyonu sağladığınızı gösterin.","expectedReadback":"Turkish 1453, contact Istanbul Tower on 118.7, good day.","frequency":"119.1","hintTr":"Tüm prosedürü tamamladınız, şimdi Tower''a güvenle devredin.","id":"turn-3","isFinal":true,"keyPhrases":[["contact","call"],["Istanbul Tower","tower"],["118.7","one one eight decimal seven","one one eight point seven"],["good day","good afternoon"]],"hint":{"text_tr":"Tüm prosedür tamamlandı, şimdi Tower''a transfer et (118.7 frekansı ver) ve nazikçe bitir. Emergency durumunda Tower ile koordinasyon sağlandığını göster.","text_en":"All procedures complete, now transfer to Tower (frequency 118.7) and close professionally. Show coordination with Tower for emergency handling."},"expected_response":{"text_en":"Turkish 1453, contact Istanbul Tower on 118.7, good day.","text_tr":"Istanbul Tower''a 118.7''den geç, iyi günler.","must_include":["contact","istanbul tower","118.7","good day"]},"vocabulary_focus":["contact","frequency"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'medical-emergency-priority-handling-l4';

UPDATE public.scenarios SET
  briefing = '{"tr":"Istanbul havalimanında hat teknisyeni olarak rutin dispatch işlemi sırasında kaptan hidrolik kaçak bildirdi. MEL''e danışıp maintenance control ile koordinasyon yaparak uçağın dispatch edilip edilemeyeceğine karar vereceksin.","en":"As a line technician at Istanbul airport during routine dispatch, the captain has reported a hydraulic leak. You must consult the MEL and coordinate with maintenance control to determine if the aircraft is dispatchable."}'::jsonb,
  learner_role = '{"tr":"Sen Istanbul havalimanında hat teknisyeni olarak TC-1453 kuyruk numaralı uçağın dispatch işlemini yürütüyorsun","en":"You are the line technician at Istanbul airport handling dispatch procedures for aircraft TC-1453"}'::jsonb,
  objective = '{"tr":"MEL prosedürlerini uygulayarak hidrolik kaçak olan uçağın güvenli dispatch kararını ver","en":"Apply MEL procedures to make a safe dispatch decision for an aircraft with a hydraulic leak"}'::jsonb,
  key_vocabulary = '[{"term":"MEL (Minimum Equipment List)","definition_tr":"Belirli arızalar ile uçuşa devam edilebileceğini gösteren onaylı ekipman listesi","definition_en":"Approved list showing which equipment failures allow continued flight operations"},{"term":"dispatch","definition_tr":"Uçağın uçuşa hazır olduğuna dair teknik onay ve yetkilendirme süreci","definition_en":"Technical approval and authorization process confirming aircraft is ready for flight"},{"term":"hydraulic leak","definition_tr":"Hidrolik sistemde sıvı kaybına neden olan arıza durumu","definition_en":"Failure condition causing fluid loss in the hydraulic system"},{"term":"main gear","definition_tr":"Ana iniş takımı, uçağın ağırlığını taşıyan tekerlek sistemi","definition_en":"Main landing gear assembly that supports the aircraft''s weight"},{"term":"maintenance control","definition_tr":"Bakım operasyonlarını koordine eden ve teknik karar veren merkez","definition_en":"Central authority coordinating maintenance operations and technical decisions"},{"term":"leak rate","definition_tr":"Kaçağın birim zamandaki akış hızı veya miktarı","definition_en":"Flow rate or quantity of leakage per unit of time"},{"term":"walk-around","definition_tr":"Uçuş öncesi pilot veya teknisyen tarafından yapılan görsel dış kontrol","definition_en":"Pre-flight visual external inspection performed by pilot or technician"},{"term":"stand by","definition_tr":"Bekleyin, hazır olun anlamında kullanılan standart havacılık ifadesi","definition_en":"Standard aviation phrase meaning wait or be ready"}]'::jsonb,
  estimated_duration_seconds = 150,
  turns = '[{"atcStation":"CAPTAIN","atcUtterance":"Good morning, we found a small hydraulic leak on the left main gear. Can you check if this is MEL acceptable for dispatch?","correctionTr":"Kaptan''a MEL''e bakacağınızı ve maintenance control ile iletişime geçeceğinizi bildirin. ''Stand by'' deyin.","expectedReadback":"Good morning Captain, I will check the MEL and contact maintenance control, stand by please.","frequency":"Ground Comm","hintTr":"Kibarca onaylayın ve beklemesini isteyin.","id":"turn-1","isFinal":false,"keyPhrases":[["check","consult","review"],["MEL"],["maintenance control","control","maintenance"],["stand by","standby","wait"]],"hint":{"text_tr":"Kaptana kibarca durumu aldığını bildir, MEL''e bakacağını ve maintenance control ile iletişime geçeceğini söyle, beklemesini iste","text_en":"Politely acknowledge the captain, inform that you will check MEL and contact maintenance control, ask to stand by"},"expected_response":{"text_en":"Good morning Captain, I will check the MEL and contact maintenance control, stand by please","text_tr":"Günaydın kaptan, MEL''e bakacağım ve bakım kontrol ile iletişime geçeceğim, lütfen bekleyin","must_include":["check","consult","mel","maintenance control","maintenance","stand by","standby"]},"vocabulary_focus":["MEL","maintenance control","stand by"]},{"atcStation":"MAINTENANCE CONTROL","atcUtterance":"Go ahead, what is the issue?","correctionTr":"Sorunu açıklayın: hidrolik kaçak, hangi uçak, MEL dispatch onayı istiyorsunuz.","expectedReadback":"We have a hydraulic leak on the left main gear, aircraft Tango Charlie 1453, requesting MEL guidance for dispatch.","frequency":"Maintenance Freq","hintTr":"Durum raporunu net verin.","id":"turn-2","isFinal":false,"keyPhrases":[["hydraulic leak","hydraulic","leak"],["left main gear","main gear","gear"],["MEL","guidance"],["dispatch"]],"hint":{"text_tr":"Maintenance control''e durumu net ve tam bildir: hangi sistem arızalı, uçak kimliği, MEL dispatch kılavuzu istediğini söyle","text_en":"Report clearly to maintenance control: which system has the fault, aircraft identity, request MEL dispatch guidance"},"expected_response":{"text_en":"We have a hydraulic leak on the left main gear, aircraft Tango Charlie 1453, requesting MEL guidance for dispatch","text_tr":"Sol ana iniş takımında hidrolik kaçak var, uçak Tango Charlie 1453, dispatch için MEL kılavuzu talep ediyorum","must_include":["hydraulic leak","hydraulic","leak","left main gear","main gear","mel","guidance","dispatch"]},"vocabulary_focus":["hydraulic leak","main gear","dispatch"]},{"atcStation":"MAINTENANCE CONTROL","atcUtterance":"Roger, that leak is acceptable under MEL item 29-21. You may dispatch with conditions: observe leak rate, no increase permitted. Confirm understood.","correctionTr":"MEL maddesini ve koşulları tekrarlayın: kaçak hızı izlenecek, artış olmayacak, dispatch yapılacak.","expectedReadback":"Understood, MEL item 29-21 acceptable, observe leak rate, no increase. We will dispatch. Thank you.","frequency":"Maintenance Freq","hintTr":"Readback ile onaylayın ve teşekkür edin.","id":"turn-3","isFinal":true,"keyPhrases":[["understood","roger","copied"],["MEL","29-21","item"],["observe","monitor"],["leak rate","leak"],["no increase"],["dispatch"]],"hint":{"text_tr":"Maintenance control''ün verdiği MEL maddesini ve koşulları tekrarla: madde numarası, kaçak hızı izleme, artış yasağı, dispatch onayı","text_en":"Read back the MEL item and conditions from maintenance control: item number, leak rate monitoring, no increase allowed, dispatch approval"},"expected_response":{"text_en":"Understood, MEL item 29-21 acceptable, observe leak rate, no increase, we will dispatch, thank you","text_tr":"Anlaşıldı, MEL maddesi 29-21 kabul edilebilir, kaçak hızı izlenecek, artış yok, dispatch yapacağız, teşekkürler","must_include":["understood","roger","mel","29-21","item","observe","monitor","leak rate","leak","no increase","dispatch"]},"vocabulary_focus":["MEL","leak rate","dispatch"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'mel-item-dispatch-decision-b1';

UPDATE public.scenarios SET
  briefing = '{"tr":"Turkish 847 dispatcher olarak kaptan ve first officer''a İstanbul''dan London Heathrow''a yapılacak uçuş için weather briefing veriyorsun. METAR ve TAF bilgilerini ICAO formatında iletmen ve crew''un sorularını yanıtlaman gerekiyor.","en":"As dispatcher for Turkish 847, you brief the captain and first officer on weather conditions for their Istanbul to London Heathrow flight. You must deliver METAR and TAF information in ICAO format and answer crew questions."}'::jsonb,
  learner_role = '{"tr":"Sen Turkish 847 flight dispatcher''ısın ve crew''a departure ve destination havaalanları için weather briefing veriyorsun.","en":"You are the flight dispatcher for Turkish 847, providing weather briefing to the crew for departure and destination airports."}'::jsonb,
  objective = '{"tr":"Kaptan''a METAR ve TAF bilgilerini doğru ICAO phraseology ile ilet ve arrival time''daki weather conditions hakkında bilgi ver.","en":"Deliver METAR and TAF information to the captain using proper ICAO phraseology and advise on weather conditions during arrival time."}'::jsonb,
  key_vocabulary = '[{"term":"METAR","definition_tr":"Belirli bir havaalanı için düzenli aralıklarla yayınlanan güncel hava durumu raporu.","definition_en":"Aviation Routine Weather Report issued at regular intervals for a specific airport."},{"term":"TAF","definition_tr":"Terminal Aerodrome Forecast - havaalanı için belirli bir süre (genellikle 6-30 saat) geçerli hava tahmin raporu.","definition_en":"Terminal Aerodrome Forecast - weather forecast valid for a specific period (typically 6-30 hours) at an airport."},{"term":"gusting","definition_tr":"Rüzgar hızının ani ve kısa süreli artışları; örneğin ''20 knots gusting 30'' demek ortalama 20, anlık 30 knot rüzgar demek.","definition_en":"Rapid and brief increases in wind speed; e.g., ''20 knots gusting 30'' means average 20, peak gusts to 30 knots."},{"term":"visibility","definition_tr":"Havada görüş mesafesi, genellikle kilometre veya statute mile cinsinden ifade edilir.","definition_en":"The distance one can see through the atmosphere, typically expressed in kilometers or statute miles."},{"term":"QNH","definition_tr":"Deniz seviyesine indirgenmiş basınç değeri; altimetre ayarı için kullanılır.","definition_en":"Atmospheric pressure adjusted to sea level; used for altimeter setting."},{"term":"broken clouds","definition_tr":"BKN - gökyüzünün 5/8 ile 7/8''ini kaplayan bulut katmanı.","definition_en":"BKN - cloud layer covering 5/8 to 7/8 of the sky."},{"term":"TEMPO","definition_tr":"TAF içinde geçici değişiklikleri belirtir; belirtilen koşulların 1 saatten az süreceği tahmin edilir.","definition_en":"Indicates temporary fluctuations in TAF; conditions expected to last less than 1 hour at a time."},{"term":"overcast","definition_tr":"OVC - gökyüzünün tamamını (8/8) kaplayan bulut örtüsü.","definition_en":"OVC - cloud cover obscuring the entire sky (8/8 coverage)."}]'::jsonb,
  estimated_duration_seconds = 150,
  turns = '[{"atcStation":"CAPTAIN","atcUtterance":"Good morning, Dispatch. Turkish 847. Could you give us the current weather for Istanbul and our destination, London Heathrow?","correctionTr":"Kaptan''a İstanbul ve Heathrow METAR bilgilerini net şekilde ilet. Rüzgar yönü/hızı, visibility, bulut durumu, sıcaklık ve QNH değerlerini içermelisin. Örnek: ''Istanbul METAR: winds 270 at 15 knots, visibility 10 kilometers...''","expectedReadback":"Good morning, Captain. Istanbul METAR shows winds two seven zero at one five knots, visibility one zero kilometers, few clouds at two thousand feet, temperature one eight, QNH one zero one three. Heathrow METAR winds two five zero at two zero knots gusting three zero, visibility eight kilometers in light rain, broken clouds at one thousand two hundred feet, temperature one two, QNH nine nine eight.","frequency":null,"hintTr":"METAR okurken sayıları gruplayarak söyle, Heathrow''da gusting var, bunu belirt.","id":"turn-1","isFinal":false,"keyPhrases":[["winds","wind"],["two seven zero","270"],["one five","15"],["visibility","vis"],["one zero kilometers","10 kilometers","10km"],["few clouds","few"],["two thousand","2000"],["temperature","temp"],["one eight","18"],["QNH","altimeter"],["one zero one three","1013"],["Heathrow"],["two five zero","250"],["two zero","20","twenty"],["gusting","gust"],["three zero","30","thirty"],["eight kilometers","8 kilometers","8km"],["light rain","rain"],["broken","BKN"],["one thousand two hundred","1200"],["one two","12"],["nine nine eight","998"]],"hint":{"text_tr":"İki havaalanının METAR''larını sırayla ver. Rüzgar, visibility, bulut, sıcaklık ve QNH bilgilerini eksiksiz oku. Heathrow''da gusting var, bunu vurgula.","text_en":"Provide METAR for both airports in sequence. Include wind, visibility, clouds, temperature, and QNH. Emphasize gusting at Heathrow."},"expected_response":{"text_en":"Good morning, Captain. Istanbul METAR shows winds two seven zero at one five knots, visibility one zero kilometers, few clouds at two thousand feet, temperature one eight, QNH one zero one three. Heathrow METAR winds two five zero at two zero knots gusting three zero, visibility eight kilometers in light rain, broken clouds at one thousand two hundred feet, temperature one two, QNH nine nine eight.","text_tr":"Kaptan''a günaydın diyerek İstanbul METAR''ını ver: rüzgar 270 derece 15 knot, görüş 10 kilometre, 2000 feet''te az bulut, sıcaklık 18, QNH 1013. Ardından Heathrow METAR''ı: rüzgar 250 derece 20 knot gusting 30, görüş 8 kilometre hafif yağmurda, 1200 feet''te broken bulutlar, sıcaklık 12, QNH 998.","must_include":["winds","two seven zero","one five","visibility","one zero kilometers","few clouds","two thousand","temperature","one eight","qnh","one zero one three","heathrow","two five zero","two zero","gusting","three zero","eight kilometers","light rain","broken","one thousand two hundred","one two","nine nine eight"]},"vocabulary_focus":["METAR","gusting","visibility","QNH","broken clouds"]},{"atcStation":"CAPTAIN","atcUtterance":"Copy that. What does the TAF say for Heathrow around our arrival time, roughly one three zero zero Zulu?","correctionTr":"TAF''ı özetle: geçerlilik süresi, 1200Z''den itibaren rüzgar/visibility/bulut durumu, TEMPO koşulları ve 1500Z''den sonra iyileşme. Kaptan varış saatine (1300Z) odaklanıyor, o zaman dilimini vurgula.","expectedReadback":"Heathrow TAF valid from zero six to one eight Zulu. From one two zero zero, winds two six zero at two two knots gusting three five, visibility six kilometers in moderate rain, broken clouds at one thousand feet, temporarily visibility four kilometers, overcast at eight hundred feet. Conditions improving after one five zero zero with winds two seven zero at one eight knots, visibility more than ten kilometers.","frequency":null,"hintTr":"TAF okurken zaman gruplarını (FROM, TEMPO) açıkça belirt, Kaptan''ın varış saatini kapsayan bölümü öne çıkar.","id":"turn-2","isFinal":false,"keyPhrases":[["TAF"],["valid","validity"],["zero six","06","0600"],["one eight","18","1800"],["from one two zero zero","1200","twelve hundred"],["two six zero","260"],["two two","22"],["gusting","gust"],["three five","35"],["six kilometers","6 kilometers","6km"],["moderate rain","rain"],["broken"],["one thousand","1000"],["temporarily","tempo","TEMPO"],["four kilometers","4 kilometers","4km"],["overcast","OVC"],["eight hundred","800"],["improving","improve"],["one five zero zero","1500","fifteen hundred"],["two seven zero","270"],["one eight","18"],["more than ten","greater than 10","10 plus"]],"hint":{"text_tr":"TAF''ın geçerlilik süresini belirt, sonra 1200Z''den itibaren koşulları oku. TEMPO ile geçici kötüleşmeyi, 1500Z sonrası iyileşmeyi açıkça söyle. Kaptan 1300Z arrival planladığı için o zaman dilimini vurgula.","text_en":"State TAF validity period, then read conditions from 1200Z. Clearly mention TEMPO deterioration and improvement after 1500Z. Emphasize the timeframe around 1300Z for the captain''s arrival."},"expected_response":{"text_en":"Heathrow TAF valid from zero six to one eight Zulu. From one two zero zero, winds two six zero at two two knots gusting three five, visibility six kilometers in moderate rain, broken clouds at one thousand feet, temporarily visibility four kilometers, overcast at eight hundred feet. Conditions improving after one five zero zero with winds two seven zero at one eight knots, visibility more than ten kilometers.","text_tr":"Heathrow TAF''ı 06''dan 18 Zulu''ya kadar geçerli. 1200Z''den itibaren rüzgar 260 derece 22 knot gusting 35, görüş 6 kilometre orta şiddette yağmurda, 1000 feet''te broken bulutlar, geçici olarak görüş 4 kilometre ve 800 feet''te overcast. 1500Z sonrası koşullar iyileşiyor: rüzgar 270 derece 18 knot, görüş 10 kilometrenin üzerinde.","must_include":["taf","valid","zero six","one eight","zulu","one two zero zero","two six zero","two two","gusting","three five","six kilometers","moderate rain","broken","one thousand","temporarily","four kilometers","overcast","eight hundred","one five zero zero","two seven zero","one eight","more than ten"]},"vocabulary_focus":["TAF","TEMPO","overcast","gusting","valid"]},{"atcStation":"CAPTAIN","atcUtterance":"Understood. So we can expect low visibility and gusty winds on arrival. Do you recommend any alternate or extra fuel?","correctionTr":"Kaptan''a alternate havalimanı (Gatwick) ve yakıt planını açıkla. Holding fuel ve alternate fuel eklendiğini, toplam yakıt miktarını (23,000 kg) net söyle. ''Affirm'' ile başla, tavsiyeni belirt.","expectedReadback":"Affirm, Captain. I recommend Gatwick as alternate. Weather there is better, winds light, visibility good. I have already added one five minutes holding fuel and alternate fuel to your flight plan. Total fuel uplift is two three thousand kilograms.","frequency":null,"hintTr":"Dispatcher olarak yakıt planını önceden hazırladın, Kaptan''a güven ver: alternate Gatwick, ekstra holding fuel var, toplam 23,000 kg.","id":"turn-3","isFinal":true,"keyPhrases":[["affirm","affirmative","yes","correct"],["recommend","suggest"],["Gatwick"],["alternate","ALT"],["weather","conditions"],["better"],["winds light","light winds"],["visibility good","good visibility"],["added","included"],["one five minutes","15 minutes","fifteen minutes"],["holding fuel","holding"],["alternate fuel"],["flight plan","FPL"],["total fuel","fuel uplift"],["two three thousand","23000","23 thousand"],["kilograms","kg","kgs"]]}]'::jsonb,
  updated_at = now()
WHERE slug = 'metar-taf-briefing-to-flight-crew';

UPDATE public.scenarios SET
  briefing = '{"tr":"Türk hava yolu şirketinde pilot alım mülakatındasınız. Interview panel standart operasyonel ve davranışsal sorular soracak, cevaplarınız profesyonel ve yapılandırılmış olmalı.","en":"You are attending a pilot job interview with a Turkish airline. The interview panel will ask standard operational and behavioral questions requiring professional, structured responses."}'::jsonb,
  learner_role = '{"tr":"Sen pilot adayı olarak mülakat paneli karşısında standart soru-cevap oturumundasın","en":"You are a pilot candidate responding to standard interview questions from the panel"}'::jsonb,
  objective = '{"tr":"Operasyonel deneyim, CRM becerileri ve şirkete uygunluğu gösteren profesyonel cevaplar ver","en":"Provide professional answers demonstrating operational experience, CRM skills, and company fit"}'::jsonb,
  key_vocabulary = '[{"term":"MEL (Minimum Equipment List)","definition_tr":"Belirli ekipmanlar arızalı olsa da uçağın güvenli şekilde uçmasına izin veren liste","definition_en":"A list that allows an aircraft to fly safely with certain equipment inoperative"},{"term":"CRM (Crew Resource Management)","definition_tr":"Ekip kaynaklarının etkin kullanımı, iletişim ve karar verme yönetimi","definition_en":"Effective use of crew resources, communication, and decision-making management"},{"term":"diversion","definition_tr":"Planlı varış yerine alternatif havaalanına yönlenme","definition_en":"Redirecting to an alternate airport instead of the planned destination"},{"term":"anti-ice systems","definition_tr":"Uçakta buz oluşumunu önleyen sistemler (kanat, motor, pitot)","definition_en":"Aircraft systems that prevent ice formation (wing, engine, pitot)"},{"term":"pushback","definition_tr":"Uçağın gate''ten geriye itilmesi işlemi","definition_en":"The procedure of pushing the aircraft backward from the gate"},{"term":"dispatch","definition_tr":"Uçağın uçuşa elverişli olup olmadığının belirlenmesi ve uçuş planlaması","definition_en":"Determining aircraft airworthiness and flight planning"},{"term":"discrepancy","definition_tr":"Teknik log''da raporlanması gereken uyumsuzluk veya arıza","definition_en":"A malfunction or irregularity that must be reported in the technical log"},{"term":"PIC (Pilot in Command)","definition_tr":"Uçuştan sorumlu kaptan pilot","definition_en":"The captain pilot responsible for the flight"}]'::jsonb,
  estimated_duration_seconds = 180,
  turns = '[{"atcStation":"INTERVIEW PANEL","atcUtterance":"Good morning. Thank you for coming. Can you tell us about your most challenging flight experience and how you handled it?","correctionTr":"Zorlayıcı bir uçuş deneyiminizi anlatın: durumu (örneğin buzlanma, weather, teknik arıza), aldığınız aksiyonları (ATC koordinasyonu, sistem kullanımı, diversion kararı) ve sonucu belirtin. Cevabınız yapılandırılmış ve profesyonel olmalı.","expectedReadback":"Good morning. Thank you for having me. My most challenging experience was during a winter flight when we encountered unexpected severe icing conditions. I immediately coordinated with ATC, requested lower altitude, activated all anti-ice systems, and informed the cabin crew. We diverted to the nearest suitable airport safely.","frequency":null,"hintTr":"Gerçek bir uçuş olayını düşünün ve CRM prensiplerini vurgulayarak açıklayın.","id":"turn-1","isFinal":false,"keyPhrases":[["most challenging","difficult","hardest"],["icing","ice","winter"],["ATC","air traffic control"],["diverted","diversion","alternate"],["safely","safe landing"]],"hint":{"text_tr":"Gerçek bir zorlayıcı uçuş durumunu seç (hava şartları, teknik sorun, ya da operasyonel zorluk). Durumu kısaca tanımla, aldığın aksiyonları CRM prensipleriyle açıkla ve sonucu belirt.","text_en":"Select a real challenging flight situation (weather, technical issue, or operational difficulty). Briefly describe the situation, explain your actions using CRM principles, and state the outcome."},"expected_response":{"text_en":"Good morning, thank you for having me. My most challenging experience was during a winter flight when we encountered unexpected severe icing conditions. I immediately coordinated with ATC, requested lower altitude, activated all anti-ice systems, and informed the cabin crew. We diverted to the nearest suitable airport safely.","text_tr":"Günaydın, teşekkürler. En zorlayıcı deneyimim kış uçuşunda beklenmedik şiddetli buzlanma yaşadığımız andı. Hemen ATC ile koordine oldum, daha düşük irtifa talep ettim, tüm anti-ice sistemleri devreye aldım ve kabin ekibini bilgilendirdim. En yakın uygun havaalanına güvenle divert ettik.","must_include":["challenging","most difficult","icing","ice conditions","atc","air traffic control","coordinated","anti-ice","diverted","diversion","safely","safe landing"]},"vocabulary_focus":["CRM","anti-ice systems","diversion","ATC"]},{"atcStation":"INTERVIEW PANEL","atcUtterance":"I see. Now, what would you do if you discovered a significant MEL item just before pushback that the previous crew didn''t report?","correctionTr":"MEL item bulduğunuzda yapmanız gerekenleri sıralayın: Kaptan''a bilgi verme, MEL''i kontrol etme, maintenance ve ops ile iletişim, safety/dispatch durumunu değerlendirme, ve doğru dökümantasyon. SOP''lara uygun prosedür önemli.","expectedReadback":"I would immediately inform the captain if I''m the first officer. We would review the MEL together to determine if the item is dispatchable. I would contact maintenance and operations to report the discrepancy. If it affects safety or dispatch, we would delay the flight until resolved. Proper documentation is essential.","frequency":null,"hintTr":"Ekip koordinasyonu, prosedür takibi ve safety kültürünü vurgulayın.","id":"turn-2","isFinal":false,"keyPhrases":[["inform","notify","tell"],["captain","PIC"],["MEL","minimum equipment list"],["maintenance","engineer","technician"],["safety","dispatch"],["documentation","report","log"]],"hint":{"text_tr":"MEL item bulduğunda izlemen gereken prosedürü adım adım açıkla: önce kaptanı bilgilendir, MEL''i kontrol et, maintenance ve operations ile iletişime geç, safety ve dispatch durumunu değerlendir, gerekli dökümantasyonu yap.","text_en":"Explain the procedure step-by-step when finding an MEL item: inform the captain first, check the MEL, contact maintenance and operations, assess safety and dispatch status, complete proper documentation."},"expected_response":{"text_en":"I would immediately inform the captain if I''m the first officer. We would review the MEL together to determine if the item is dispatchable. I would contact maintenance and operations to report the discrepancy. If it affects safety or dispatch, we would delay the flight until resolved. Proper documentation is essential.","text_tr":"First officer isem hemen kaptanı bilgilendiririm. Item''ın dispatch edilebilir olup olmadığını anlamak için MEL''i birlikte kontrol ederiz. Discrepancy''yi raporlamak için maintenance ve operations ile iletişime geçerim. Safety veya dispatch''i etkiliyorsa çözülene kadar uçuşu geciktiririz. Doğru dökümantasyon şarttır.","must_include":["inform","notify","captain","pic","mel","minimum equipment list","review","check","maintenance","operations","discrepancy","safety","dispatch","documentation","delay"]},"vocabulary_focus":["MEL","PIC","dispatch","discrepancy","pushback"]},{"atcStation":"INTERVIEW PANEL","atcUtterance":"Very good. Final question: Why do you want to fly for our airline specifically, and what can you bring to our team?","correctionTr":"Şirketi neden seçtiğinizi (safety kültürü, filo, network) ve siz ne katabileceğinizi (teknik beceri, CRM, takım ruhu, tecrübe) açıklayın. Samimi ve profesyonel bir ton kullanın. Bu soru motivasyonunuzu ve uyumunuzu ölçer.","expectedReadback":"I have great respect for your airline''s safety culture and modern fleet. Your international network offers excellent career development. I bring strong technical skills, good CRM abilities, and experience in multi-cultural environments. I''m a team player who values professionalism and continuous learning. I would be honored to contribute to your operation.","frequency":null,"hintTr":"Şirket hakkında bilginizi ve kişisel güçlü yönlerinizi dengeli şekilde sunun.","id":"turn-3","isFinal":true,"keyPhrases":[["safety culture","safety","reputation"],["fleet","aircraft","modern"],["career","development","growth"],["CRM","crew resource management","teamwork"],["team player","contribute","professional"]],"hint":{"text_tr":"İki bölümlü cevap ver: 1) Şirketi neden seçtiğini açıkla (safety kültürü, filo tipi, network, eğitim standartları gibi somut nedenler). 2) Senin ne katabileceğini belirt (teknik beceriler, CRM tecrübesi, takım çalışması, önceki deneyimler).","text_en":"Give a two-part answer: 1) Explain why you chose the company (safety culture, fleet type, network, training standards - concrete reasons). 2) State what you can contribute (technical skills, CRM experience, teamwork, previous experience)."},"expected_response":{"text_en":"I''m impressed by your airline''s strong safety culture and modern fleet. Your extensive route network offers excellent career development opportunities. I can bring five years of international flying experience, strong CRM skills, and experience with Boeing and Airbus types. I''m a team player committed to continuous learning and maintaining the highest professional standards.","text_tr":"Şirketinizin güçlü safety kültürü ve modern filosu beni etkiledi. Geniş route network''ünüz mükemmel kariyer gelişim fırsatları sunuyor. Beş yıllık uluslararası uçuş tecrübesi, güçlü CRM becerileri ve Boeing ile Airbus tip tecrübesi getirebilirim. Sürekli öğrenmeye ve en yüksek profesyonel standartları korumaya bağlı bir takım oyuncusuyum.","must_include":["safety culture","fleet","modern","network","route","experience","crm","crew resource management","team","teamwork","professional","standards","learning"]},"vocabulary_focus":["CRM","safety culture","fleet","professional standards"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'mock-pilot-interview-qa-b2';

UPDATE public.scenarios SET
  briefing = '{"tr":"Turkish 2468 (IST–AMS) uçuşu için yeni bir NOTAM yayınlandı: runway 35L bakım nedeniyle kapalı. Dispatcher olarak kaptana pist değişikliği, revised slot ve performance bilgilerini iletmelisiniz.","en":"A new NOTAM has been issued for Turkish 2468 (IST–AMS): runway 35L is closed for maintenance. As dispatcher, you must brief the captain on the runway change, revised slot, and performance implications."}'::jsonb,
  learner_role = '{"tr":"Sen Turkish 2468 (IST–AMS) uçuşunun dispatcher''ısın ve kaptana NOTAM bilgilerini, runway değişikliğini ve yeni departure slot''unu bildiriyorsun.","en":"You are the dispatcher for Turkish 2468 (IST–AMS), briefing the captain on NOTAM information, runway change, and new departure slot."}'::jsonb,
  objective = '{"tr":"NOTAM detaylarını açıkça ilet, runway değişikliğini onayla ve performance bilgilerini doğrula.","en":"Clearly communicate NOTAM details, confirm runway change, and verify performance information."}'::jsonb,
  key_vocabulary = '[{"term":"NOTAM","definition_tr":"Notice to Airmen – pilotlara operasyonel değişiklikler hakkında resmi bildirim","definition_en":"Notice to Airmen – official notification of operational changes to pilots"},{"term":"slot","definition_tr":"Tahsis edilmiş kalkış veya iniş zaman aralığı","definition_en":"Assigned departure or arrival time window"},{"term":"runway closure","definition_tr":"Pistin bakım veya operasyonel sebeplerle kullanıma kapatılması","definition_en":"Runway unavailable for operations due to maintenance or other reasons"},{"term":"takeoff performance","definition_tr":"Uçağın ağırlık, pist uzunluğu ve hava koşullarına göre kalkış kabiliyeti","definition_en":"Aircraft capability to take off based on weight, runway length, and weather conditions"},{"term":"loadsheet","definition_tr":"Uçağın ağırlık ve balans verilerini içeren resmi dokuman","definition_en":"Official document containing aircraft weight and balance data"},{"term":"FMS","definition_tr":"Flight Management System – uçuş yönetim bilgisayar sistemi","definition_en":"Flight Management System – computerized flight management system"},{"term":"wilco","definition_tr":"Will comply – talimatı anlayıp uygulayacağım anlamında kısaltma","definition_en":"Will comply – acknowledgment that instruction is understood and will be executed"},{"term":"revised","definition_tr":"Değiştirilmiş, güncellenmiş (slot, route vb.)","definition_en":"Changed or updated (slot, route, etc.)"}]'::jsonb,
  estimated_duration_seconds = 150,
  turns = '[{"atcStation":"CAPTAIN","atcUtterance":"Ops, Turkish 2468, good morning. We''re ready for departure briefing, go ahead.","correctionTr":"Kaptana NOTAM''ı açıkça bildirmelisiniz: hangi pist kapalı (35L), hangi piste geçiliyor (35R), ve yeni slot saati (0815 Zulu).","expectedReadback":"Turkish 2468, morning Captain. New NOTAM issued, runway 35L closed for maintenance from 0800 to 1000 Zulu. Departure now from runway 35R, revised slot 0815.","frequency":"OPS","hintTr":"NOTAM detaylarını net ve sırayla verin.","id":"turn-1","isFinal":false,"keyPhrases":[["notam","new notam"],["35L","three five left","runway 35L"],["closed","closure"],["35R","three five right","runway 35R"],["0815","zero eight one five","revised slot"]],"hint":{"text_tr":"Dispatcher olarak NOTAM''ı sırayla bildir: hangi pist kapalı, kapanış süresi, yeni pist ve yeni slot saati. Açık ve net ol.","text_en":"As dispatcher, present the NOTAM in sequence: which runway is closed, closure time, new runway, and revised slot. Be clear and precise."},"expected_response":{"text_en":"Turkish 2468, morning Captain. New NOTAM issued, runway 35L closed for maintenance from 0800 to 1000 Zulu. Departure now from runway 35R, revised slot 0815.","text_tr":"Kaptana günaydın de, NOTAM''ı bildir: 35L pisti 0800-1000 Zulu arası kapalı, kalkış 35R''den olacak, yeni slot 0815.","must_include":["notam","new notam","35l","three five left","runway 35l","closed","closure","maintenance","35r","three five right","runway 35r","0815","zero eight one five","revised slot","zulu"]},"vocabulary_focus":["NOTAM","runway closure","slot","revised"]},{"atcStation":"CAPTAIN","atcUtterance":"Copy 35R and 0815 Zulu. Will the runway length affect our takeoff performance with current weight?","correctionTr":"Kaptanın sorusunu yanıtlayın: 35R pistinin uzunluğu (3000 metre) mevcut ağırlık için yeterli mi, performance hesabı normal mi?","expectedReadback":"Negative Captain, 35R length is 3000 meters, sufficient for your current weight. Performance data confirms normal takeoff.","frequency":"OPS","hintTr":"Pist uzunluğunu ve performance onayını açıkça belirtin.","id":"turn-2","isFinal":false,"keyPhrases":[["negative","no"],["35R","three five right"],["3000","three thousand"],["meters","metres"],["sufficient","enough","adequate"],["performance","takeoff performance"],["normal","confirms"]],"hint":{"text_tr":"Kaptanın performance sorusunu yanıtla: 35R pistinin uzunluğu mevcut ağırlık için yeterli mi? Performance verilerini onayla.","text_en":"Answer the captain''s performance question: is runway 35R length sufficient for current weight? Confirm performance data."},"expected_response":{"text_en":"Negative Captain, 35R length is 3000 meters, sufficient for your current weight. Performance data confirms normal takeoff.","text_tr":"Hayır kaptan, sorun yok: 35R 3000 metre, mevcut ağırlık için yeterli. Performance normal kalkış gösteriyor.","must_include":["negative","no","35r","three five right","3000","three thousand","meters","metres","sufficient","enough","adequate","current weight","performance","takeoff performance","normal","confirms"]},"vocabulary_focus":["takeoff performance","runway closure","FMS"]},{"atcStation":"CAPTAIN","atcUtterance":"Roger that, we''ll update the FMS for 35R. Please send revised loadsheet to the aircraft.","correctionTr":"Kaptanın isteğini onaylayın (wilco), loadsheet''in ne zaman gönderileceğini (beş dakika) ve ground frekansını (121.9) bildirin.","expectedReadback":"Wilco Captain, revised loadsheet will be uploaded in five minutes. Contact ground on 121.9 when ready to push.","frequency":"OPS","hintTr":"İşlemi onaylayın ve yer frekansını verin.","id":"turn-3","isFinal":true,"keyPhrases":[["wilco","will comply","roger"],["loadsheet","load sheet"],["uploaded","sent","send"],["five minutes","5 minutes"],["ground","contact ground"],["121.9","one two one decimal nine"]],"hint":{"text_tr":"Kaptanın loadsheet isteğini onayla (wilco), ne zaman gönderileceğini söyle ve ground frekansını bildir.","text_en":"Acknowledge the captain''s loadsheet request (wilco), state when it will be sent, and provide ground frequency."},"expected_response":{"text_en":"Wilco Captain, revised loadsheet will be uploaded in five minutes. Contact ground on 121.9 when ready to push.","text_tr":"Anlaşıldı kaptan, güncellenmiş loadsheet beş dakikada yüklenecek. Push için hazır olunca ground 121.9''u ara.","must_include":["wilco","will comply","roger","loadsheet","load sheet","revised","uploaded","sent","send","five minutes","5 minutes","ground","contact ground","121.9","one two one decimal nine","push"]},"vocabulary_focus":["wilco","loadsheet","revised","slot"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'notam-runway-closure-briefing';

UPDATE public.scenarios SET
  briefing = '{"tr":"Ankara yakınlarında training flight sırasında Approach ve Tower ile iletişim kuracaksınız. Altitude, heading ve frequency değişikliklerini doğru şekilde readback yaparak sayı telaffuzu pratiği yapacaksınız.","en":"During a training flight near Ankara, you will communicate with Approach and Tower. Practice correct number pronunciation while reading back altitude, heading, and frequency changes."}'::jsonb,
  learner_role = '{"tr":"Sen Student One Two Three callsign''ı ile uçan bir öğrenci pilotusun ve controlled airspace''te eğitim uçuşu yapıyorsun.","en":"You are a student pilot flying with callsign Student One Two Three, conducting a training flight in controlled airspace."}'::jsonb,
  objective = '{"tr":"ATC talimatlarındaki sayıları ICAO standardına uygun şekilde readback yapın.","en":"Read back ATC instructions with numbers according to ICAO standards."}'::jsonb,
  key_vocabulary = '[{"term":"flight level","definition_tr":"Standart basınca (1013.25 hPa) göre yüz feet cinsinden irtifa (FL150 = 15,000 feet)","definition_en":"Altitude in hundreds of feet referenced to standard pressure (1013.25 hPa)"},{"term":"heading","definition_tr":"Uçağın manyetik kuzeye göre yönü, derece cinsinden (000-360)","definition_en":"Aircraft direction relative to magnetic north, expressed in degrees (000-360)"},{"term":"readback","definition_tr":"Pilot tarafından ATC talimatının tekrarlanması, doğruluk kontrolü için","definition_en":"Repetition of ATC instruction by pilot to confirm correct understanding"},{"term":"contact","definition_tr":"Başka bir ATC frequency''sine geçiş talimatı","definition_en":"Instruction to switch to another ATC frequency"},{"term":"maintain","definition_tr":"Belirtilen altitude, speed veya heading''i koruma talimatı","definition_en":"Instruction to keep specified altitude, speed, or heading"},{"term":"decimal","definition_tr":"Frekans söylenirken ondalık noktası için kullanılan kelime","definition_en":"Word used for the decimal point when stating frequencies"},{"term":"niner","definition_tr":"9 rakamının havacılıkta telaffuz şekli (5 ile karışmaması için)","definition_en":"Aviation pronunciation of digit 9 (to avoid confusion with 5)"},{"term":"runway heading","definition_tr":"Pistin yönüne paralel uçuş, genellikle kalkış sonrası","definition_en":"Flight direction parallel to the runway, typically after takeoff"}]'::jsonb,
  estimated_duration_seconds = 180,
  turns = '[{"atcStation":"ANKARA APPROACH","atcUtterance":"Student One Two Three, climb to flight level one five zero, turn left heading two seven zero.","correctionTr":"İrtifa ve yön değişikliğini okuyun: ''Climb to flight level one five zero'' ve ''left heading two seven zero'' deyin. Sayıları tek tek telaffuz edin.","expectedReadback":"Climb to flight level one five zero, left heading two seven zero, Student One Two Three.","frequency":"119.7","hintTr":"Her rakamı ayrı ayrı söyleyin: one-five-zero, two-seven-zero.","id":"turn-1","isFinal":false,"keyPhrases":[["climb","climbing"],["flight level","FL"],["one five zero","150"],["left","turn left"],["heading"],["two seven zero","270"]],"hint":{"text_tr":"İrtifa değişikliğinde ''climb to'' ve ''flight level'' kullanın. Rakamları tek tek söyleyin: one-five-zero. Heading için ''left heading'' deyin ve three digit format kullanın: two-seven-zero.","text_en":"For altitude change use ''climb to'' and ''flight level''. Say digits individually: one-five-zero. For heading say ''left heading'' using three-digit format: two-seven-zero."},"expected_response":{"text_en":"Climb to flight level one five zero, left heading two seven zero, Student One Two Three","text_tr":"FL150''ye tırmanın, sola 270 heading''e dönün - callsign''ınızla bitirin","must_include":["climb","flight level","one five zero","150","left","heading","two seven zero","270"]},"vocabulary_focus":["flight level","heading","readback"]},{"atcStation":"ANKARA APPROACH","atcUtterance":"Student One Two Three, contact Ankara Tower on frequency one two zero decimal niner.","correctionTr":"Frekans değişikliğini okuyun: ''Contact Tower one two zero decimal niner'' deyin. ''Decimal'' kelimesini unutmayın, 9 için ''niner'' kullanın.","expectedReadback":"Contact Tower one two zero decimal niner, Student One Two Three.","frequency":"119.7","hintTr":"Frekansları söylerken: ''one two zero decimal niner'' şeklinde.","id":"turn-2","isFinal":false,"keyPhrases":[["contact"],["tower","Ankara Tower"],["one two zero","120"],["decimal"],["niner","nine","9"]],"hint":{"text_tr":"Frequency değişikliği için ''contact'' ve istasyon adını kullanın. Frekansı rakam rakam söyleyin ve ondalık için ''decimal'' kelimesini ekleyin. 9 için mutlaka ''niner'' deyin.","text_en":"Use ''contact'' with the station name for frequency change. Say frequency digit by digit and use the word ''decimal'' for the decimal point. Always say ''niner'' for 9."},"expected_response":{"text_en":"Contact Tower one two zero decimal niner, Student One Two Three","text_tr":"Tower''a 120.9 frekansından geçin - frequency''yi rakam rakam okuyun","must_include":["contact","tower","ankara tower","one two zero","120","decimal","niner","nine"]},"vocabulary_focus":["contact","decimal","niner"]},{"atcStation":"ANKARA TOWER","atcUtterance":"Student One Two Three, maintain two thousand five hundred feet, runway heading.","correctionTr":"İrtifa talimatını okuyun: ''Maintain two thousand five hundred feet, runway heading'' deyin. Ayak (feet) cinsinden irtifayı tam söyleyin veya rakam rakam okuyun.","expectedReadback":"Maintain two thousand five hundred feet, runway heading, Student One Two Three.","frequency":"120.9","hintTr":"Ayak cinsinden irtifalar: ''two thousand five hundred'' veya ''two five zero zero feet''.","id":"turn-3","isFinal":true,"keyPhrases":[["maintain","maintaining"],["two thousand five hundred","2500","two five zero zero"],["feet"],["runway heading"]],"hint":{"text_tr":"Feet cinsinden altitude için ''maintain'' kullanın. 2500 feet''i iki şekilde söyleyebilirsiniz: ''two thousand five hundred feet'' veya ''two five zero zero feet''. Runway heading''i olduğu gibi tekrarlayın.","text_en":"Use ''maintain'' for altitude in feet. You can say 2500 feet two ways: ''two thousand five hundred feet'' or ''two five zero zero feet''. Repeat runway heading as is."},"expected_response":{"text_en":"Maintain two thousand five hundred feet, runway heading, Student One Two Three","text_tr":"2500 feet''te kalın ve pist yönünde devam edin","must_include":["maintain","two thousand five hundred","two five zero zero","2500","feet","runway heading"]},"vocabulary_focus":["maintain","runway heading"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'number-transmission-altitude-heading-frequency';

UPDATE public.scenarios SET
  briefing = '{"tr":"Cruise fazında beklenmeyen moderate türbülans yaşanıyor. Captain, kabini güvence altına almak ve yolculara seatbelt uyarısı yapmak için senden PA announcement yapmanı istiyor.","en":"During cruise, unexpected moderate turbulence is encountered. The captain requests you to make a PA announcement to secure the cabin and advise passengers about seatbelt requirements."}'::jsonb,
  learner_role = '{"tr":"Sen cabin crew üyesi olarak yolculara türbülans hakkında PA announcement yapacaksın.","en":"You are a cabin crew member making a PA announcement to passengers regarding turbulence."}'::jsonb,
  objective = '{"tr":"Captain talimatına göre yolculara standart türbülans PA announcement''ı yap.","en":"Make a standard turbulence PA announcement to passengers following captain''s instruction."}'::jsonb,
  key_vocabulary = '[{"term":"moderate turbulence","definition_tr":"Orta şiddette hava türbülansı, emniyet kemeri takılmasını gerektiren durum","definition_en":"Medium-intensity air turbulence requiring seatbelt fastening"},{"term":"PA announcement","definition_tr":"Public Address sistemi üzerinden yapılan yolcu anons","definition_en":"Public Address system announcement to passengers"},{"term":"seatbelt sign","definition_tr":"Emniyet kemeri işareti, açık olduğunda yolcular oturmalı","definition_en":"Seatbelt indicator light, passengers must remain seated when illuminated"},{"term":"secure the cabin","definition_tr":"Kabini güvenli hale getirmek, yolcuları oturtmak, eşyaları sabitlemek","definition_en":"Make the cabin safe by seating passengers and securing items"},{"term":"fasten seatbelt","definition_tr":"Emniyet kemerini takmak ve sıkıştırmak","definition_en":"Buckle and tighten the seatbelt"},{"term":"cruise","definition_tr":"Uçuşun seyir fazı, sabit irtifa ve hızda uçuş","definition_en":"Level flight phase at constant altitude and speed"},{"term":"captain","definition_tr":"Uçağın komutanı, sorumlu pilot","definition_en":"Pilot in command of the aircraft"},{"term":"return to seats","definition_tr":"Yolcuların kendi koltuklarına geri dönmesi","definition_en":"Passengers going back to their assigned seats"}]'::jsonb,
  estimated_duration_seconds = 120,
  turns = '[{"atcStation":"CAPTAIN","atcUtterance":"Cabin, captain. Expect moderate turbulence in 3 minutes. Make a PA announcement and secure the cabin.","correctionTr":"PA anonsu standart: \"Ladies and gentlemen\" hitabı + captain bilgisi + seatbelt sign + return to seats + fasten.","expectedReadback":"Ladies and gentlemen, the captain has switched on the seatbelt sign. Please return to your seats and fasten your seatbelts.","id":"turn-1","isFinal":true,"keyPhrases":[["ladies and gentlemen","dear passengers"],["captain","flight deck"],["seatbelt","seat belt"],["return","go back"],["seats","your seat"],["fasten","buckle"]],"hint":{"text_tr":"Standart PA formatını kullan: önce yolculara hitap et, sonra captain''ın seatbelt sign''ı açtığını söyle, koltuklarına dönüp kemerlerini takmalarını iste.","text_en":"Use standard PA format: greet passengers, inform them the captain has switched on the seatbelt sign, request them to return to seats and fasten seatbelts."},"expected_response":{"text_en":"Ladies and gentlemen, the captain has switched on the seatbelt sign. Please return to your seats and fasten your seatbelts.","text_tr":"Yolculara hitap edip captain''ın seatbelt işaretini açtığını söyle ve koltuklarına dönüp kemerlerini takmalarını iste.","must_include":["ladies and gentlemen","dear passengers","captain","flight deck","seatbelt","seat belt","return","go back","seats","your seat","fasten","buckle"]},"vocabulary_focus":["PA announcement","seatbelt sign","fasten seatbelt","return to seats"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'pa-turbulence';

UPDATE public.scenarios SET
  briefing = '{"tr":"Uçuş sonrası walk-around sırasında sol kanat altında hydraulic fluid sızıntısı tespit ettin. Maintenance Supervisor''e durumu bildirip talimatları alman gerekiyor.","en":"During post-flight walk-around you discovered a hydraulic fluid leak under the left wing. You must report the condition to your Maintenance Supervisor and receive instructions."}'::jsonb,
  learner_role = '{"tr":"Sen line technician olarak post-flight inspection yapıyorsun ve hydraulic system defect tespit ettin","en":"You are a line technician conducting post-flight inspection who has discovered a hydraulic system defect"}'::jsonb,
  objective = '{"tr":"Hydraulic leak''i doğru terminoloji ile raporla, durumu teyit et ve verilen maintenance talimatlarını uygula","en":"Report the hydraulic leak using correct terminology, confirm the condition, and comply with maintenance instructions"}'::jsonb,
  key_vocabulary = '[{"term":"hydraulic leak","definition_tr":"Hidrolik sistemden sıvı sızıntısı","definition_en":"Fluid seepage from hydraulic system"},{"term":"reservoir","definition_tr":"Hidrolik sıvı deposu","definition_en":"Hydraulic fluid storage tank"},{"term":"AOG (Aircraft On Ground)","definition_tr":"Uçağın uçuşa elverişsiz durumda olması","definition_en":"Aircraft unserviceable and unable to fly"},{"term":"snag","definition_tr":"Teknik defekt veya arıza kaydı","definition_en":"Technical defect or fault entry"},{"term":"tech log","definition_tr":"Uçak teknik defter (Aircraft Technical Log)","definition_en":"Aircraft Technical Log for recording defects and maintenance"},{"term":"below minimum","definition_tr":"Minimum seviyenin altında","definition_en":"Lower than the minimum acceptable level"},{"term":"dispatch","definition_tr":"Uçuş operasyonları departmanı","definition_en":"Flight operations department"},{"term":"walk-around","definition_tr":"Uçuş öncesi/sonrası görsel dış kontrol","definition_en":"Visual external inspection before/after flight"}]'::jsonb,
  estimated_duration_seconds = 120,
  turns = '[{"atcStation":"MAINTENANCE SUPERVISOR","atcUtterance":"Go ahead with your post-flight report.","correctionTr":"Supervisor''e önce hydraulic leak olduğunu, nerede olduğunu (left wing altı) ve hangi sistem olduğunu (System A) söyle.","expectedReadback":"Hydraulic leak found under left wing, approximately two litres on ground, system A","frequency":null,"hintTr":"Bulguyu net ve kısa bildir: ne, nerede, hangi sistem.","id":"turn-1","isFinal":false,"keyPhrases":[["hydraulic","leak","fluid"],["left wing","port wing"],["system a","system alpha","hydraulic a"]],"hint":{"text_tr":"Önce ne bulduğunu (hydraulic leak), sonra nerede olduğunu (left wing altında) ve hangi sistemi etkilediğini (System A) net bir şekilde bildir","text_en":"First state what you found (hydraulic leak), then where it is located (under left wing), and which system is affected (System A)"},"expected_response":{"text_en":"Hydraulic leak found under left wing, approximately two litres on ground, system A","text_tr":"Sol kanat altında hidrolik sızıntı tespit ettim, yerde yaklaşık iki litre sıvı var, sistem A","must_include":["hydraulic","leak","fluid","left wing","port wing","system a","system alpha","hydraulic a"]},"vocabulary_focus":["hydraulic leak","left wing","system a"]},{"atcStation":"MAINTENANCE SUPERVISOR","atcUtterance":"Copy that. Can you confirm if the reservoir level is below minimum?","correctionTr":"Supervisor rezervuar seviyesinin minimum altında olup olmadığını soruyor. ''Affirmative'' ya da ''Yes'' ile onayla, ardından ''below minimum'' ve ''red line visible'' de.","expectedReadback":"Checking now… Affirmative, reservoir is below minimum, red line visible","frequency":null,"hintTr":"Önce onay ver, sonra gördüğün durumu tanımla.","id":"turn-2","isFinal":false,"keyPhrases":[["affirmative","yes","confirmed","correct"],["below minimum","under minimum","low"],["red line","minimum mark"]],"hint":{"text_tr":"Supervisor rezervuar seviyesini soruyor. Önce onaylayıcı yanıt ver (affirmative), sonra seviyenin minimum altında olduğunu ve red line''ın görünür olduğunu belirt","text_en":"Supervisor is asking about reservoir level. First confirm (affirmative), then state that level is below minimum and red line is visible"},"expected_response":{"text_en":"Checking now… Affirmative, reservoir is below minimum, red line visible","text_tr":"Kontrol ediyorum... Evet, rezervuar minimum seviyenin altında, kırmızı çizgi görünüyor","must_include":["affirmative","yes","confirmed","correct","below minimum","under minimum","low","red line","minimum mark"]},"vocabulary_focus":["reservoir","below minimum","affirmative"]},{"atcStation":"MAINTENANCE SUPERVISOR","atcUtterance":"Roger. Tag the aircraft as AOG, open a snag in the tech log, and notify dispatch. We''ll send another technician to assist.","correctionTr":"Supervisor üç talimat verdi: uçağı AOG olarak etiketle, tech log''a snag gir, dispatch''e bildir. ''Wilco'' diyerek tümünü kabul et ve kısaca tekrarla.","expectedReadback":"Wilco, tagging aircraft AOG, opening snag, and notifying dispatch","frequency":null,"hintTr":"Talimatları kısa ve net readback yap.","id":"turn-3","isFinal":true,"keyPhrases":[["wilco","will comply","roger"],["aog","aircraft on ground"],["snag","defect","tech log"],["dispatch","operations","notify"]],"hint":{"text_tr":"Supervisor üç ayrı talimat verdi: uçağı AOG olarak etiketle, tech log''a snag gir, dispatch''e bildir. Wilco diyerek kabul et ve üç talimatı da kısaca tekrarla","text_en":"Supervisor gave three separate instructions: tag aircraft AOG, open snag in tech log, notify dispatch. Acknowledge with wilco and briefly repeat all three instructions"},"expected_response":{"text_en":"Wilco, tagging aircraft AOG, opening snag, and notifying dispatch","text_tr":"Anlaşıldı, uçağı AOG olarak etiketliyorum, snag giriyorum ve dispatch''e bildiriyorum","must_include":["wilco","will comply","roger","aog","aircraft on ground","snag","defect","tech log","dispatch","operations","notify"]},"vocabulary_focus":["AOG","snag","tech log","dispatch","wilco"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'post-flight-inspection-hydraulic-leak';

UPDATE public.scenarios SET
  briefing = '{"tr":"Istanbul''dan Antalya''ya kalkacak Turkish 1453 Boeing 737-800''ün sabah walk-around inspection''ında sol main landing gear yakınında hydraulic fluid sızıntısı tespit edildi. Kalkışa 45 dakika var ve durumu Maintenance Control''e bildirip talimat almanız gerekiyor.","en":"During the morning walk-around inspection of Turkish 1453, a Boeing 737-800 scheduled to depart Istanbul for Antalya in 45 minutes, you discover a hydraulic fluid leak near the left main landing gear. You must report the finding to Maintenance Control and request guidance."}'::jsonb,
  learner_role = '{"tr":"Sen Turkish 1453 Boeing 737-800 uçağında yetkili aircraft technician olarak pre-flight walk-around inspection yapıyorsun ve hydraulic leak tespit ettin.","en":"You are a licensed aircraft technician performing the pre-flight walk-around inspection on Turkish 1453, a Boeing 737-800, and you have discovered a hydraulic leak."}'::jsonb,
  objective = '{"tr":"Hidrolik sızıntısını Maintenance Control''e bildirip gerekli talimatları alarak uçağı güvenli hale getir.","en":"Report the hydraulic leak to Maintenance Control, obtain necessary instructions, and ensure the aircraft is secured safely."}'::jsonb,
  key_vocabulary = '[{"term":"walk-around inspection","definition_tr":"Uçuş öncesi uçağın dış yüzeylerinin görsel kontrolü","definition_en":"Visual inspection of the aircraft''s exterior surfaces before flight"},{"term":"hydraulic leak","definition_tr":"Hidrolik sistemden sıvı sızıntısı veya kaçağı","definition_en":"Fluid leakage or seepage from the hydraulic system"},{"term":"main landing gear","definition_tr":"Uçağın ana iniş takımı, genellikle kanatlar altında yer alır","definition_en":"Primary landing gear assembly, typically located under the wings"},{"term":"ground the aircraft","definition_tr":"Uçağı uçuşa elverişsiz ilan edip yerde tutma","definition_en":"Declare the aircraft unserviceable and prevent it from flying"},{"term":"unserviceable","definition_tr":"Uçuşa veya operasyona elverişsiz, arızalı","definition_en":"Not fit for flight or operation, defective"},{"term":"active leak","definition_tr":"Halen devam eden, aktif sızıntı","definition_en":"Ongoing leak that is currently dripping or flowing"},{"term":"tag","definition_tr":"Arızalı sistemi işaretleme, etiketleme","definition_en":"Mark or label a defective system to prevent use"},{"term":"wilco","definition_tr":"Will comply - talimatları yerine getireceğim anlamında standart havacılık terimi","definition_en":"Will comply - standard aviation term indicating instructions will be carried out"}]'::jsonb,
  estimated_duration_seconds = 180,
  turns = '[{"atcStation":"MAINTENANCE CONTROL","atcUtterance":"Maintenance Control, go ahead with your report.","correctionTr":"Hidrolik sızıntısını, yerini (sol ana iniş takımı) ve ne yaptığınızı (çevir kontrolü) belirtmeniz gerekiyor. ''Requesting guidance'' ile talimat istediğinizi söyleyin.","expectedReadback":"Maintenance Control, this is technician on Turkish 1453, I have discovered a hydraulic leak on the left main landing gear during walk-around inspection, requesting guidance.","frequency":"131.8","hintTr":"Sorunu net tanımlayın: ne buldunuz, nerede, ne yaparken?","id":"turn-1","isFinal":false,"keyPhrases":[["hydraulic leak","hydraulic fluid leak","hydraulic leakage"],["left main landing gear","left main gear","port main gear"],["walk-around","walkaround","external inspection","pre-flight inspection"],["requesting guidance","need guidance","require instructions","what are my instructions"]],"hint":{"text_tr":"İlk çağrında kendini tanıt (technician on Turkish 1453), neyi nerede bulduğunu (hydraulic leak, left main landing gear) ve ne yaparken bulduğunu (walk-around inspection) söyle. Sonunda talimat iste (requesting guidance).","text_en":"Identify yourself (technician on Turkish 1453), state what you found and where (hydraulic leak, left main landing gear), mention what you were doing (walk-around inspection), and request guidance."},"expected_response":{"text_en":"Maintenance Control, this is technician on Turkish 1453, I have discovered a hydraulic leak on the left main landing gear during walk-around inspection, requesting guidance.","text_tr":"Maintenance Control''e ''teknisyen olarak Turkish 1453''teyim, walk-around sırasında sol main landing gear''da hydraulic leak buldum, talimat istiyorum'' diyorsun.","must_include":["hydraulic leak","hydraulic fluid","left main landing gear","left main gear","port main gear","walk-around","walkaround","pre-flight inspection","requesting guidance","need guidance","require instructions"]},"vocabulary_focus":["walk-around inspection","hydraulic leak","main landing gear","requesting guidance"]},{"atcStation":"MAINTENANCE CONTROL","atcUtterance":"Roger, can you confirm the approximate quantity of fluid and whether the leak appears active or residual?","correctionTr":"Sıvı miktarını tahmin edin (yaklaşık iki litre) ve sızıntının aktif olduğunu (damlama devam ediyor) açıklayın.","expectedReadback":"Affirmative, I estimate approximately two litres of fluid pooled on the ramp, and the leak appears active with dripping visible from the hydraulic line.","frequency":"131.8","hintTr":"Gözleminizi rakamlarla destekleyin ve sızıntının hala devam edip etmediğini belirtin.","id":"turn-2","isFinal":false,"keyPhrases":[["affirmative","affirm","confirmed","roger","yes"],["approximately","estimate","roughly","around"],["two litres","2 litres","two liters","two to three litres"],["pooled","pooling","collected","accumulated"],["active","active leak","ongoing"],["dripping","dripping visible","fluid dripping","continues to drip"]],"hint":{"text_tr":"Sızıntının miktarını tahmin et (yaklaşık iki litre, approximately two litres) ve sızıntının aktif olduğunu (active, dripping visible) açıkla. ''Affirmative'' ile onaylayarak başla.","text_en":"Estimate the quantity of fluid (approximately two litres) and confirm the leak is active (dripping visible). Start with ''Affirmative'' to acknowledge the question."},"expected_response":{"text_en":"Affirmative, I estimate approximately two litres of fluid pooled on the ramp, and the leak appears active with dripping visible from the hydraulic line.","text_tr":"''Onaylıyorum, apron üzerinde yaklaşık iki litre sıvı birikmiş durumda ve sızıntı aktif, hydraulic line''dan damlama görünüyor'' diyorsun.","must_include":["affirmative","affirm","confirmed","approximately","estimate","two litres","2 litres","pooled","pooling","active","active leak","dripping","dripping visible"]},"vocabulary_focus":["active leak","pooled","dripping","affirmative"]},{"atcStation":"MAINTENANCE CONTROL","atcUtterance":"Copy that. Ground the aircraft immediately and tag the hydraulic system as unserviceable. Dispatch a hydraulic specialist to your location and inform the captain that departure will be delayed pending repair. Do you copy?","correctionTr":"''Wilco'' diyerek talimatları kabul edin ve yapacaklarınızı özetleyin: uçağı yere indirme, sistemi etiketleme, uzman çağırma ve kaptanı bilgilendirme.","expectedReadback":"Wilco, grounding the aircraft now, tagging hydraulic system unserviceable, dispatching specialist, and will inform the captain of the delay, Turkish 1453.","frequency":"131.8","hintTr":"Tüm talimatları kısa ve net bir şekilde onaylayın.","id":"turn-3","isFinal":true,"keyPhrases":[["wilco","will comply","roger wilco","understood"],["grounding","ground the aircraft","grounding aircraft"],["tagging","tag","marking"],["hydraulic system","hydraulic"],["unserviceable","u/s","out of service"],["specialist","hydraulic specialist","technician"],["inform the captain","inform captain","notify captain","advise captain"],["delay","delayed","departure delay"]],"hint":{"text_tr":"''Wilco'' diyerek talimatları kabul et ve yapacaklarını özetle: uçağı ground ediyorsun, hydraulic system''i unserviceable olarak tag ediyorsun, specialist çağırıyorsun ve captain''ı delay konusunda bilgilendiriyorsun.","text_en":"Acknowledge with ''Wilco'' and summarize actions: grounding aircraft, tagging hydraulic system unserviceable, dispatching specialist, and informing captain of the delay."},"expected_response":{"text_en":"Wilco, grounding the aircraft now, tagging hydraulic system unserviceable, dispatching specialist, and will inform the captain of the delay, Turkish 1453.","text_tr":"''Talimatları uyguluyorum, şimdi uçağı ground ediyorum, hydraulic system''i unserviceable olarak tag ediyorum, specialist çağırıyorum ve captain''ı delay konusunda bilgilendireceğim'' diyorsun.","must_include":["wilco","will comply","grounding","ground the aircraft","tagging","tag","unserviceable","u/s","dispatching specialist","specialist","hydraulic specialist","inform captain","inform the captain","delay"]},"vocabulary_focus":["wilco","ground the aircraft","unserviceable","tag","dispatching specialist"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'preflight-walkround-hydraulic-leak-found';

UPDATE public.scenarios SET
  briefing = '{"tr":"İstanbul Havalimanı''nda gate 23''te park halindeki Turkish 1453 pushback için hazır. Ground crew olarak cockpit ile standart pushback koordinasyonunu gerçekleştirecek ve güvenli pushback prosedürünü yöneteceksin.","en":"Turkish 1453 is parked at gate 23 at Istanbul Airport and ready for pushback. As ground crew, you will coordinate standard pushback procedures with the cockpit and manage safe pushback operations."}'::jsonb,
  learner_role = '{"tr":"Sen Turkish 1453 için ground crew elemanısın ve Gate 23''ten pushback koordinasyonunu yürütüyorsun.","en":"You are the ground crew member for Turkish 1453 coordinating pushback from Gate 23."}'::jsonb,
  objective = '{"tr":"Cockpit ile güvenli pushback koordinasyonu yaparak uçağı gate''ten uygun yönde çıkarmak.","en":"Coordinate safe pushback with cockpit and push aircraft from gate in the correct direction."}'::jsonb,
  key_vocabulary = '[{"term":"pushback","definition_tr":"Uçağın gate''ten geri itilerek çıkarılması prosedürü","definition_en":"Procedure of pushing aircraft backwards from the gate"},{"term":"brakes set","definition_tr":"Park frenlerinin aktif/kilitli olduğu durum","definition_en":"Parking brakes are applied and locked"},{"term":"tug","definition_tr":"Uçağı iten özel çekici araç (pushback tug/tractor)","definition_en":"Specialized vehicle used to push aircraft (pushback tractor)"},{"term":"facing","definition_tr":"Uçağın burun yönü, hangi istikamete bakacağı","definition_en":"Direction the aircraft nose will be pointing"},{"term":"tail to","definition_tr":"Uçak kuyruğunun hangi yöne gideceği","definition_en":"Direction the aircraft tail will be pushed towards"},{"term":"cleared to push","definition_tr":"Pushback yapmak için izin verildi","definition_en":"Authorization granted to commence pushback"},{"term":"doors closed/secure","definition_tr":"Tüm uçak kapılarının kapalı ve güvenli olduğu durum","definition_en":"All aircraft doors are closed and secured"},{"term":"commence","definition_tr":"Başlamak, işleme geçmek (aviation formal term)","definition_en":"To begin or start an operation"}]'::jsonb,
  estimated_duration_seconds = 150,
  turns = '[{"atcStation":"CAPTAIN","atcUtterance":"Ground crew, Turkish 1453, ready for pushback. Confirm brakes set and all doors closed.","correctionTr":"Kaptan''a brake''lerin set olduğunu, tüm kapıların kapalı olduğunu ve pushback''e hazır olduğunuzu onaylamanız gerek.","expectedReadback":"Turkish 1453, brakes set, all doors closed, ready to commence pushback.","frequency":"129.8","hintTr":"Standart prosedür: brake durumu, kapı durumu, hazırlık.","id":"turn-1","isFinal":false,"keyPhrases":[["brakes set","brakes are set","parking brake set"],["doors closed","all doors closed","doors secure"],["ready","ready to commence","ready for pushback"]],"hint":{"text_tr":"Kaptan''a üç temel bilgiyi ver: parking brake durumu, kapıların durumu ve pushback''e hazır olduğunuzu onaylayın.","text_en":"Confirm three key items to captain: parking brake status, door status, and readiness for pushback."},"expected_response":{"text_en":"Turkish 1453, brakes set, all doors closed, ready to commence pushback.","text_tr":"Brake''ler set, tüm kapılar kapalı ve pushback''e başlamaya hazır olduğunuzu bildirin.","must_include":["brakes set","brakes are set","parking brake set","doors closed","all doors closed","doors secure","ready","ready to commence","ready for pushback"]},"vocabulary_focus":["brakes set","doors closed","commence"]},{"atcStation":"CAPTAIN","atcUtterance":"Roger, cleared to push. Advise when tug is connected and ready to push back.","correctionTr":"Pushback clearance''ı onaylayın ve tug bağlandığında haber vereceğinizi bildirin.","expectedReadback":"Cleared to push, will advise when tug connected.","frequency":"129.8","hintTr":"Kısa ve net: clearance onayı + ne zaman bilgi vereceğiniz.","id":"turn-2","isFinal":false,"keyPhrases":[["cleared to push","cleared for push","roger cleared"],["advise","will advise","will inform","will call"],["tug connected","when connected","tug is connected"]],"hint":{"text_tr":"Pushback clearance''ını onaylayın ve tug bağlandığında tekrar bilgi vereceğinizi belirtin.","text_en":"Acknowledge pushback clearance and confirm you will inform when tug is connected."},"expected_response":{"text_en":"Cleared to push, will advise when tug connected.","text_tr":"Pushback izni alındı, çekici bağlandığında haber vereceğinizi söyleyin.","must_include":["cleared to push","cleared for push","roger cleared","advise","will advise","will inform","will call","tug connected","when connected","tug is connected"]},"vocabulary_focus":["cleared to push","tug","advise"]},{"atcStation":"CAPTAIN","atcUtterance":"Standing by. Confirm direction of push, facing north or south?","correctionTr":"Pushback yönünü net belirtin: uçak hangi tarafa bakacak (facing) ve kuyruk hangi yöne gidecek (tail to).","expectedReadback":"Pushback direction facing north, push tail to the south.","frequency":"129.8","hintTr":"Yön: nose/facing ve tail direction ayrı ayrı belirtilir.","id":"turn-3","isFinal":true,"keyPhrases":[["facing north","nose north","north direction"],["tail south","tail to south","push tail south","pushing south"]],"hint":{"text_tr":"Pushback yönünü açıkça belirtin: uçak burnu hangi yöne bakacak (facing) ve kuyruk hangi yöne itilecek (tail to).","text_en":"State pushback direction clearly: which way the nose will face and which direction the tail will be pushed."},"expected_response":{"text_en":"Pushback direction facing north, push tail to the south.","text_tr":"Uçak kuzeye bakacak şekilde, kuyruk güneye doğru itilecek.","must_include":["facing north","nose north","north direction","tail south","tail to south","push tail south","pushing south"]},"vocabulary_focus":["facing","tail to","pushback direction"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'pushback-coordination-with-cockpit-b1';

UPDATE public.scenarios SET
  briefing = '{"tr":"IST''de Turkish 1453 için refueling supervision yapıyorsun. Bowser''da yeterli yakıt yok ve operations ile koordinasyon gerekiyor.","en":"You are supervising refueling operations for Turkish 1453 at IST. A fuel quantity discrepancy requires coordination between the refueling operator and operations."}'::jsonb,
  learner_role = '{"tr":"Sen ground supervisor olarak IST''de Turkish 1453''ün refueling operasyonunu yönetiyorsun.","en":"You are the ground supervisor managing refueling operations for Turkish 1453 at IST."}'::jsonb,
  objective = '{"tr":"Yakıt miktarı uyumsuzluğunu tespit et, operations ile koordine ol ve güvenli refueling''i tamamla.","en":"Identify the fuel discrepancy, coordinate with operations, and ensure safe completion of refueling."}'::jsonb,
  key_vocabulary = '[{"term":"bowser","definition_tr":"Havaalanında yakıt taşıyan ve uçaklara yakıt veren araç","definition_en":"A tanker truck used to refuel aircraft at airports"},{"term":"discrepancy","definition_tr":"İki miktar veya bilgi arasındaki uyumsuzluk, fark","definition_en":"A difference or inconsistency between two amounts or pieces of information"},{"term":"coordinate","definition_tr":"İlgili birimlerle iletişime geçip plan yapmak, organize etmek","definition_en":"To communicate and organize with relevant departments or personnel"},{"term":"supervise","definition_tr":"Bir operasyonu izlemek ve yönetmek, denetlemek","definition_en":"To oversee and manage an operation or procedure"},{"term":"caps","definition_tr":"Uçak yakıt tanklarının kapakları","definition_en":"Fuel tank covers or caps on an aircraft"},{"term":"flight plan adjustment","definition_tr":"Uçuş planında yapılan değişiklik (yakıt, rota vb.)","definition_en":"A modification made to the flight plan (fuel, route, etc.)"},{"term":"partial refueling","definition_tr":"Talep edilen miktardan daha az yakıt ikmali","definition_en":"Refueling with less than the requested amount of fuel"},{"term":"departure preparation","definition_tr":"Uçağın kalkış için hazırlanması süreci","definition_en":"The process of preparing an aircraft for departure"}]'::jsonb,
  estimated_duration_seconds = 180,
  turns = '[{"atcStation":"REFUELING OPERATOR","atcUtterance":"Ground supervisor, refueling operator. We have a problem with Turkish 1453. They requested 18,500 kilos but our bowser only has 15,000 kilos remaining. Advise.","correctionTr":"Operatörün mesajını anladığınızı onaylayın ve operations ile koordinasyon yapacağınızı bildirin. ''Copied'' veya ''roger'' ile başlayıp ''stand by'' kullanabilirsiniz.","expectedReadback":"Refueling operator, copied. Stand by while I coordinate with operations for Turkish 1453.","frequency":"131.7","hintTr":"Önce durumu kabul edin, sonra ne yapacağınızı net söyleyin.","id":"turn-1","isFinal":false,"keyPhrases":[["copied","roger","received"],["stand by","standby","wait"],["coordinate","check","contact"],["operations","ops","dispatch"]],"hint":{"text_tr":"Operatörün bildirdiği sorunu anladığını onayla, sonra operations ile görüşeceğini net söyle.","text_en":"Acknowledge the operator''s report, then clearly state you will coordinate with operations."},"expected_response":{"text_en":"Refueling operator, copied. Stand by while I coordinate with operations for Turkish 1453.","text_tr":"Operatörün mesajını aldığını söyle ve operations ile görüşürken beklemesini iste.","must_include":["copied","roger","received","stand by","standby","coordinate","operations","ops"]},"vocabulary_focus":["coordinate","discrepancy","bowser"]},{"atcStation":"OPERATIONS","atcUtterance":"Ground supervisor, ops. We can accept 15,000 kilos for Turkish 1453. Flight plan will be adjusted. Confirm you will supervise partial refueling.","correctionTr":"Operations''a onay verin: 15,000 kilo refueling''i süpervize edeceğinizi ve güvenli şekilde tamamlanacağını bildirin. ''Affirm'' veya ''confirmed'' kullanın.","expectedReadback":"Operations, affirm. I will supervise 15,000 kilos refueling for Turkish 1453 and ensure bowser is disconnected safely.","frequency":"131.7","hintTr":"Görev sorumluluğunu net kabul edin ve güvenlik vurgusunu unutmayın.","id":"turn-2","isFinal":false,"keyPhrases":[["affirm","affirmative","confirmed","roger"],["supervise","monitor","oversee"],["15,000","fifteen thousand","15000"],["refueling","fueling"],["disconnected","disconnect","safe","safely"]],"hint":{"text_tr":"Operations''ın kararını kabul et, 15,000 kilo refueling''i süpervize edeceğini ve güvenli tamamlanacağını bildir.","text_en":"Confirm operations'' decision and state you will supervise the 15,000 kilos refueling safely."},"expected_response":{"text_en":"Operations, affirm. I will supervise 15,000 kilos refueling for Turkish 1453 and ensure bowser is disconnected safely.","text_tr":"Onay ver, 15,000 kilo yakıt süpervizörlüğünü yapacağını ve güvenli disconnect edileceğini söyle.","must_include":["affirm","affirmative","confirmed","supervise","15,000","fifteen thousand","refueling","disconnected","safely"]},"vocabulary_focus":["supervise","partial refueling","flight plan adjustment"]},{"atcStation":"REFUELING OPERATOR","atcUtterance":"Ground supervisor, refueling complete. 15,000 kilos delivered. Bowser disconnected, all caps secured. Turkish 1453 ready for departure preparation.","correctionTr":"Operatörün tamamlama raporunu kabul edin, yakıt miktarını onaylayın ve operations''ı bilgilendireceğinizi söyleyin. ''Thank you'' ile nezaket gösterin.","expectedReadback":"Refueling operator, thank you. 15,000 kilos confirmed. I will inform operations that Turkish 1453 is clear for departure preparation.","frequency":"131.7","hintTr":"Süpervizör olarak döngüyü tamamlayın: miktar onayı + operations''a haber verme.","id":"turn-3","isFinal":true,"keyPhrases":[["thank you","thanks","roger"],["15,000","fifteen thousand","15000"],["confirmed","confirm","received"],["inform","notify","advise","contact"],["operations","ops"],["clear","ready"],["departure preparation","departure prep","pushback"]],"hint":{"text_tr":"Tamamlama raporunu kabul et, yakıt miktarını onayla ve operations''ı bilgilendireceğini söyle.","text_en":"Acknowledge the completion report, confirm the fuel amount, and state you will inform operations."},"expected_response":{"text_en":"Refueling operator, thank you. 15,000 kilos confirmed. I will inform operations that Turkish 1453 is clear for departure preparation.","text_tr":"Teşekkür et, 15,000 kilo yakıtı onayla ve operations''a uçağın departure preparation için hazır olduğunu bildireceğini söyle.","must_include":["thank you","thanks","15,000","fifteen thousand","confirmed","inform","notify","operations","clear","ready","departure preparation"]},"vocabulary_focus":["caps","departure preparation","supervise"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'refueling-supervision-quantity-discrepancy';

UPDATE public.scenarios SET
  briefing = '{"tr":"Istanbul Havalimanı''nda runway 35L''ye başarılı bir iniş yaptınız ve Tower sizi Ground frequency''sine devredecek. Ground''dan taxi clearance alıp park yerine güvenli şekilde ulaşmanız gerekiyor.","en":"You have successfully landed on runway 35L at Istanbul Airport and Tower will hand you over to Ground frequency. You need to receive taxi clearance from Ground and safely reach your parking stand."}'::jsonb,
  learner_role = '{"tr":"Sen Turkish 1453 callsign''lı bir Airbus A321''in First Officer''ısın ve kaptanla birlikte uçağı park yerine götürüyorsun.","en":"You are the First Officer of Turkish 1453, an Airbus A321, working with the captain to taxi the aircraft to the parking stand."}'::jsonb,
  objective = '{"tr":"Tower ve Ground''dan gelen tüm talimatları doğru ICAO phraseology ile readback yaparak uçağı A12 park yerine güvenle ulaştırmak.","en":"Correctly readback all instructions from Tower and Ground using ICAO phraseology and safely taxi the aircraft to stand A12."}'::jsonb,
  key_vocabulary = '[{"term":"readback","definition_tr":"ATC''den alınan talimatın tekrar okunması, doğrulama için kritik prosedür","definition_en":"Repeating ATC instructions back to confirm understanding, critical safety procedure"},{"term":"taxi clearance","definition_tr":"Yer hareketleri için ATC tarafından verilen rota ve izin","definition_en":"Route and permission given by ATC for ground movement"},{"term":"hold short","definition_tr":"Belirtilen noktanın önünde durmak, geçmeden beklemek","definition_en":"Stop before a specified point and await further clearance"},{"term":"contact Ground","definition_tr":"Yer kontrol frekansına geçiş yapma talimatı","definition_en":"Instruction to switch to ground control frequency"},{"term":"via","definition_tr":"Belirtilen taxiway''ler üzerinden, rota göstergesi","definition_en":"Through the specified taxiways, route indicator"},{"term":"stand","definition_tr":"Apron''da uçağın park edeceği numaralı alan","definition_en":"Numbered parking position for aircraft on the apron"},{"term":"cross","definition_tr":"Bir taxiway veya runway''i geçme izni","definition_en":"Permission to cross a taxiway or runway"},{"term":"frequency","definition_tr":"ATC ile iletişim kurulan radyo kanalı (MHz)","definition_en":"Radio channel (MHz) used to communicate with ATC"}]'::jsonb,
  estimated_duration_seconds = 120,
  turns = '[{"atcStation":"ISTANBUL TOWER","atcUtterance":"Turkish 1453, contact Ground 121.9.","correctionTr":"Frekans değişimi için önce yeni frekansı, sonra call sign''ınızı okuyun: ''Ground 121.9, Turkish 1453.''","expectedReadback":"Ground 121.9, Turkish 1453.","frequency":"118.1","hintTr":"Kule sizi yeni frekansa yönlendiriyor, kısa ve net readback yapın.","id":"turn-1","isFinal":false,"keyPhrases":[["ground","121.9","121 point 9"],["turkish","1453","turkish one four five three"]],"hint":{"text_tr":"Tower seni yeni bir frekansa yönlendiriyor. Önce yeni frequency''yi, sonra callsign''ını söyleyerek kısa ve net bir readback yap.","text_en":"Tower is directing you to a new frequency. Make a short and clear readback with the new frequency first, then your callsign."},"expected_response":{"text_en":"Ground 121.9, Turkish 1453.","text_tr":"Yeni frekansı ve callsign''ını onaylıyorsun.","must_include":["ground","121.9","121 point 9","turkish","1453","one four five three"]},"vocabulary_focus":["contact Ground","frequency","readback"]},{"atcStation":"ISTANBUL GROUND","atcUtterance":"Turkish 1453, Istanbul Ground, taxi to stand A12 via A, B3, hold short of taxiway C.","correctionTr":"Taxi talimatını tam olarak tekrarlayın: ''Taxi to stand A12 via A, B3, hold short of taxiway C, Turkish 1453.'' Rota ve hold short noktası önemli.","expectedReadback":"Taxi to stand A12 via A, B3, hold short of taxiway C, Turkish 1453.","frequency":"121.9","hintTr":"Yer kontrolü size park yerini ve rotayı veriyor, eksiksiz readback yapın.","id":"turn-2","isFinal":false,"keyPhrases":[["taxi","stand","a12","a 12"],["via","a","b3","b 3"],["hold short","taxiway","c"],["turkish","1453"]],"hint":{"text_tr":"Ground sana tam taxi clearance veriyor: park yeri, rota ve önemli bir hold short noktası var. Her üç bilgiyi de eksiksiz tekrarla.","text_en":"Ground is giving you complete taxi clearance: parking stand, route, and an important hold short point. Repeat all three elements completely."},"expected_response":{"text_en":"Taxi to stand A12 via A, B3, hold short of taxiway C, Turkish 1453.","text_tr":"Park yeri A12''ye A ve B3 üzerinden gidiyorsun, taxiway C''den önce duracaksın.","must_include":["taxi","stand","a12","a 12","via","a","b3","b 3","hold short","taxiway","c","turkish","1453"]},"vocabulary_focus":["taxi clearance","via","hold short","stand"]},{"atcStation":"ISTANBUL GROUND","atcUtterance":"Turkish 1453, cross taxiway C, continue to A12.","correctionTr":"Geçiş izni verildiğinde ''Cross taxiway C, continue to A12, Turkish 1453'' şeklinde onaylayın.","expectedReadback":"Cross taxiway C, continue to A12, Turkish 1453.","frequency":"121.9","hintTr":"Hold short kaldırıldı, devam izni aldınız.","id":"turn-3","isFinal":true,"keyPhrases":[["cross","taxiway","c"],["continue","a12","a 12"],["turkish","1453"]],"hint":{"text_tr":"Daha önce beklemeni istedikleri hold short kaldırıldı. Şimdi taxiway C''yi geçip A12''ye devam edebilirsin, bu izni onayla.","text_en":"The hold short you were given earlier is now lifted. You can now cross taxiway C and continue to A12, confirm this clearance."},"expected_response":{"text_en":"Cross taxiway C, continue to A12, Turkish 1453.","text_tr":"Taxiway C''yi geçip A12''ye devam etme izni aldın.","must_include":["cross","taxiway","c","continue","a12","a 12","turkish","1453"]},"vocabulary_focus":["cross","taxi clearance","readback"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'standard-taxi-clearance-readback-b2';

UPDATE public.scenarios SET
  briefing = '{"tr":"İstanbul Atatürk Havalimanı''nda gate A21''den runway 35L''a taxi clearance alacak ve ground control talimatlarını uygulayacaksın. Busy bir terminal alanda trafiğe dikkat ederek ilerlemelisin.","en":"You will receive taxi clearance from gate A21 to runway 35L at Istanbul Atatürk Airport and follow ground control instructions. Navigate carefully through the busy terminal area while managing traffic."}'::jsonb,
  learner_role = '{"tr":"Sen Turkish Airlines 1453 callsign''ı ile uçan bir pilot olarak İstanbul''da ground control ile iletişim kuruyorsun.","en":"You are the pilot flying as Turkish Airlines 1453, communicating with ground control at Istanbul."}'::jsonb,
  objective = '{"tr":"Taxi clearance''ı doğru read-back yap ve traffic conflict durumunda uygun phraseology kullan.","en":"Correctly read back taxi clearance and use proper phraseology during traffic conflict."}'::jsonb,
  key_vocabulary = '[{"term":"taxi clearance","definition_tr":"Uçağın hangi taxiway''lerden hangi noktaya gideceğini belirten ATC izni","definition_en":"ATC authorization specifying which taxiways to use to reach a designated point"},{"term":"holding point","definition_tr":"Runway''e girmeden önce bekleme yapılan işaretli nokta","definition_en":"Marked position where aircraft wait before entering the runway"},{"term":"read-back","definition_tr":"ATC talimatını tekrar ederek anladığını teyit etme","definition_en":"Repeating ATC instruction to confirm understanding"},{"term":"give way","definition_tr":"Başka bir uçağa yol verme, öncelik tanıma","definition_en":"Yield right-of-way to another aircraft"},{"term":"taxiway","definition_tr":"Uçakların runway dışında hareket ettiği işaretli yollar","definition_en":"Marked paths for aircraft movement outside of runways"},{"term":"callsign","definition_tr":"Uçağın radyo iletişiminde kullandığı kimlik kodu","definition_en":"Aircraft identification code used in radio communication"},{"term":"ground control","definition_tr":"Havalimanında taxi hareketlerini yöneten ATC birimi","definition_en":"ATC unit managing aircraft taxiing movements at the airport"},{"term":"via","definition_tr":"Kullanılacak route veya taxiway''leri belirtir (üzerinden)","definition_en":"Indicates the route or taxiways to be used"}]'::jsonb,
  estimated_duration_seconds = 120,
  turns = '[{"atcStation":"ISTANBUL GROUND","atcUtterance":"Turkish 1453, taxi to holding point runway 35 left, via Echo Six, Hotel.","correctionTr":"Taxi clearance read-back şu sırayla: HOLDING POINT + RUNWAY + via TAXIWAYS + CALLSIGN.","expectedReadback":"Taxi to holding point runway 35 left via Echo Six Hotel, Turkish 1453.","frequency":"129.6","id":"turn-1","keyPhrases":[["taxi"],["holding point","hold short"],["runway 35 left","runway three five left","35l","three five left"],["echo six","e6","e 6"],["hotel","h"],["turkish"],["1453","one four five three"]],"hint":{"text_tr":"Taxi clearance read-back sırası: önce holding point ve runway''i söyle, sonra ''via'' ile taxiway''leri belirt, en sonda callsign''ını ekle.","text_en":"Taxi clearance read-back order: first state holding point and runway, then taxiways with ''via'', and finish with your callsign."},"expected_response":{"text_en":"Taxi to holding point runway 35 left via Echo Six Hotel, Turkish 1453.","text_tr":"Runway 35 sol holding point''e, Echo Six ve Hotel taxiway''leri üzerinden taxi yapıyorsun.","must_include":["taxi","holding point","runway 35 left","via","echo six","hotel","turkish 1453"]},"vocabulary_focus":["taxi clearance","holding point","via","read-back"]},{"atcStation":"ISTANBUL GROUND","atcUtterance":"Turkish 1453, give way to A320 from your right, then continue.","correctionTr":"\"Giving way\" + ne için (\"to A320\") + \"then continuing\" şeklinde tekrarla.","expectedReadback":"Giving way to A320, then continuing, Turkish 1453.","frequency":"129.6","id":"turn-2","isFinal":true,"keyPhrases":[["give way","giving way","yield"],["a320","airbus 320"],["continue","continuing"],["turkish"]],"hint":{"text_tr":"Traffic conflict durumunda önce ''giving way'' de, neye yol verdiğini (A320) belirt, ardından devam edeceğini (''continuing'') söyle.","text_en":"In traffic conflict, first say ''giving way'', specify what you''re yielding to (A320), then state you will continue."},"expected_response":{"text_en":"Giving way to A320, then continuing, Turkish 1453.","text_tr":"Sağından gelen A320''ye yol veriyorsun, sonra devam edeceksin.","must_include":["giving way","give way","a320","continuing","continue","turkish"]},"vocabulary_focus":["give way","traffic","continue"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'taxi-clearance-ist';

UPDATE public.scenarios SET
  briefing = '{"tr":"İstanbul Havalimanı''nda yoğun trafik var. Sen Turkish 1453 olarak Gate 23''ten pushback yaptın ve aktif runway 35R''yi cross ederek runway 35L''e taxi yapman gerekiyor.","en":"Istanbul Airport is busy with traffic. You are Turkish 1453, pushed back from Gate 23, and need to taxi to runway 35L by crossing the active runway 35R."}'::jsonb,
  learner_role = '{"tr":"Sen Turkish 1453, bir Airbus A321 pilotu olarak Ground Control''den taxi clearance alacak ve runway crossing yapacaksın.","en":"You are Turkish 1453, an Airbus A321 pilot, receiving taxi clearance from Ground Control and performing a runway crossing."}'::jsonb,
  objective = '{"tr":"Ground Control talimatlarını doğru readback yap ve güvenli bir şekilde runway 35L holding point''e ulaş.","en":"Read back Ground Control instructions correctly and reach runway 35L holding point safely."}'::jsonb,
  key_vocabulary = '[{"term":"taxi clearance","definition_tr":"Apron''dan runway''e gitmek için verilen hareket izni","definition_en":"Permission to move on the airport surface from apron to runway"},{"term":"holding point","definition_tr":"Runway''e girmeden önce beklenen son nokta","definition_en":"The last point before entering the runway where aircraft wait"},{"term":"cross runway","definition_tr":"Bir runway''in üzerinden geçmek için alınan özel izin","definition_en":"Special permission to traverse across an active runway"},{"term":"hold short","definition_tr":"Belirtilen noktanın veya runway''in önünde durmak","definition_en":"Stop before a specified point or runway"},{"term":"via","definition_tr":"Taxiway rotasını belirtmek için kullanılır (örn: via Alpha)","definition_en":"Used to specify the taxiway route (e.g., via Alpha)"},{"term":"readback","definition_tr":"ATC talimatını tekrar ederek doğru anladığını göstermek","definition_en":"Repeating ATC instructions to confirm correct understanding"},{"term":"contact","definition_tr":"Başka bir frekansa geçmek için kullanılan ifade","definition_en":"Instruction to switch to another frequency"},{"term":"traffic on final","definition_tr":"İniş için son yaklaşmada olan başka bir uçak","definition_en":"Another aircraft on final approach for landing"}]'::jsonb,
  estimated_duration_seconds = 180,
  turns = '[{"atcStation":"ISTANBUL GROUND","atcUtterance":"Turkish 1453, Istanbul Ground, taxi to holding point Runway 35 Left via Alpha, cross Runway 35 Right.","correctionTr":"Taxi clearance''ı tam readback yapmalısınız: taxi rotası (Alpha), varış noktası (holding point Runway 35 Left) ve önemli olan runway crossing talimatı (cross Runway 35 Right). Call sign''ınızla bitirin.","expectedReadback":"Taxi to holding point Runway 35 Left via Alpha, cross Runway 35 Right, Turkish 1453.","frequency":"121.75","hintTr":"Routing''i ve runway crossing''i net tekrarlayın.","id":"turn-1","isFinal":false,"keyPhrases":[["taxi","taxiing"],["holding point","holding"],["35 left","35L","three five left"],["alpha"],["cross","crossing"],["35 right","35R","three five right"],["1453","turkish 1453"]],"hint":{"text_tr":"Tam taxi clearance readback yapmalısın: hangi taxiway''den (via Alpha) nereye gidiyorsun (holding point runway 35 Left), hangi runway''i cross edeceksin (runway 35 Right) ve call sign''ınla bitir.","text_en":"Read back complete taxi clearance: which taxiway (via Alpha), destination (holding point runway 35 Left), runway crossing (runway 35 Right), and end with your callsign."},"expected_response":{"text_en":"Taxi to holding point Runway 35 Left via Alpha, cross Runway 35 Right, Turkish 1453.","text_tr":"Alpha taxiway''inden holding point runway 35 Left''e taxi yapacağını, runway 35 Right''ı cross edeceğini söyle ve call sign''ınla bitir.","must_include":["taxi","holding point","35 left","three five left","35l","via","alpha","cross","35 right","three five right","35r","turkish 1453","1453"]},"vocabulary_focus":["taxi clearance","holding point","via","cross runway"]},{"atcStation":"ISTANBUL GROUND","atcUtterance":"Turkish 1453, hold short of Runway 35 Right, traffic on final.","correctionTr":"Hold short emrini onaylamalısınız: hangi runway''de durduğunuzu (Runway 35 Right) belirtin ve call sign''ınızı ekleyin.","expectedReadback":"Holding short of Runway 35 Right, Turkish 1453.","frequency":"121.75","hintTr":"Kısa ve net: hangi runway''de hold short yapıyorsunuz?","id":"turn-2","isFinal":false,"keyPhrases":[["holding short","hold short","holding"],["35 right","35R","three five right"],["1453","turkish 1453"]],"hint":{"text_tr":"Hold short emrini onayla: hangi runway''de bekliyorsun (runway 35 Right) ve call sign''ını ekle. Kısa ve net olmalı.","text_en":"Confirm hold short instruction: which runway (runway 35 Right) and add your callsign. Keep it short and clear."},"expected_response":{"text_en":"Holding short of Runway 35 Right, Turkish 1453.","text_tr":"Runway 35 Right''ta holding short yaptığını onayla ve call sign''ınla bitir.","must_include":["holding short","hold short","holding","35 right","three five right","35r","turkish 1453","1453"]},"vocabulary_focus":["hold short","traffic on final"]},{"atcStation":"ISTANBUL GROUND","atcUtterance":"Turkish 1453, cross Runway 35 Right, contact Tower 118.7.","correctionTr":"Runway crossing izni ve frekans değişikliğini readback edin: cross Runway 35 Right, yeni frekans (Tower 118.7) ve call sign.","expectedReadback":"Cross Runway 35 Right, contact Tower 118.7, Turkish 1453.","frequency":"121.75","hintTr":"İki talimat var: runway crossing ve frekans değişimi.","id":"turn-3","isFinal":true,"keyPhrases":[["cross","crossing"],["35 right","35R","three five right"],["contact","contacting"],["tower"],["118.7","one one eight decimal seven","one one eight point seven"],["1453","turkish 1453"]],"hint":{"text_tr":"İki talimat var: runway crossing izni (cross runway 35 Right) ve frekans değişimi (Tower 118.7). Her ikisini de readback et ve call sign''ınla bitir.","text_en":"Two instructions: runway crossing clearance (cross runway 35 Right) and frequency change (Tower 118.7). Read back both and end with callsign."},"expected_response":{"text_en":"Cross Runway 35 Right, contact Tower 118.7, Turkish 1453.","text_tr":"Runway 35 Right''ı cross edeceğini, Tower 118.7''ye geçeceğini söyle ve call sign''ınla bitir.","must_include":["cross","crossing","35 right","three five right","35r","contact","tower","118.7","one one eight point seven","one one eight decimal seven","turkish 1453","1453"]},"vocabulary_focus":["cross runway","contact","readback"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'taxi-clearance-runway-crossing-b1';

UPDATE public.scenarios SET
  briefing = '{"tr":"Gate 23''te park halindeki Turkish 1453 (B737-800) uçağının rutin walk-around inspection''ı sırasında sol main landing gear altında hydraulic fluid birikintisi tespit edildi. Snag''i maintenance supervisor''e bildirip technical log''a kaydetmen gerekiyor.","en":"During routine walk-around inspection of Turkish 1453 (B737-800) at gate 23, hydraulic fluid pooling was discovered under the left main landing gear. You must report the snag to maintenance supervisor and document it in the technical log."}'::jsonb,
  learner_role = '{"tr":"Sen Turkish 1453 B737-800 uçağının bakım teknisyeni olarak gate 23''te hydraulic leak snag''ini raporluyorsun.","en":"You are the maintenance technician for Turkish 1453 B737-800 reporting a hydraulic leak snag at gate 23."}'::jsonb,
  objective = '{"tr":"Hydraulic leak snag''ini doğru prosedürle bildirip technical log''a ATA 29 altına kaydetmek.","en":"Report the hydraulic leak snag following proper procedure and document it in the technical log under ATA 29."}'::jsonb,
  key_vocabulary = '[{"term":"snag","definition_tr":"Uçakta tespit edilen teknik arıza veya kusur","definition_en":"A technical defect or malfunction discovered on an aircraft"},{"term":"walk-around inspection","definition_tr":"Uçağın dış kısmının görsel kontrolü","definition_en":"Visual external inspection of the aircraft"},{"term":"hydraulic fluid","definition_tr":"Hidrolik sistemlerde basınç iletimi için kullanılan sıvı","definition_en":"Fluid used in hydraulic systems to transmit pressure"},{"term":"technical log / tech log","definition_tr":"Uçağın teknik durumunu ve bakım kayıtlarını içeren resmi belge","definition_en":"Official document containing aircraft technical status and maintenance records"},{"term":"ATA chapter","definition_tr":"Uçak sistemlerini kategorize eden standart numaralandırma sistemi (ATA 29 = hydraulic)","definition_en":"Standard numbering system categorizing aircraft systems (ATA 29 = hydraulic)"},{"term":"reservoir","definition_tr":"Hidrolik sıvının depolandığı tank","definition_en":"Tank where hydraulic fluid is stored"},{"term":"main landing gear","definition_tr":"Uçağın ana iniş takımları (kanatlar altında)","definition_en":"Primary landing gear assemblies (under wings)"},{"term":"wilco","definition_tr":"Will comply - talimatı anlayıp uygulayacağım anlamında","definition_en":"Will comply - acknowledgment that instruction is understood and will be followed"}]'::jsonb,
  estimated_duration_seconds = 150,
  turns = '[{"atcStation":"MAINTENANCE SUPERVISOR","atcUtterance":"Go ahead with your snag report for Turkish 1453.","correctionTr":"Snag bildiriminde şu unsurlar bulunmalı: uçak call sign (Turkish 1453), sorunun ne olduğu (hydraulic leak), nerede (left main landing gear), ne istediğiniz (tech log entry ve inspection). Örnek: ''Turkish 1453, left main landing gear altında hydraulic fluid leak gözlemledim, tech log entry ve inspection talep ediyorum.''","expectedReadback":"Turkish 1453, hydraulic fluid leak observed under left main landing gear during walk-around, requesting tech log entry and further inspection.","frequency":null,"hintTr":"Sorunun yerini ve ne gördüğünüzü net belirtin, sonra ne yapılması gerektiğini söyleyin.","id":"turn-1","isFinal":false,"keyPhrases":[["hydraulic","fluid","leak"],["left main","landing gear","left gear"],["tech log","technical log","log entry"],["inspection","further inspection","check"]],"hint":{"text_tr":"İlk olarak uçak callsign''ını söyle, sonra nerede ne gördüğünü açıkla (left main landing gear, hydraulic fluid leak), en son ne istediğini belirt (tech log entry ve inspection).","text_en":"Start with aircraft callsign, then describe what you observed and where (left main landing gear, hydraulic fluid leak), finish with what you need (tech log entry and inspection)."},"expected_response":{"text_en":"Turkish 1453, hydraulic fluid leak observed under left main landing gear during walk-around, requesting tech log entry and further inspection.","text_tr":"Turkish 1453 callsign''ı ile başla, sol main landing gear altında hydraulic fluid leak gördüğünü bildir, tech log kaydı ve inspection iste.","must_include":["turkish 1453","hydraulic","leak","left main","landing gear","tech log","inspection"]},"vocabulary_focus":["snag","hydraulic fluid","main landing gear","tech log"]},{"atcStation":"MAINTENANCE SUPERVISOR","atcUtterance":"Copy that. Can you estimate the quantity of fluid and confirm if the hydraulic reservoir level is still within limits?","correctionTr":"Süpervisör sıvı miktarını ve reservoir seviyesini soruyor. Yaklaşık miktarı tahmin edin (örneğin ''approximately two litres'') ve reservoir level''ı cockpit panel''den kontrol edeceğinizi belirtin. ''Advise'' veya ''report back'' diyerek geri bildirim vereceğinizi söyleyin.","expectedReadback":"Approximately two litres of fluid on the ground, I will check the reservoir level from the cockpit panel now and advise.","frequency":null,"hintTr":"Gördüğünüz sıvı miktarını tahmin edin, sonra reservoir seviyesini nereden kontrol edeceğinizi açıklayın.","id":"turn-2","isFinal":false,"keyPhrases":[["two litre","2 litre","approximately two"],["check","checking","will check"],["reservoir","level"],["cockpit","panel"],["advise","report back","confirm"]],"hint":{"text_tr":"Yerde gördüğün sıvı miktarını tahmin et (yaklaşık iki litre gibi), sonra reservoir level''ı cockpit panel''den kontrol edeceğini söyle ve geri bildirim vereceğini belirt.","text_en":"Estimate the amount of fluid on ground (approximately two litres), state you will check reservoir level from cockpit panel, and confirm you will report back."},"expected_response":{"text_en":"Approximately two litres of fluid on the ground, I will check the reservoir level from the cockpit panel now and advise.","text_tr":"Yaklaşık iki litre sıvı var yerde, reservoir seviyesini cockpit panel''den kontrol edip geri bildireceğim.","must_include":["two litre","approximately","check","reservoir","level","cockpit","panel","advise"]},"vocabulary_focus":["reservoir","hydraulic fluid","cockpit panel"]},{"atcStation":"MAINTENANCE SUPERVISOR","atcUtterance":"Understood. After you check the reservoir, enter the snag in the tech log under ATA chapter 29, and I will dispatch a hydraulic specialist to the aircraft. Do you copy?","correctionTr":"Süpervisör size üç görev veriyor: reservoir kontrol et, snag''i tech log''a ATA 29 altına kaydet, hydraulic specialist gelecek. Readback şöyle olmalı: ''Wilco, reservoir level kontrol edeceğim, snag''i tech log ATA 29''a kaydediyorum, gate 23''te hydraulic specialist bekliyorum.'' Tüm talimatları onaylayın.","expectedReadback":"Wilco, I will check reservoir level, enter snag in tech log ATA 29, awaiting hydraulic specialist at gate 23.","frequency":null,"hintTr":"Verilen tüm talimatları sırayla onaylayın: kontrol, kayıt, specialist bekleme.","id":"turn-3","isFinal":true,"keyPhrases":[["wilco","roger","copy"],["check","reservoir"],["enter","snag","tech log"],["ATA 29","ATA chapter 29"],["hydraulic specialist","specialist"],["gate 23","awaiting"]],"hint":{"text_tr":"Üç görevi onayla: reservoir kontrol et, snag''i tech log''a ATA 29 altına kaydet, hydraulic specialist gelecek. Wilco ile başlayıp tüm adımları tekrarla.","text_en":"Acknowledge three tasks: check reservoir, enter snag in tech log under ATA 29, hydraulic specialist coming. Start with wilco and repeat all steps."},"expected_response":{"text_en":"Wilco, I will check reservoir level, enter snag in tech log ATA chapter 29, awaiting hydraulic specialist at gate 23.","text_tr":"Wilco de, reservoir kontrol edeceğini, snag''i ATA 29''a kaydedeceğini ve gate 23''te hydraulic specialist bekleyeceğini söyle.","must_include":["wilco","check","reservoir","snag","tech log","ata 29","hydraulic specialist","gate 23"]},"vocabulary_focus":["wilco","ATA chapter","tech log","hydraulic specialist"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'tech-log-snag-entry-hydraulic-leak';

UPDATE public.scenarios SET
  briefing = '{"tr":"Turkish 1453 callsign ile Londra''ya cruise seviyesinde uçarken, 28C koltuğunda sarhoş ve agresif bir yolcu uçuş güvenliğini tehdit ediyor. Cabin Chief koordinasyonunda durumu yönetmen ve Captain''ı bilgilendirmen gerekiyor.","en":"During cruise to London on Turkish 1453, an intoxicated and aggressive passenger in seat 28C threatens flight safety. You must manage the situation under Cabin Chief coordination and notify the Captain."}'::jsonb,
  learner_role = '{"tr":"Sen Turkish 1453 flight''ında cabin crew member olarak FL370''de cruise yapıyorsun ve Cabin Chief''in talimatlarıyla unruly passenger durumunu yönetiyorsun.","en":"You are a cabin crew member on Turkish 1453 cruising at FL370, managing an unruly passenger situation under Cabin Chief instructions."}'::jsonb,
  objective = '{"tr":"Unruly passenger durumunda doğru coordination phraseology kullanarak yolcu güvenliğini sağla ve Captain''ı bilgilendir.","en":"Use proper coordination phraseology to ensure passenger safety during an unruly passenger situation and notify the Captain."}'::jsonb,
  key_vocabulary = '[{"term":"unruly passenger","definition_tr":"Kabin kurallarına uymayan, agresif veya tehditkar davranan yolcu","definition_en":"Passenger who refuses to comply with cabin rules, acts aggressively or threatens safety"},{"term":"restraint","definition_tr":"Tehlikeli yolcunun hareket özgürlüğünün fiziksel olarak kısıtlanması","definition_en":"Physical restriction of a dangerous passenger''s movement"},{"term":"securing passengers","definition_tr":"Yolcuların güvenliğini sağlamak için koruyucu önlemler almak","definition_en":"Taking protective measures to ensure passenger safety"},{"term":"wilco","definition_tr":"Will comply - Talimatı yerine getireceğim anlamında standart onay","definition_en":"Will comply - standard acknowledgment that instruction will be carried out"},{"term":"standing by","definition_tr":"Hazır bekleme durumunda, müdahaleye hazır","definition_en":"Ready and waiting, prepared to intervene"},{"term":"flight safety","definition_tr":"Uçuşun güvenli şekilde gerçekleştirilmesi için gerekli koşullar","definition_en":"Conditions necessary for safe conduct of the flight"},{"term":"presence in cabin","definition_tr":"Kaptan''ın cockpit''ten çıkarak cabin''e gelmesi","definition_en":"Captain leaving the cockpit to attend the cabin"},{"term":"affirmative","definition_tr":"Evet, onaylıyorum anlamında standart aviation terimi","definition_en":"Yes, confirmed - standard aviation term for agreement"}]'::jsonb,
  estimated_duration_seconds = 150,
  turns = '[{"atcStation":"CABIN CHIEF","atcUtterance":"Crew at 28C, passenger is becoming aggressive and refuses to comply. I need you to secure surrounding passengers and standby to assist.","correctionTr":"Kabin Amiri''ne önce onay ver (roger/wilco), sonra etraftaki yolcuları güvenli hale getireceğini ve yardıma hazır olduğunu belirt. Koltuk numarasını tekrarla.","expectedReadback":"Roger, securing passengers around 28C and standing by to assist.","frequency":null,"hintTr":"Önce anladığını belirt, sonra yapacağın eylemi açıkla.","id":"turn-1","isFinal":false,"keyPhrases":[["roger","wilco","copy","understood"],["securing","moving","clear","relocate"],["passengers","pax"],["28C","twenty-eight charlie"],["standing by","standby","ready to assist","ready"]],"hint":{"text_tr":"Önce Cabin Chief''in mesajını anladığını standart bir terimle onayla (roger/wilco), sonra 28C çevresindeki yolcuları güvenli hale getireceğini ve yardıma hazır olduğunu belirt.","text_en":"First acknowledge the Cabin Chief''s message with standard terminology (roger/wilco), then state you will secure passengers around 28C and stand by to assist."},"expected_response":{"text_en":"Roger, securing passengers around 28C and standing by to assist.","text_tr":"Anlaşıldı, 28C çevresindeki yolcuları güvenli hale getiriyorum ve yardıma hazırım.","must_include":["roger","wilco","copy","securing","passengers","28c","twenty-eight charlie","standing by","standby","assist"]},"vocabulary_focus":["wilco","securing passengers","standing by"]},{"atcStation":"CABIN CHIEF","atcUtterance":"Notify the captain immediately. Tell him we have an unruly passenger, possible restraint required, and request his presence in the cabin.","correctionTr":"Kaptan''ı bilgilendireceğini onayla. Unruly passenger durumunu, olası restraint ihtiyacını ve kabin''e gelmesini istediğini aktar.","expectedReadback":"Wilco, notifying captain of unruly passenger, possible restraint, requesting his presence in cabin.","frequency":null,"hintTr":"Kaptan''a durumu tam ve net bildir.","id":"turn-2","isFinal":false,"keyPhrases":[["wilco","roger","copy"],["notifying","informing","advising","contacting"],["captain","commander"],["unruly passenger","disruptive passenger","unruly pax"],["restraint","restrain"],["requesting","request"],["presence","come","attend"]],"hint":{"text_tr":"Cabin Chief''in talebini wilco ile onayla. Sonra Captain''a unruly passenger durumunu, restraint gerekebileceğini ve cabin''e gelmesini isteyeceğini söyle.","text_en":"Acknowledge the Cabin Chief''s request with wilco. Then state you will inform the Captain of the unruly passenger, possible restraint needed, and request his presence in cabin."},"expected_response":{"text_en":"Wilco, notifying captain of unruly passenger, possible restraint required, requesting his presence in cabin.","text_tr":"Yerine getireceğim, Kaptan''a unruly passenger durumunu ve olası restraint ihtiyacını bildiriyorum, cabin''e gelmesini istiyorum.","must_include":["wilco","roger","notifying","informing","captain","unruly passenger","disruptive","restraint","requesting","presence","cabin"]},"vocabulary_focus":["unruly passenger","restraint","presence in cabin"]},{"atcStation":"CAPTAIN","atcUtterance":"Cabin crew, captain here. Confirm passenger is restrained and no immediate threat to flight safety. I will file a report and notify authorities at destination.","correctionTr":"Kaptan''a yolcunun restraint edildiğini ve uçuş güvenliğine tehdit olmadığını onayla. Teşekkür et veya onay ver.","expectedReadback":"Affirmative captain, passenger restrained, no immediate threat to flight safety, thank you.","frequency":null,"hintTr":"Durumu Kaptan''a net bir şekilde onayla.","id":"turn-3","isFinal":true,"keyPhrases":[["affirmative","affirm","confirmed","roger","correct"],["captain"],["passenger restrained","restrained","secured"],["no threat","no immediate threat","safe","flight safety"],["thank you","copy"]],"hint":{"text_tr":"Captain''a durumu affirmative ile onayla. Yolcunun restraint edildiğini ve flight safety''ye tehdit olmadığını net bir şekilde söyle.","text_en":"Confirm the situation to the Captain with affirmative. Clearly state the passenger is restrained and poses no threat to flight safety."},"expected_response":{"text_en":"Affirmative captain, passenger restrained, no immediate threat to flight safety, thank you.","text_tr":"Onaylıyorum Kaptan, yolcu restraint edildi, uçuş güvenliğine acil tehdit yok, teşekkür ederim.","must_include":["affirmative","affirm","confirmed","captain","restrained","secured","no threat","flight safety","thank you"]},"vocabulary_focus":["affirmative","restraint","flight safety"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'unruly-passenger-cabin-crew-coordination';

UPDATE public.scenarios SET
  briefing = '{"tr":"İstanbul Approach''ta inbound bir A321''i (Turkish 1453, Atina''dan geliyor) runway 35L ILS''ine vectoring yapacaksın. Uçak descent''te, sırayla heading, speed ve altitude change''leri verip localizer''a intercept ettirmen gerekiyor.","en":"You are Istanbul Approach controlling an inbound A321 (Turkish 1453 from Athens) for ILS runway 35L. The aircraft is descending and you will issue vectors, speed restrictions, and altitude changes to intercept the localizer."}'::jsonb,
  learner_role = '{"tr":"Sen İstanbul Approach controller''ısın, Turkish Airlines 1453 (A321) uçağını Atina''dan Istanbul Airport''a ILS runway 35L için vectoring yapıyorsun.","en":"You are the Istanbul Approach controller vectoring Turkish Airlines 1453 (A321) inbound from Athens for ILS runway 35L at Istanbul Airport."}'::jsonb,
  objective = '{"tr":"Uçağı güvenli bir şekilde ILS''e intercept ettirip Tower frekansına geçir.","en":"Safely vector the aircraft to intercept the ILS and hand off to Tower frequency."}'::jsonb,
  key_vocabulary = '[{"term":"vectoring","definition_tr":"Pilota belirli bir heading vermek suretiyle uçağı istenen rotaya veya approach''a yönlendirme işlemi","definition_en":"Guiding an aircraft by issuing specific headings to position it for an approach or route"},{"term":"ILS (Instrument Landing System)","definition_tr":"Localizer ve glideslope sinyalleriyle uçağı pist merkezine ve doğru iniş açısına yönlendiren hassas yaklaşma sistemi","definition_en":"Precision approach system using localizer and glideslope signals to guide aircraft to runway centerline and correct descent path"},{"term":"localizer","definition_tr":"ILS''in yatay yönlendirme sinyali; uçağı pist merkez hattına hizalar","definition_en":"Horizontal guidance component of ILS that aligns aircraft with runway centerline"},{"term":"QNH","definition_tr":"Deniz seviyesine indirgenmiş atmosferik basınç değeri; altimetre ayarı için kullanılır","definition_en":"Atmospheric pressure reduced to sea level; used for altimeter setting"},{"term":"intercept","definition_tr":"Uçağın bir radyal, localizer veya flight path''i kesmesi veya ona katılması","definition_en":"Aircraft joining or crossing a radial, localizer, or flight path"},{"term":"cleared ILS approach","definition_tr":"Pilot''a ILS prosedürünü uygulayarak iniş yapma izni verilmesi","definition_en":"Authorization for the pilot to execute the ILS procedure for landing"},{"term":"reduce speed","definition_tr":"Pilot''tan hızını belirtilen değere düşürmesini istemek (genellikle knot cinsinden)","definition_en":"Instruction for pilot to decrease airspeed to a specified value (typically in knots)"},{"term":"contact Tower","definition_tr":"Pilot''a bir sonraki frekansa (genellikle Tower) geçmesi talimatı","definition_en":"Instruction for pilot to switch to the next frequency (usually Tower)"}]'::jsonb,
  estimated_duration_seconds = 180,
  turns = '[{"atcStation":"TURKISH 1453","atcUtterance":"Istanbul Approach, Turkish 1453, passing flight level one zero zero, descending to seven thousand feet.","correctionTr":"Uçağı dört bin feet''e indirme talimatı verin ve QNH değerini bildirin. ''Continue descent to four thousand feet, QNH one zero one three'' deyin.","expectedReadback":"Turkish 1453, Istanbul Approach, roger, continue descent to four thousand feet, QNH one zero one three.","frequency":"119.1","hintTr":"Pilot iniş bilgisi veriyor, siz yeni irtifa ve basınç değeri verin.","id":"turn-1","isFinal":false,"keyPhrases":[["Turkish 1453","Turkish fourteen fifty-three"],["continue descent","descend","continue descending"],["four thousand","4000"],["QNH","altimeter"],["one zero one three","1013"]],"hint":{"text_tr":"Pilot descent bilgisi veriyor. Sen şimdi yeni bir altitude ve QNH değerini ver. Standart format: ''Continue descent to [altitude], QNH [value]''","text_en":"Pilot is reporting descent. Issue a new altitude and QNH. Standard format: ''Continue descent to [altitude], QNH [value]''"},"expected_response":{"text_en":"Turkish 1453, continue descent to four thousand feet, QNH one zero one three","text_tr":"Uçağı 4000 feet''e indirme ve basınç değerini (QNH 1013) bildirme talimatı","must_include":["turkish 1453","turkish fourteen fifty-three","continue descent","descend","four thousand","4000","qnh","one zero one three","1013"]},"vocabulary_focus":["QNH","continue descent","altitude"]},{"atcStation":"TURKISH 1453","atcUtterance":"Continue descent four thousand, QNH one zero one three, Turkish 1453.","correctionTr":"Uçağı sola 310 heading''e döndürün, hızı 180 knot''a düşürmesini isteyin ve ILS runway 35L için vectoring yaptığınızı bildirin. Örnek: ''Turn left heading three one zero, reduce speed to one eight zero knots, vectors for ILS runway three five left.''","expectedReadback":"Turkish 1453, turn left heading three one zero, reduce speed to one eight zero knots, vectors for ILS runway three five left.","frequency":"119.1","hintTr":"Şimdi pilotu ILS''e yönlendirin: heading, hız azaltma ve amaç.","id":"turn-2","isFinal":false,"keyPhrases":[["Turkish 1453","Turkish fourteen fifty-three"],["turn left","left turn"],["heading three one zero","heading 310"],["reduce speed","reduce to","speed"],["one eight zero","180","one eighty"],["knots"],["vectors","vectoring"],["ILS"],["runway three five left","three five left","35L"]],"hint":{"text_tr":"Pilot hazır, şimdi vectoring başlat: heading ver (310), hız azaltma iste (180 knot) ve ILS runway 35L için vectoring yaptığını belirt.","text_en":"Pilot is ready. Start vectoring: issue heading (310), request speed reduction (180 knots), and state you are vectoring for ILS runway 35L."},"expected_response":{"text_en":"Turkish 1453, turn left heading three one zero, reduce speed to one eight zero knots, vectors for ILS runway three five left","text_tr":"Sola 310 derece dönüş, 180 knot''a hız düşürme ve ILS runway 35L için vectoring yapıldığını bildirme","must_include":["turkish 1453","turkish fourteen fifty-three","turn left","left turn","heading three one zero","heading 310","reduce speed","reduce to","one eight zero","180","one eighty","knots","vectors","vectoring","ils","runway three five left","three five left","35l"]},"vocabulary_focus":["vectoring","heading","reduce speed","ILS"]},{"atcStation":"TURKISH 1453","atcUtterance":"Left heading three one zero, reducing to one eight zero knots, Turkish 1453.","correctionTr":"Son heading''i verin (285), localizer''ı kesmesini söyleyin, ILS yaklaşmasını onaylayın ve Kule frekansına geçirmek için ''contact Istanbul Tower on 118.1'' deyin.","expectedReadback":"Turkish 1453, turn left heading two eight five, intercept localizer runway three five left, cleared ILS approach runway three five left, contact Istanbul Tower on one one eight decimal one.","frequency":"119.1","hintTr":"Final vectoring talimatı: heading, localizer intercept, clearance ve frekans değişikliği.","id":"turn-3","isFinal":true,"keyPhrases":[["Turkish 1453","Turkish fourteen fifty-three"],["turn left","left turn"],["heading two eight five","heading 285"],["intercept localizer","intercept"],["runway three five left","three five left","35L"],["cleared ILS approach","cleared ILS","cleared for ILS"],["contact"],["Istanbul Tower","Tower"],["one one eight decimal one","one one eight point one","118.1"]],"hint":{"text_tr":"Son turn: heading 285 ver, localizer''ı intercept etmesini söyle, ILS approach''ı clear et ve Tower frekansına (118.1) geçirmek için ''contact Istanbul Tower'' de.","text_en":"Final turn: issue heading 285, instruct to intercept localizer, clear ILS approach, and hand off to Tower frequency (118.1) with ''contact Istanbul Tower''."},"expected_response":{"text_en":"Turkish 1453, turn left heading two eight five, intercept localizer runway three five left, cleared ILS approach runway three five left, contact Istanbul Tower on one one eight decimal one","text_tr":"Sola 285 heading, localizer''ı intercept etme, ILS yaklaşması clearance ve Tower frekansına (118.1) geçiş talimatı","must_include":["turkish 1453","turkish fourteen fifty-three","turn left","left turn","heading two eight five","heading 285","intercept","localizer","runway three five left","three five left","35l","cleared ils approach","cleared ils","ils approach","contact","istanbul tower","tower","one one eight decimal one","118.1"]},"vocabulary_focus":["intercept","localizer","cleared ILS approach","contact Tower"]}]'::jsonb,
  updated_at = now()
