UPDATE public.scenarios SET
  briefing = '{"tr":"Turkish 1453 Atina''ya uçarken şiddetli thunderstorm''la karşılaştı ve diversion gerekiyor. Sen dispatcher olarak crew ile alternate routing, fuel planning ve ground coordination yapacaksın.","en":"Turkish 1453 en route to Athens encounters severe thunderstorms requiring diversion. As dispatcher you will coordinate alternate routing, fuel planning, and ground services with the crew."}'::jsonb,
  learner_role = '{"tr":"Sen Turkish Airlines dispatcher olarak Turkish 1453 (B737-800) için weather diversion koordinasyonu yapıyorsun.","en":"You are a Turkish Airlines dispatcher coordinating weather diversion for Turkish 1453 (B737-800)."}'::jsonb,
  objective = '{"tr":"Crew ile güvenli şekilde alternate airport seçimi, fuel status kontrolü ve ground services koordinasyonunu tamamla.","en":"Complete safe alternate airport selection, fuel status verification, and ground services coordination with the crew."}'::jsonb,
  key_vocabulary = '[{"term":"diversion","definition_tr":"Planlanan havalimanı yerine alternatif bir havalimanına yönlenme","definition_en":"Rerouting to an alternate airport instead of the planned destination"},{"term":"severe cell","definition_tr":"Radar''da görünen şiddetli hava olayı (thunderstorm, yağış alanı)","definition_en":"Intense weather phenomenon visible on radar (thunderstorm, precipitation area)"},{"term":"holding","definition_tr":"Havada bekleme yapma durumu, genellikle dakika cinsinden hesaplanır","definition_en":"Airborne waiting pattern, typically calculated in minutes of fuel"},{"term":"slot time","definition_tr":"Havalimanında verilen iniş veya kalkış zaman aralığı","definition_en":"Assigned time window for landing or departure at an airport"},{"term":"turnaround","definition_tr":"Uçağın inişten sonra tekrar kalkışa hazır hale getirilmesi süreci","definition_en":"Process of preparing aircraft for next departure after landing"},{"term":"ground services","definition_tr":"Yer hizmetleri (yakıt, bagaj, catering, temizlik vb.)","definition_en":"Ground handling services (fuel, baggage, catering, cleaning, etc.)"},{"term":"wilco","definition_tr":"Will comply - talimatı anlayıp uygulayacağını belirtme","definition_en":"Will comply - acknowledgment that instruction is understood and will be executed"},{"term":"METAR","definition_tr":"Havalimanı hava durumu raporu (görüş, rüzgar, bulut, sıcaklık)","definition_en":"Meteorological Aerodrome Report (visibility, wind, clouds, temperature)"}]'::jsonb,
  estimated_duration_seconds = 180,
  turns = '[{"atcStation":"TURKISH 1453 CAPTAIN","atcUtterance":"Turkish 1453, we have weather radar showing severe cell direct course, request diversion options and fuel status from dispatch.","correctionTr":"Kaptan''a hava durumunu kontrol ettiğinizi, Izmir''e diversion önerdiğinizi, yakıtın Izmir artı 45 dakika holding için yeterli olduğunu söyleyin ve niyetini sorun. ''Roger, checking weather, recommend divert Izmir, fuel sufficient for Izmir plus 45 minutes holding, advise intentions'' diyebilirsiniz.","expectedReadback":"Turkish 1453, roger, checking weather. Recommend divert to Izmir, current fuel sufficient for Izmir plus 45 minutes holding, advise intentions.","frequency":"131.3","hintTr":"Dispatcher olarak alternatifleri hızlıca değerlendirip Kaptan''a net öneri sunun.","id":"turn-1","isFinal":false,"keyPhrases":[["roger","copied","affirm"],["checking weather","weather check","reviewing weather"],["recommend","suggest","advise"],["divert","alternate","diversion"],["Izmir","LTFJ"],["fuel sufficient","fuel adequate","enough fuel"],["45 minutes","four five minutes"],["holding","hold"],["advise intentions","request intentions","your intentions"]],"hint":{"text_tr":"Dispatcher olarak önce durumu kabul et (roger), sonra hava durumunu kontrol ettiğini belirt, Izmir''i alternate olarak öner ve mevcut yakıtın Izmir artı 45 dakika holding için yeterli olduğunu söyle. Son olarak captain''ın niyetini sor.","text_en":"As dispatcher, first acknowledge (roger), confirm checking weather, recommend Izmir as alternate, state fuel is sufficient for Izmir plus 45 minutes holding, then request captain''s intentions."},"expected_response":{"text_en":"Turkish 1453, roger, checking weather. Recommend divert to Izmir, current fuel sufficient for Izmir plus 45 minutes holding, advise intentions.","text_tr":"Önce durumu kabul et, hava kontrol ettiğini söyle, Izmir''e diversion öner, yakıtın yeterli olduğunu belirt ve captain''ın kararını sor.","must_include":["roger","checking weather","recommend","divert","izmir","fuel sufficient","45 minutes","holding","advise intentions"]},"vocabulary_focus":["diversion","severe cell","holding"]},{"atcStation":"TURKISH 1453 CAPTAIN","atcUtterance":"Affirm, proceeding Izmir. Request you coordinate slot time and notify ground services for immediate turnaround.","correctionTr":"Kaptan''ın talebini onaylayın ve Izmir slot koordinasyonu ile yer hizmetlerini hemen ayarlayacağınızı, slot bilgisini kısa sürede vereceğinizi belirtin. ''Wilco, coordinating Izmir slot and ground services now, will advise slot time shortly'' şeklinde cevap verin.","expectedReadback":"Wilco, coordinating Izmir slot and ground services now, will advise slot time shortly, Turkish 1453.","frequency":"131.3","hintTr":"OCC ile koordinasyon başlattığınızı ve kısa sürede bilgi vereceğinizi bildirin.","id":"turn-2","isFinal":false,"keyPhrases":[["wilco","will comply","roger wilco"],["coordinating","coordinate","arranging"],["Izmir slot","slot","slot time"],["ground services","handling","ground handling"],["now","immediately"],["advise","confirm","update"],["shortly","soon","momentarily"],["Turkish 1453","1453"]],"hint":{"text_tr":"Captain''ın talebini kabul et (wilco), Izmir slot koordinasyonunu ve ground services''i şimdi ayarladığını belirt, slot bilgisini kısa sürede vereceğini söyle.","text_en":"Acknowledge captain''s request (wilco), confirm coordinating Izmir slot and ground services now, advise slot time will follow shortly."},"expected_response":{"text_en":"Wilco, coordinating Izmir slot and ground services now, will advise slot time shortly, Turkish 1453.","text_tr":"Talimatı uygulayacağını belirt, slot ve yer hizmetlerini şimdi koordine ettiğini söyle, kısa sürede slot zamanını bildireceğini ekle.","must_include":["wilco","coordinating","izmir slot","ground services","now","advise","shortly"]},"vocabulary_focus":["slot time","ground services","turnaround","wilco"]},{"atcStation":"OPERATIONS CENTER","atcUtterance":"Dispatch, Izmir slot confirmed in 35 minutes, ground crew standing by, METAR shows VFR conditions, runway 16 in use.","correctionTr":"Operasyon''dan gelen slot, yer ekibi ve hava durumu bilgisini onaylayın ve ekibe ileteceğinizi belirtin. ''Roger operations, relaying to Turkish 1453, slot 35 minutes, ground ready, VFR conditions runway 16'' deyin.","expectedReadback":"Roger operations, relaying to Turkish 1453, slot 35 minutes, ground ready, VFR conditions runway 16, thanks.","frequency":"ACARS","hintTr":null,"id":"turn-3","isFinal":true,"keyPhrases":[["roger","copied","received"],["operations","ops","OCC"],["relaying","passing","advising"],["Turkish 1453","1453","crew"],["slot 35 minutes","three five minutes","35 minutes"],["ground ready","ground standing by","ground crew ready"],["VFR","VFR conditions"],["runway 16","runway one six","RWY 16"],["thanks","thank you"]],"hint":{"text_tr":"Operations''dan gelen tüm bilgileri onayla (roger operations), ekibe ileteceğini belirt: slot 35 dakika içinde, ground crew hazır, VFR conditions ve runway 16 kulımda.","text_en":"Acknowledge all information from operations (roger operations), confirm relaying to crew: slot in 35 minutes, ground crew ready, VFR conditions, runway 16 in use."},"expected_response":{"text_en":"Roger operations, relaying to Turkish 1453, slot 35 minutes, ground crew standing by, VFR conditions, runway 16.","text_tr":"Operations''ı onayla, ekibe ileteceğini söyle: slot 35 dakika, yer ekibi hazır, VFR koşullar, pist 16.","must_include":["roger","operations","relaying","turkish 1453","slot","35 minutes","ground crew","vfr","runway 16"]},"vocabulary_focus":["METAR","ground services","slot time"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'weather-diversion-coordination-severe-tstm';

UPDATE public.scenarios SET
  briefing = '{"tr":"Turkish 1453, Istanbul''dan Ankara''ya uçuş sırasında varış noktasında şiddetli thunderstorm nedeniyle Ankara''ya iniş yapamaz durumda. Hava koşulları güvenli approach''a izin vermiyor, Antalya''ya diversion planlanıyor.","en":"Turkish 1453 en route from Istanbul to Ankara encounters severe thunderstorms over the destination, preventing safe approach. You must request diversion to Antalya due to weather conditions."}'::jsonb,
  learner_role = '{"tr":"Sen Turkish 1453 callsign''ı ile uçan pilot olarak Ankara Approach ile iletişime geçip hava durumu nedeniyle Antalya''ya diversion talep ediyorsun.","en":"You are the pilot of Turkish 1453 communicating with Ankara Approach to request diversion to Antalya due to weather conditions."}'::jsonb,
  objective = '{"tr":"Hava durumu nedeniyle güvenli bir şekilde alternate havaalanına diversion yaparak uçuşu tamamlamak.","en":"Complete the flight by safely diverting to an alternate airport due to weather conditions."}'::jsonb,
  key_vocabulary = '[{"term":"diversion","definition_tr":"Planlanan varış noktası dışında bir havaalanına yönlenme","definition_en":"Redirecting to an airport other than the planned destination"},{"term":"unable","definition_tr":"Clearance veya talimatı yerine getirememe durumu","definition_en":"Cannot comply with a clearance or instruction"},{"term":"severe weather","definition_tr":"Uçuş güvenliğini tehdit eden ciddi hava koşulları (thunderstorm, icing vb.)","definition_en":"Serious weather conditions threatening flight safety (thunderstorm, icing, etc.)"},{"term":"flight level","definition_tr":"Standart basınç ayarında (29.92 inHg) yüzlerce feet cinsinden irtifa","definition_en":"Altitude in hundreds of feet using standard pressure setting (29.92 inHg)"},{"term":"heading","definition_tr":"Uçağın manyetik kuzeye göre yönü (derece olarak)","definition_en":"Aircraft direction relative to magnetic north (in degrees)"},{"term":"vectors","definition_tr":"ATC tarafından verilen heading talimatları ile yönlendirme","definition_en":"Guidance by heading instructions provided by ATC"},{"term":"ILS approach","definition_tr":"Instrument Landing System ile yapılan hassas iniş yaklaşması","definition_en":"Precision landing approach using Instrument Landing System"},{"term":"alternate airport","definition_tr":"Ana havaalanına iniş yapılamadığında kullanılan yedek havaalanı","definition_en":"Backup airport used when landing at the primary airport is not possible"}]'::jsonb,
  estimated_duration_seconds = 180,
  turns = '[{"atcStation":"ANKARA APPROACH","atcUtterance":"Turkish 1453, Ankara Approach, descend to flight level one four zero, expect ILS runway zero three left.","correctionTr":"Approach''a iniş yapamayacağınızı hava durumu nedeniyle bildirip Antalya''ya diversion talep edin. ''Unable due to weather, request diversion to Antalya'' deyin.","expectedReadback":"Ankara Approach, Turkish 1453, unable due to weather, request diversion to Antalya.","frequency":"119.1","hintTr":"Hava koşulları güvenli iniş yapmaya uygun değil, alternatif havaalanı talep edin.","id":"turn-1","isFinal":false,"keyPhrases":[["unable","unable to comply","cannot"],["weather","thunderstorm","severe weather"],["request diversion","divert","alternate"],["Antalya"]],"hint":{"text_tr":"Ankara''daki thunderstorm nedeniyle approach yapamayacağını bildir ve Antalya''ya diversion talep et. ''Unable due to weather'' ile başla.","text_en":"Report inability to approach due to thunderstorms over Ankara and request diversion to Antalya. Start with ''Unable due to weather''."},"expected_response":{"text_en":"Ankara Approach, Turkish 1453, unable due to weather, request diversion to Antalya.","text_tr":"Hava durumu nedeniyle iniş yapamayacağını bildirip Antalya''ya yönlenme talebinde bulun.","must_include":["unable","weather","request diversion","divert","antalya","alternate"]},"vocabulary_focus":["unable","diversion","severe weather","alternate airport"]},{"atcStation":"ANKARA APPROACH","atcUtterance":"Turkish 1453, roger, diversion approved. Climb to flight level two zero zero, turn right heading one eight zero, contact Antalya Control on one two four decimal six five.","correctionTr":"Talimatları tam readback yapın: Yükseliş seviyesi FL200, sağa dönüş heading 180, Antalya Control frekansı 124.65. Örnek: ''Climb FL200, right heading 180, contact Antalya 124.65, Turkish 1453''.","expectedReadback":"Climb flight level two zero zero, right heading one eight zero, contact Antalya one two four decimal six five, Turkish 1453.","frequency":"119.1","hintTr":"Clearance''ı eksiksiz tekrarlayın: irtifa, heading ve yeni frekans.","id":"turn-2","isFinal":false,"keyPhrases":[["climb","climbing"],["flight level two zero zero","FL200","two zero zero"],["right","turn right"],["heading one eight zero","one eight zero","180"],["Antalya","one two four decimal six five","124.65"]],"hint":{"text_tr":"Diversion onaylandı. Tüm clearance''ı sırayla readback yap: FL200''e climb, heading 180 sağa dön, Antalya Control 124.65''i ara.","text_en":"Diversion approved. Read back the full clearance in order: climb to FL200, turn right heading 180, contact Antalya Control 124.65."},"expected_response":{"text_en":"Climb flight level two zero zero, right heading one eight zero, contact Antalya one two four decimal six five, Turkish 1453.","text_tr":"Tüm talimatları eksiksiz tekrarla: yükseliş, heading değişikliği ve frekans.","must_include":["climb","flight level two zero zero","fl200","right","heading one eight zero","180","antalya","one two four decimal six five","124.65"]},"vocabulary_focus":["flight level","heading","vectors"]},{"atcStation":"ANTALYA CONTROL","atcUtterance":"Turkish 1453, Antalya Control, identified, descend to flight level one six zero, expect vectors for ILS runway zero two right, weather at Antalya, wind zero three zero degrees at one five knots, visibility one zero kilometers, few clouds at three thousand feet.","correctionTr":"Antalya Control''ün talimatını onaylayın: İniş FL160''a, ILS runway 02R için vectors bekleyin. Örnek: ''Descend FL160, expect vectors ILS 02R, Turkish 1453''.","expectedReadback":"Descend flight level one six zero, expect vectors ILS zero two right, Turkish 1453.","frequency":"124.65","hintTr":"Yeni approach clearance''ını kısa ve net readback edin.","id":"turn-3","isFinal":true,"keyPhrases":[["descend","descending"],["flight level one six zero","FL160","one six zero"],["expect vectors","vectors"],["ILS","ILS approach"],["zero two right","runway zero two right","02R"]],"hint":{"text_tr":"Antalya Control ile iletişime geçtin. İniş talimatını onayla: FL160''a in, ILS 02R için vectors bekle.","text_en":"Now in contact with Antalya Control. Acknowledge descent clearance: descend to FL160, expect vectors for ILS 02R."},"expected_response":{"text_en":"Descend flight level one six zero, expect vectors ILS zero two right, Turkish 1453.","text_tr":"İniş seviyesi ve ILS approach planını kısaca onayla.","must_include":["descend","flight level one six zero","fl160","one six zero","expect vectors","vectors","ils","zero two right","02r"]},"vocabulary_focus":["ILS approach","vectors","flight level"]}]'::jsonb,
  updated_at = now()
WHERE slug = 'weather-diversion-request-b2';
COMMIT;
